const HCI_QUESTIONS_DATA = {"subject": "\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u0627\u0633\u0648\u0628", "sections": [{"id": "hci-lecture-1", "title": "\u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0627\u0644\u0623\u0648\u0644\u0649", "questions": [{"id": "hci-lecture-1-q1", "number": 1, "text": "\u064a\u0631\u0643\u0632 \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0628\u064a\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u0627\u0633\u0648\u0628 (HCI) \u062d\u0635\u0631\u0627\u064b \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u062a\u0642\u0646\u064a \u0648\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0635\u0644\u0628\u0629 (Hardware).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q2", "number": 2, "text": "\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062a\u0641\u0627\u0639\u0644 (Interaction Model) \u064a\u0647\u062f\u0641 \u0644\u0641\u0647\u0645 \"\u0627\u0644\u062a\u0631\u062c\u0645\u0629\" \u0628\u064a\u0646 \u0645\u0627 \u064a\u0631\u064a\u062f\u0647 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0645\u0627 \u064a\u0641\u0639\u0644\u0647 \u0627\u0644\u0646\u0638\u0627\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q3", "number": 3, "text": "\u0645\u0628\u062f\u0623 \"\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0628\u0643\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0627\u0644\u0645\u0647\u0627\u0645\" \u064a\u0639\u0646\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0623\u0648\u0644\u0627\u064b \u062b\u0645 \u0627\u062e\u062a\u0628\u0627\u0631\u0647 \u0645\u0639 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u064a \u0627\u0644\u0646\u0647\u0627\u064a\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q4", "number": 4, "text": "\u0648\u0627\u062c\u0647\u0629 \u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 (Command Line Interface) \u062a\u062a\u0645\u064a\u0632 \u0628\u0643\u0648\u0646\u0647\u0627 \u0633\u0647\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q5", "number": 5, "text": "\u0646\u0645\u0637 \"\u0645\u0644\u0621 \u0627\u0644\u0646\u0645\u0627\u0630\u062c\" (Form-fills) \u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u062e\u0628\u0631\u0627\u0621 \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u063a\u064a\u0631 \u0627\u0644\u062e\u0628\u0631\u0627\u0621.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q6", "number": 6, "text": "\u0641\u064a \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0648\u0638\u064a\u0641\u064a\" (Functional Arrangement)\u060c \u064a\u062a\u0645 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0645\u062f\u0649 \u062a\u0643\u0631\u0627\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q7", "number": 7, "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 (Interaction Design) \u064a\u0642\u062a\u0635\u0631 \u0639\u0644\u0649 \u062a\u0635\u0645\u064a\u0645 \u0634\u0643\u0644 \u0627\u0644\u0623\u0632\u0631\u0627\u0631 \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q8", "number": 8, "text": "\u0627\u0644\u0628\u0639\u062f \u0627\u0644\u0631\u0627\u0628\u0639 \u0641\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0647\u0648 \"\u0627\u0644\u0633\u0644\u0648\u0643\" (Behavior).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q9", "number": 9, "text": "\u0645\u0628\u062f\u0623 \"\u0627\u0644\u0642\u0627\u0628\u0644\u064a\u0629 \u0644\u0644\u062a\u0646\u0628\u0624\" (Predictable) \u064a\u0639\u0646\u064a \u0623\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u0645\u0643\u0646\u0647 \u062a\u0648\u0642\u0639 \u0645\u0627 \u0633\u064a\u062d\u062f\u062b \u0642\u0628\u0644 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0625\u062c\u0631\u0627\u0621.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q10", "number": 10, "text": "\"\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629\" (Feedback) \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u062a\u0639\u0646\u064a \u062a\u0648\u0642\u0639 \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0645\u0646\u0639\u0647\u0627 \u0645\u0633\u0628\u0642\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q11", "number": 11, "text": "\u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u062e\u0637\u064a\u0629 (Linear)\u060c \u062d\u064a\u062b \u0646\u0646\u062a\u0642\u0644 \u0645\u0646 \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0644\u0644\u062a\u0635\u0645\u064a\u0645 \u0644\u0644\u062a\u0646\u0641\u064a\u0630 \u062f\u0648\u0646 \u0631\u062c\u0648\u0639.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q12", "number": 12, "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a (Visual Design) \u064a\u0623\u062a\u064a \u0642\u0628\u0644 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0641\u064a \u0645\u0631\u0627\u062d\u0644 \u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q13", "number": 13, "text": "\"\u0627\u0644\u0642\u064a\u0627\u0633 \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a\" (Empirical Measurement) \u064a\u062a\u0637\u0644\u0628 \u062a\u062d\u062f\u064a\u062f \u0623\u0647\u062f\u0627\u0641 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0642\u064a\u0627\u0633 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q14", "number": 14, "text": "\u0646\u0645\u0637 \"\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a\" (Instructing) \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0625\u062c\u0631\u0627\u0621 \u0645\u062d\u0627\u062f\u062b\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0627\u0644\u0646\u0638\u0627\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q15", "number": 15, "text": "\"\u0627\u0644\u0625\u062f\u0631\u0627\u0643\" (Perceivability) \u064a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062a\u0644\u0645\u064a\u062d\u0627\u062a \u0645\u0631\u0626\u064a\u0629 \u062a\u0633\u0627\u0639\u062f\u0647 \u0641\u064a \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0641\u0631\u0635 \u0627\u0644\u062a\u0641\u0627\u0639\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q16", "number": 16, "text": "\u0627\u0644\u0627\u062a\u0633\u0627\u0642 (Consistency) \u064a\u0642\u0644\u0644 \u0645\u0646 \u0639\u0628\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q17", "number": 17, "text": "\"\u062d\u0648\u0627\u0631 \u0627\u0644\u0633\u0624\u0627\u0644 \u0648\u0627\u0644\u062c\u0648\u0627\u0628\" (Question/Answer Dialog) \u064a\u062a\u0645\u064a\u0632 \u0628\u0642\u0648\u062a\u0647 \u0648\u0645\u0631\u0648\u0646\u062a\u0647 \u0627\u0644\u0639\u0627\u0644\u064a\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q18", "number": 18, "text": "\u0641\u064a \u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a (Sequential Arrangement)\u060c \u064a\u062a\u0645 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u062e\u0637\u0648\u0627\u062a \u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0645\u0647\u0645\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q19", "number": 19, "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a \u0644\u0627 \u064a\u0624\u062b\u0631 \u0639\u0644\u0649 \u062b\u0642\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u064a \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q20", "number": 20, "text": "\u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0648\u0627\u0644\u0646\u0634\u0631\" (Implementation) \u062a\u062a\u0636\u0645\u0646 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f \u0648\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0646\u0638\u0627\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q21", "number": 21, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0645\u0646 \u0645\u0628\u062f\u0623 \"\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0628\u0643\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0627\u0644\u0645\u0647\u0627\u0645\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0642\u0644\u064a\u0644 \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u062a\u0637\u0648\u064a\u0631."}, {"key": "B", "text": "\u0628\u0646\u0627\u0621 \u0627\u0644\u0646\u0638\u0627\u0645 \u0623\u0648\u0644\u0627\u064b \u062b\u0645 \u062a\u0639\u062f\u064a\u0644\u0647 \u0644\u0627\u062d\u0642\u0627\u064b."}, {"key": "C", "text": "\u0641\u0647\u0645 \u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0633\u0644\u0648\u0643\u0647\u0645 \u0642\u0628\u0644 \u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "D", "text": "\u0625\u062c\u0628\u0627\u0631 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062a\u0643\u064a\u0641 \u0645\u0639 \u0627\u0644\u0646\u0638\u0627\u0645."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q22", "number": 22, "text": "\u0623\u064a \u0645\u0646 \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u063a\u064a\u0631 \u0627\u0644\u062e\u0628\u0631\u0627\u0621 (Non-experts)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 (Command Line)."}, {"key": "B", "text": "\u0644\u063a\u0627\u062a \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0645\u0631\u0643\u0628\u0629."}, {"key": "C", "text": "\u0645\u0644\u0621 \u0627\u0644\u0646\u0645\u0627\u0630\u062c (Form-fills)."}, {"key": "D", "text": "\u0627\u0644\u0646\u0648\u0627\u0641\u0630 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 (Direct Manipulation) \u0627\u0644\u0645\u0639\u0642\u062f\u0629."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q23", "number": 23, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u062c\u0648\u0647\u0631\u064a \u0628\u064a\u0646 \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0648\u0638\u064a\u0641\u064a\" \u0648\"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0648\u0638\u064a\u0641\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0647\u0645\u064a\u0629."}, {"key": "B", "text": "\u0627\u0644\u0648\u0638\u064a\u0641\u064a \u064a\u062c\u0645\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0630\u0627\u062a \u0627\u0644\u063a\u0631\u0636 \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a \u064a\u062a\u0628\u0639 \u062a\u0631\u062a\u064a\u0628 \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u0639\u0645\u0644."}, {"key": "C", "text": "\u0627\u0644\u0648\u0638\u064a\u0641\u064a \u0644\u0644\u062e\u0628\u0631\u0627\u0621\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a \u0644\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u0631\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q24", "number": 24, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \u0627\u0644\u0628\u0639\u062f \u0627\u0644\u062e\u0627\u0645\u0633 \"\u0627\u0644\u0633\u0644\u0648\u0643\" (Behavior) \u0641\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0634\u0643\u0644 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u0631\u062f\u0648\u062f \u0641\u0639\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "C", "text": "\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0629 \u0641\u064a \u062a\u0635\u0646\u064a\u0639 \u0627\u0644\u062c\u0647\u0627\u0632."}, {"key": "D", "text": "\u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u0632\u0645\u0646\u064a\u0629 \u0644\u0644\u062a\u0641\u0627\u0639\u0644."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q25", "number": 25, "text": "\u0625\u0630\u0627 \u0642\u0627\u0645 \u0645\u0635\u0645\u0645 \u0628\u062c\u0639\u0644 \u0632\u0631 \"\u0627\u0644\u062d\u0630\u0641\" \u0628\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u062d\u0645\u0631 \u0648\u0634\u0643\u0644\u0647 \u064a\u0648\u062d\u064a \u0628\u0627\u0644\u062e\u0637\u0631\u060c \u0641\u0623\u064a \u0645\u0628\u062f\u0623 \u062a\u0635\u0645\u064a\u0645\u064a \u064a\u0637\u0628\u0642\u0647\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0627\u062a\u0633\u0627\u0642 (Consistency)."}, {"key": "B", "text": "\u0627\u0644\u0625\u062f\u0631\u0627\u0643 (Perceivability)."}, {"key": "C", "text": "\u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 (Learnability)."}, {"key": "D", "text": "\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 (Feedback)."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q26", "number": 26, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u064a \u062a\u0644\u064a \"\u0627\u0644\u062a\u062d\u0644\u064a\u0644\" \u0645\u0628\u0627\u0634\u0631\u0629 \u0641\u064a \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a."}, {"key": "B", "text": "\u0627\u0644\u062a\u0646\u0641\u064a\u0630."}, {"key": "C", "text": "\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629."}, {"key": "D", "text": "\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q27", "number": 27, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u0627\u062a\u0633\u0627\u0642\" (Consistency) \u0645\u0647\u0645\u0627\u064b \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0648\u0627\u062c\u0647\u0627\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u062c\u0639\u0644 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u062a\u0628\u062f\u0648 \u0645\u0645\u0644\u0629."}, {"key": "B", "text": "\u0644\u062a\u0642\u0644\u064a\u0644 \u0641\u0631\u0635 \u0627\u0631\u062a\u0643\u0627\u0628 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0648\u062a\u0633\u0647\u064a\u0644 \u0646\u0642\u0644 \u0627\u0644\u062e\u0628\u0631\u0629."}, {"key": "C", "text": "\u0644\u0632\u064a\u0627\u062f\u0629 \u0648\u0642\u062a \u0627\u0644\u062a\u0639\u0644\u0645."}, {"key": "D", "text": "\u0644\u062a\u0645\u064a\u064a\u0632 \u0643\u0644 \u0634\u0627\u0634\u0629 \u0639\u0646 \u0627\u0644\u0623\u062e\u0631\u0649 \u062a\u0645\u0627\u0645\u0627\u064b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q28", "number": 28, "text": "\u0623\u064a \u0645\u0645\u0627 \u064a\u0644\u064a \u064a\u0646\u062a\u0645\u064a \u0625\u0644\u0649 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\" (Visual Design) \u0648\u0644\u064a\u0633 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u062d\u062f\u064a\u062f \u062a\u062f\u0641\u0642 \u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642."}, {"key": "B", "text": "\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u062e\u0637\u0648\u0637 (Typography) \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u0646."}, {"key": "C", "text": "\u062a\u062d\u062f\u064a\u062f \u0633\u0644\u0648\u0643 \u0627\u0644\u0623\u0632\u0631\u0627\u0631 \u0639\u0646\u062f \u0627\u0644\u0646\u0642\u0631."}, {"key": "D", "text": "\u0625\u0646\u0634\u0627\u0621 \u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q29", "number": 29, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u064a\" (Iterative Design)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0625\u0637\u0644\u0627\u0642\u0647."}, {"key": "B", "text": "\u0646\u0633\u062e \u062a\u0635\u0645\u064a\u0645 \u0645\u0646\u062a\u062c \u0645\u0646\u0627\u0641\u0633."}, {"key": "C", "text": "\u0639\u0645\u0644\u064a\u0629 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0639\u062f\u0629 \u0645\u0631\u0627\u062a \u0644\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "D", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u062a\u0643\u0631\u0627\u0631 \u0645\u0639\u064a\u0646."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q30", "number": 30, "text": "\u0641\u064a \u0633\u064a\u0627\u0642 \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u060c \u0645\u062a\u0649 \u064a\u064f\u0641\u0636\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \"\u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0645\u0628\u062a\u062f\u0626\u0627\u064b."}, {"key": "B", "text": "\u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0647\u0627\u0645 \u0628\u0633\u064a\u0637\u0629 \u0648\u062a\u062a\u0637\u0644\u0628 \u0645\u0648\u0627\u0641\u0642\u0629 \u0646\u0639\u0645/\u0644\u0627."}, {"key": "C", "text": "\u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062e\u0628\u064a\u0631\u0627\u064b \u0648\u064a\u062d\u062a\u0627\u062c \u0644\u0642\u0648\u0629 \u0648\u062a\u062d\u0643\u0645 \u0645\u0628\u0627\u0634\u0631."}, {"key": "D", "text": "\u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0631\u0633\u0648\u0645\u064a\u0629 \u0648\u0645\u0639\u0642\u062f\u0629."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q31", "number": 31, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0641\u064a \u0646\u0645\u0637 \"\u062d\u0648\u0627\u0631 \u0627\u0644\u0633\u0624\u0627\u0644 \u0648\u0627\u0644\u062c\u0648\u0627\u0628\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u062a\u0639\u0644\u0645."}, {"key": "B", "text": "\u0645\u062d\u062f\u0648\u062f\u064a\u0629 \u0627\u0644\u0648\u0638\u0627\u0626\u0641 \u0648\u0627\u0644\u0642\u0648\u0629."}, {"key": "C", "text": "\u0639\u062f\u0645 \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647 \u0645\u0639 \u0644\u0648\u062d\u0629 \u0627\u0644\u0645\u0641\u0627\u062a\u064a\u062d."}, {"key": "D", "text": "\u062a\u0643\u0644\u0641\u062a\u0647 \u0627\u0644\u0639\u0627\u0644\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q32", "number": 32, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0641\u0631\u0627\u063a\u0627\u062a \u0627\u0644\u0633\u0644\u0628\u064a\u0629\" (Negative Space) \u0641\u064a \u0645\u0628\u0627\u062f\u0626 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0648\u0627\u062c\u0647\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0641\u0631\u0627\u063a\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u0645\u0633\u062a\u063a\u0644\u0629 \u0627\u0644\u062a\u064a \u064a\u062c\u0628 \u0645\u0644\u0624\u0647\u0627."}, {"key": "B", "text": "\u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0627\u0644\u0628\u064a\u0636\u0627\u0621 \u062d\u0648\u0644 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u064a \u062a\u0633\u0627\u0639\u062f \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0632\u0647\u0627 \u0648\u062a\u0631\u062a\u064a\u0628\u0647\u0627."}, {"key": "C", "text": "\u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062f\u0627\u0643\u0646\u0629 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u064a\u0629."}, {"key": "D", "text": "\u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062d\u062f\u062b \u0641\u064a\u0647\u0627 \u0623\u062e\u0637\u0627\u0621."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q33", "number": 33, "text": "\u0623\u064a \u0627\u0644\u0639\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u062a\u0635\u0641 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u062a\u0645\u0631\u0643\u0632 \u062d\u0648\u0644 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0646\u0638\u0627\u0645 \u0647\u0648 \u0645\u062d\u0648\u0631 \u0627\u0644\u0639\u0645\u0644\u064a\u0629."}, {"key": "B", "text": "\u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0647\u064a \u0627\u0644\u062a\u064a \u062a\u062d\u062f\u062f \u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "C", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0647\u0648 \u0645\u062d\u0648\u0631 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0648\u064a\u062c\u0628 \u0641\u0647\u0645 \u0633\u064a\u0627\u0642 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647."}, {"key": "D", "text": "\u064a\u062a\u0645 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0642\u062f\u0631\u0627\u062a \u0627\u0644\u0645\u0628\u0631\u0645\u062c."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q34", "number": 34, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \"\u0627\u0644\u0643\u0644\u0645\u0627\u062a\" (Words) \u0648\"\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a\" \u0643\u0623\u0628\u0639\u0627\u062f \u0644\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0644\u0644\u0623\u0648\u0627\u0645\u0631\u060c \u0648\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a \u0644\u0644\u0635\u0648\u0631 \u0641\u0642\u0637."}, {"key": "B", "text": "\u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0644\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0646\u0635\u064a\u060c \u0648\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a \u0644\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0631\u0633\u0648\u0645\u064a\u0629 \u0648\u0627\u0644\u0623\u064a\u0642\u0648\u0646\u0627\u062a."}, {"key": "C", "text": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u0631\u0642."}, {"key": "D", "text": "\u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u062e\u0628\u0631\u0627\u0621 \u0641\u0642\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q35", "number": 35, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u0644\u0627 \u064a\u0639\u062a\u0628\u0631 \u0645\u0646 \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u062e\u0645\u0633\u0629 \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0627\u062a\u0633\u0627\u0642."}, {"key": "B", "text": "\u0627\u0644\u0623\u0645\u0627\u0646\u0629 (Honesty)."}, {"key": "C", "text": "\u0627\u0644\u0625\u062f\u0631\u0627\u0643."}, {"key": "D", "text": "\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q36", "number": 36, "text": "\u0645\u0627 \u0627\u0644\u0647\u062f\u0641 \u0645\u0646 \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629\" (Prototyping)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0628\u064a\u0639 \u0627\u0644\u0645\u0646\u062a\u062c \u0627\u0644\u0646\u0647\u0627\u0626\u064a."}, {"key": "B", "text": "\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0645\u0628\u0643\u0631\u0629."}, {"key": "C", "text": "\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f \u0627\u0644\u0646\u0647\u0627\u0626\u064a."}, {"key": "D", "text": "\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q37", "number": 37, "text": "\u0625\u0630\u0627 \u0643\u0646\u062a \u062a\u0635\u0645\u0645 \u0646\u0638\u0627\u0645\u0627\u064b \u0644\u0631\u0648\u0627\u062f \u0627\u0644\u0641\u0636\u0627\u0621 \u064a\u062a\u0637\u0644\u0628 \u0627\u062a\u0628\u0627\u0639 \u062e\u0637\u0648\u0627\u062a \u062f\u0642\u064a\u0642\u0629 \u0648\u0635\u0627\u0631\u0645\u0629\u060c \u0623\u064a \u062a\u0631\u062a\u064a\u0628 \u0644\u0644\u062a\u062d\u0643\u0645 \u062a\u062e\u062a\u0627\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0631\u062a\u064a\u0628 \u0645\u062a\u0643\u0631\u0631 (Frequency)."}, {"key": "B", "text": "\u062a\u0631\u062a\u064a\u0628 \u0648\u0638\u064a\u0641\u064a (Functional)."}, {"key": "C", "text": "\u062a\u0631\u062a\u064a\u0628 \u062a\u0633\u0644\u0633\u0644\u064a (Sequential)."}, {"key": "D", "text": "\u062a\u0631\u062a\u064a\u0628 \u0639\u0634\u0648\u0627\u0626\u064a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q38", "number": 38, "text": "\u0643\u064a\u0641 \u064a\u0633\u0627\u0647\u0645 \"\u0627\u0644\u0648\u0642\u062a\" \u0643\u0628\u0639\u062f \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0628\u0642\u064a\u0627\u0633 \u0633\u0631\u0639\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c."}, {"key": "B", "text": "\u0628\u0642\u064a\u0627\u0633 \u0645\u062f\u0629 \u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u062a\u0642\u062f\u0645\u0647 \u0641\u064a \u0627\u0644\u0645\u0647\u0645\u0629."}, {"key": "C", "text": "\u0628\u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0639\u062f \u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0633\u0627\u0647\u0645 \u0628\u0623\u064a \u0634\u064a\u0621."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q39", "number": 39, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 \u0623\u0646 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \"\u0628\u062f\u064a\u0647\u064a\u0627\u064b\" (Learnability)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0646 \u064a\u0643\u0648\u0646 \u0645\u062c\u0647\u0648\u0644 \u0627\u0644\u0645\u0635\u062f\u0631."}, {"key": "B", "text": "\u0623\u0646 \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062e\u0628\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0644\u0627 \u064a\u062d\u062a\u0627\u062c \u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0643\u062b\u064a\u0631\u0629."}, {"key": "C", "text": "\u0623\u0646 \u064a\u0643\u0648\u0646 \u0635\u0639\u0628\u0627\u064b \u0644\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u062a\u062d\u062f\u064a."}, {"key": "D", "text": "\u0623\u0646 \u064a\u0638\u0647\u0631 \u0631\u0633\u0627\u0626\u0644 \u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0641\u064a \u0643\u0644 \u062b\u0627\u0646\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q40", "number": 40, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062f \u0645\u0646 \u0639\u0646\u0627\u0635\u0631 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u0645\u062a\u062d\u0631\u0643\u0629 (Animation)."}, {"key": "B", "text": "\u0627\u0644\u0637\u0628\u0627\u0639\u0629 (Typography)."}, {"key": "C", "text": "\u0627\u0644\u0648\u0642\u062a."}, {"key": "D", "text": "\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q41", "number": 41, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629\" \u0641\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u062c\u0647\u0632\u0629 (\u0647\u0648\u0627\u062a\u0641\u060c \u0644\u0627\u0628\u062a\u0648\u0628) \u0627\u0644\u062a\u064a \u064a\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "B", "text": "\u0627\u0644\u0623\u062b\u0627\u062b \u0641\u064a \u0627\u0644\u063a\u0631\u0641\u0629."}, {"key": "C", "text": "\u0627\u0644\u0623\u0642\u0631\u0627\u0635 \u0627\u0644\u0635\u0644\u0628\u0629."}, {"key": "D", "text": "\u0627\u0644\u0643\u0648\u062f \u0627\u0644\u0628\u0631\u0645\u062c\u064a."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q42", "number": 42, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\" \u0645\u0647\u0645\u0627\u064b \u0644\u0644\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629 (Branding)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0623\u0646\u0647 \u064a\u062d\u062f\u062f \u0633\u0639\u0631 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u0644\u0623\u0646\u0647 \u064a\u0646\u0642\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u0647\u0648\u064a\u0629 \u0627\u0644\u0634\u0631\u0643\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0648\u0627\u0644\u0634\u0639\u0627\u0631."}, {"key": "C", "text": "\u0644\u0623\u0646\u0647 \u064a\u062c\u0639\u0644 \u0627\u0644\u0645\u0648\u0642\u0639 \u0628\u0637\u064a\u0626\u0627\u064b."}, {"key": "D", "text": "\u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647 \u0628\u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q43", "number": 43, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064a \"\u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629."}, {"key": "B", "text": "\u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a (Requirements)."}, {"key": "C", "text": "\u0627\u0644\u062a\u062d\u0644\u064a\u0644."}, {"key": "D", "text": "\u0627\u0644\u062a\u0646\u0641\u064a\u0630."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q44", "number": 44, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \"\u062a\u0648\u0642\u0639 \u0627\u0644\u0623\u062e\u0637\u0627\u0621\" \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062c\u064a\u062f\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u062d\u0627\u0648\u0644\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0625\u062a\u0644\u0627\u0641 \u0627\u0644\u0646\u0638\u0627\u0645."}, {"key": "B", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0644\u0645\u0646\u0639 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u062d\u062a\u0645\u0644\u0629 \u0623\u0648 \u0627\u0644\u062a\u062e\u0641\u064a\u0641 \u0645\u0646 \u062d\u062f\u062a\u0647\u0627 \u0642\u0628\u0644 \u0648\u0642\u0648\u0639\u0647\u0627."}, {"key": "C", "text": "\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062e\u0637\u0623 \u0627\u0644\u0645\u062e\u064a\u0641\u0629."}, {"key": "D", "text": "\u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0646\u0638\u0627\u0645 \u0639\u0646\u062f \u0623\u064a \u062e\u0637\u0623."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q45", "number": 45, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0635\u0641 \"\u0646\u0645\u0637 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629\" (Conversing)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u0643\u062a\u0628 \u0623\u0648\u0627\u0645\u0631 \u0635\u0627\u0631\u0645\u0629."}, {"key": "B", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u062c\u0631\u064a \u062d\u0648\u0627\u0631\u0627\u064b \u0645\u0639 \u0627\u0644\u0646\u0638\u0627\u0645 (\u0635\u0648\u062a\u064a/\u0646\u0635\u064a) \u0648\u0643\u0623\u0646\u0647 \u0634\u062e\u0635 \u0622\u062e\u0631."}, {"key": "C", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u0645\u0644\u0623 \u0641\u0631\u0627\u063a\u0627\u062a."}, {"key": "D", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u062e\u062a\u0627\u0631 \u0645\u0646 \u0642\u0627\u0626\u0645\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q46", "number": 46, "text": "\u0645\u0627 \u0647\u064a \u0645\u0634\u0643\u0644\u0629 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u063a\u064a\u0631 \u0627\u0644\u0645\u062a\u0633\u0642\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0633\u0647\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062a\u0646\u0628\u0624."}, {"key": "B", "text": "\u064a\u0631\u0628\u0643 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u064a\u0632\u064a\u062f \u0645\u0646 \u0627\u062d\u062a\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062e\u0637\u0623."}, {"key": "C", "text": "\u064a\u062c\u0639\u0644 \u0627\u0644\u0645\u0646\u062a\u062c \u062c\u0630\u0627\u0628\u0627\u064b."}, {"key": "D", "text": "\u064a\u0642\u0644\u0644 \u0648\u0642\u062a \u0627\u0644\u062a\u0646\u0641\u064a\u0630."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q47", "number": 47, "text": "\u0641\u064a \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a\"\u060c \u0623\u064a \u062a\u0642\u0646\u064a\u0629 \u0644\u0627 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u062c\u0645\u0639 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0627\u062a."}, {"key": "B", "text": "\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646."}, {"key": "C", "text": "\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f."}, {"key": "D", "text": "\u0627\u0644\u0627\u0637\u0644\u0627\u0639 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q48", "number": 48, "text": "\u0645\u0627 \u0647\u0648 \u062a\u0623\u062b\u064a\u0631 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\" \u0627\u0644\u0633\u064a\u0621 \u0639\u0644\u0649 \u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0627 \u064a\u0624\u062b\u0631."}, {"key": "B", "text": "\u064a\u0632\u064a\u062f \u0645\u0646 \u0633\u0631\u0639\u0629 \u0627\u0644\u0645\u0648\u0642\u0639."}, {"key": "C", "text": "\u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0633\u0648\u0621 \u0627\u0644\u0641\u0647\u0645 \u0648\u0639\u062f\u0645 \u0627\u0644\u062b\u0642\u0629."}, {"key": "D", "text": "\u064a\u062d\u0633\u0646 \u0645\u0646 \u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u0646\u0638\u0627\u0645."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q49", "number": 49, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0645\u062b\u0644 \"\u0627\u0644\u062a\u0643\u0631\u0627\u0631\" \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0643\u0631\u0627\u0631 \u0646\u0641\u0633 \u0627\u0644\u0623\u062e\u0637\u0627\u0621."}, {"key": "B", "text": "\u062a\u0643\u0631\u0627\u0631 \u062f\u0648\u0631\u0629 (\u062a\u0635\u0645\u064a\u0645 -> \u0627\u062e\u062a\u0628\u0627\u0631 -> \u062a\u0639\u062f\u064a\u0644) \u0644\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0646\u062a\u064a\u062c\u0629."}, {"key": "C", "text": "\u062a\u0643\u0631\u0627\u0631 \u0646\u0641\u0633 \u0627\u0644\u0623\u0644\u0648\u0627\u0646."}, {"key": "D", "text": "\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0628\u064a\u0639."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q50", "number": 50, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0645\u0646 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0625\u0646\u0634\u0627\u0621 \u0645\u0646\u062a\u062c\u0627\u062a \u0645\u0639\u0642\u062f\u0629."}, {"key": "B", "text": "\u062a\u0633\u0647\u064a\u0644 \u062d\u064a\u0627\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u062c\u0639\u0644 \u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0623\u0642\u0644 \u0625\u062d\u0628\u0627\u0637\u0627\u064b."}, {"key": "C", "text": "\u0632\u064a\u0627\u062f\u0629 \u0639\u062f\u062f \u0627\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "D", "text": "\u062a\u0642\u0644\u064a\u0644 \u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u0646\u0638\u0627\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q51", "number": 51, "text": "\u0639\u0631\u0641 \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0628\u064a\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u0627\u0633\u0648\u0628 (HCI).", "questionType": "text", "answerText": "\u0647\u0648 \u0645\u062c\u0627\u0644 \u0645\u062a\u0639\u062f\u062f \u0627\u0644\u062a\u062e\u0635\u0635\u0627\u062a \u064a\u0647\u062a\u0645 \u0628\u062f\u0631\u0627\u0633\u0629 \u0648\u062a\u0635\u0645\u064a\u0645 \u0648\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u0631\u0643\u0632\u0629 \u062d\u0648\u0644 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u060c \u0628\u0647\u062f\u0641 \u062c\u0639\u0644 \u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0633\u0647\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u060c \u0645\u0641\u064a\u062f\u0629\u060c \u0648\u0645\u0645\u062a\u0639\u0629."}, {"id": "hci-lecture-1-q52", "number": 52, "text": "\u0623\u0630\u0643\u0631 \u062b\u0644\u0627\u062b\u0629 \u0645\u0646 \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629\u060c \u0648\u0627\u0634\u0631\u062d \u0648\u0627\u062d\u062f\u0627\u064b \u0645\u0646\u0647\u0627.", "questionType": "text", "answerText": "1. \u0627\u0644\u0627\u062a\u0633\u0627\u0642. 2. \u0627\u0644\u0642\u0627\u0628\u0644\u064a\u0629 \u0644\u0644\u062a\u0646\u0628\u0624. 3. \u0627\u0644\u0625\u062f\u0631\u0627\u0643 (\u0623\u0648 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629\u060c \u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645)."}, {"id": "hci-lecture-1-q53", "number": 53, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 \u0646\u0645\u0637 \"\u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631\" \u0648 \"\u0627\u0644\u0642\u0648\u0627\u0626\u0645\" \u0645\u0646 \u062d\u064a\u062b \u0633\u0647\u0648\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0648\u0627\u0644\u0642\u0648\u0629.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-1-q54", "number": 54, "text": "\u0645\u0627 \u0647\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u062e\u0645\u0633\u0629\u061f", "questionType": "text", "answerText": "1. \u0627\u0644\u0643\u0644\u0645\u0627\u062a (Words). 2. \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a (Visual Presentation). 3. \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629 (Physical Objects). 4. \u0627\u0644\u0648\u0642\u062a (Time). 5. \u0627\u0644\u0633\u0644\u0648\u0643 (Behavior)."}, {"id": "hci-lecture-1-q55", "number": 55, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0648\u0638\u064a\u0641\u064a\" \u0648 \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a\" \u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u062d\u0643\u0645.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-1-q56", "number": 56, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u064a\" (Iterative Design)\u061f \u0648\u0644\u0645\u0627\u0630\u0627 \u0647\u0648 \u0636\u0631\u0648\u0631\u064a\u061f", "questionType": "text", "answerText": "\u0647\u0648 \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u062a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062a\u0643\u0631\u0627\u0631 \u062f\u0648\u0631\u0627\u062a \u0645\u0646 (\u062a\u0635\u0645\u064a\u0645 -> \u0646\u0645\u0648\u0630\u062c -> \u0627\u062e\u062a\u0628\u0627\u0631 -> \u062a\u0639\u062f\u064a\u0644)."}, {"id": "hci-lecture-1-q57", "number": 57, "text": "\u0648\u0636\u062d \u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0628\u064a\u0646 \"\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\" \u0648 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\". \u0623\u064a\u0647\u0645\u0627 \u064a\u0633\u0628\u0642 \u0627\u0644\u0622\u062e\u0631\u061f", "questionType": "text", "answerText": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 (ID) \u064a\u0633\u0628\u0642 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a (VD)."}, {"id": "hci-lecture-1-q58", "number": 58, "text": "\u0645\u0627 \u0647\u064a \u062e\u0637\u0648\u0627\u062a \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628\u061f", "questionType": "text", "answerText": "1. \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a (Requirements). 2. \u0627\u0644\u062a\u062d\u0644\u064a\u0644 (Analysis). 3. \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629 (Iteration & Prototyping). 4. \u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0648\u0627\u0644\u0646\u0634\u0631 (Implementation & Deployment)."}, {"id": "hci-lecture-1-q59", "number": 59, "text": "\u0627\u0634\u0631\u062d \u0645\u0628\u062f\u0623 \"\u0627\u0644\u0625\u062f\u0631\u0627\u0643\" (Perceivability) \u0645\u0639 \u0645\u062b\u0627\u0644.", "questionType": "text", "answerText": "\u064a\u0639\u0646\u064a \u0623\u0646 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u0627\u062a \u0648\u0627\u0644\u0648\u0638\u0627\u0626\u0641 \u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0648\u0627\u0636\u062d\u0629 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062f\u0648\u0646 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0644\u062a\u062c\u0631\u0628\u0629."}, {"id": "hci-lecture-1-q60", "number": 60, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0646\u0645\u0637 \"\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a\" \u0648 \"\u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629\" \u0641\u064a \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "text", "answerText": ""}]}, {"id": "hci-lecture-3", "title": "\u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629", "questions": [{"id": "hci-lecture-3-q1", "number": 1, "text": "\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI) \u062a\u0631\u0643\u0632 \u0641\u0642\u0637 \u0639\u0644\u0649 \u0627\u0644\u0634\u0643\u0644 \u0627\u0644\u062c\u0645\u0627\u0644\u064a \u0648\u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647\u0627 \u0628\u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u0623\u0632\u0631\u0627\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q2", "number": 2, "text": "\"\u0627\u0644\u062d\u0627\u0648\u064a\u0627\u062a\" (Containers) \u0641\u064a \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0641\u064a \u0623\u0642\u0633\u0627\u0645 \u0630\u0627\u062a \u0645\u0639\u0646\u0649.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q3", "number": 3, "text": "\u0645\u0628\u062f\u0623 \"\u0627\u0644\u0623\u0644\u0641\u0629\" (Familiarity) \u064a\u0639\u0646\u064a \u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0627\u062a \u062c\u062f\u064a\u062f\u0629 \u0648\u0645\u0628\u062a\u0643\u0631\u0629 \u062a\u0645\u0627\u0645\u0627\u064b \u0644\u062a\u062c\u0646\u0628 \u0627\u0644\u0645\u0644\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q4", "number": 4, "text": "\"\u062a\u062d\u0643\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\" (User Control) \u064a\u0639\u0646\u064a \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062d\u0631\u064a\u0629 \u0627\u0631\u062a\u0643\u0627\u0628 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0645\u0639 \u062a\u0648\u0641\u064a\u0631 \u0648\u0633\u064a\u0644\u0629 \u0644\u0644\u062a\u0631\u0627\u062c\u0639 (Undo).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q5", "number": 5, "text": "\u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0647\u0631\u0645\u064a \u0627\u0644\u0628\u0635\u0631\u064a (Hierarchy) \u064a\u0639\u062a\u0645\u062f \u0641\u0642\u0637 \u0639\u0644\u0649 \u062d\u062c\u0645 \u0627\u0644\u062e\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q6", "number": 6, "text": "\"\u0627\u0644\u0645\u0631\u0648\u0646\u0629\" (Flexibility) \u0641\u064a \u062a\u0635\u0645\u064a\u0645 UI \u062a\u0639\u0646\u064a \u0642\u062f\u0631\u0629 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0639\u0644\u0649 \u062e\u062f\u0645\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646 \u0648\u0627\u0644\u062e\u0628\u0631\u0627\u0621 \u0645\u0639\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q7", "number": 7, "text": "\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UX) \u062a\u0642\u062a\u0635\u0631 \u0639\u0644\u0649 \u0634\u0639\u0648\u0631 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062d\u0638\u0629 \u0634\u0631\u0627\u0621 \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q8", "number": 8, "text": "\u0645\u0631\u062d\u0644\u0629 \"\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c\" (Product Definition) \u062a\u0623\u062a\u064a \u0628\u0639\u062f \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645\".", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q9", "number": 9, "text": "\"\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\" (Information Architecture) \u062a\u0647\u062a\u0645 \u0628\u0643\u064a\u0641\u064a\u0629 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0648\u0647\u064a\u0643\u0644 \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q10", "number": 10, "text": "\u0645\u0635\u0645\u0645 UI \u064a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0645\u0647\u0627\u0631\u0627\u062a \u0641\u064a \"\u0623\u0628\u062d\u0627\u062b \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\" \u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0635\u0645\u0645 UX.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q11", "number": 11, "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0628 (RWD) \u064a\u0639\u0646\u064a \u0625\u0646\u0634\u0627\u0621 \u0645\u0648\u0642\u0639\u064a\u0646 \u0645\u0646\u0641\u0635\u0644\u064a\u0646 \u0644\u0644\u0645\u0648\u0628\u0627\u064a\u0644 \u0648\u0627\u0644\u0643\u0645\u0628\u064a\u0648\u062a\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q12", "number": 12, "text": "\u0625\u0637\u0627\u0631 \u0627\u0644\u0639\u0645\u0644 Bootstrap \u064a\u0648\u0641\u0631 \u0648\u0642\u062a\u0627\u064b \u0648\u062c\u0647\u062f\u0627\u064b \u0644\u0644\u0645\u0637\u0648\u0631\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q13", "number": 13, "text": "\u0646\u0638\u0627\u0645 \u0627\u0644\u0634\u0628\u0643\u0629 \u0641\u064a Bootstrap \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u0635\u0641\u062d\u0629 \u0625\u0644\u0649 10 \u0623\u0639\u0645\u062f\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q14", "number": 14, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `col-lg` \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0623\u0642\u0644 \u0645\u0646 576 \u0628\u0643\u0633\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q15", "number": 15, "text": "\u064a\u0645\u0643\u0646 \u062f\u0645\u062c \u0643\u0644\u0627\u0633\u0627\u062a Bootstrap (\u0645\u062b\u0644 `col-md` \u0648 `col-sm`) \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0639\u0646\u0635\u0631 \u0644\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u0634\u0643\u0644 \u0639\u0644\u0649 \u0623\u062c\u0647\u0632\u0629 \u0645\u062e\u062a\u0644\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q16", "number": 16, "text": "\"\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644\" (Accessibility) \u062a\u0639\u0646\u064a \u0633\u0647\u0648\u0644\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q17", "number": 17, "text": "\"\u0627\u0644\u0648\u0636\u0648\u062d\" (Clarity) \u064a\u0639\u0646\u064a \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0641\u062c\u0648\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0628\u064a\u0646 \u0645\u0627 \u064a\u0639\u0631\u0641\u0647 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0645\u0627 \u064a\u062d\u062a\u0627\u062c \u0644\u0645\u0639\u0631\u0641\u062a\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q18", "number": 18, "text": "\u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\" \u0641\u064a UX \u0644\u0627 \u062a\u062a\u0637\u0644\u0628 \u0648\u062c\u0648\u062f \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q19", "number": 19, "text": "\"\u0627\u0644\u0641\u0631\u0627\u063a \u0627\u0644\u0633\u0644\u0628\u064a\" (Negative Space) \u064a\u0634\u062a\u062a \u0627\u0646\u062a\u0628\u0627\u0647 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q20", "number": 20, "text": "\u0645\u0635\u0645\u0645 UI \u064a\u062d\u062a\u0627\u062c \u0644\u0645\u0639\u0631\u0641\u0629 HTML/CSS \u0644\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q21", "number": 21, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0639\u0646\u0635\u0631 \u0627\u0644\u0630\u064a \u064a\u064f\u0635\u0646\u0641 \u0636\u0645\u0646 \"\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0625\u062f\u062e\u0627\u0644\" (Input Controls)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0642\u062f\u0645 (Progress Bar)."}, {"key": "B", "text": "\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 (Dropdown List)."}, {"key": "C", "text": "\u0623\u064a\u0642\u0648\u0646\u0629 \u0627\u0644\u062a\u0646\u0628\u064a\u0647."}, {"key": "D", "text": "\u0627\u0644\u062d\u0627\u0648\u064a\u0629 (Container)."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q22", "number": 22, "text": "\u0641\u064a \u0633\u064a\u0627\u0642 UI\u060c \u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \"\u0645\u0628\u062f\u0623 \u0627\u0644\u0623\u0644\u0641\u0629\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0646 \u064a\u0639\u0631\u0641 \u0627\u0644\u0645\u0635\u0645\u0639 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0634\u062e\u0635\u064a\u0627\u064b."}, {"key": "B", "text": "\u0623\u0646 \u062a\u0639\u0645\u0644 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0628\u0646\u0641\u0633 \u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u062a\u064a \u064a\u062a\u0648\u0642\u0639\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0645\u0646 \u062a\u062c\u0627\u0631\u0628\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0635\u0648\u0631 \u0639\u0627\u0626\u0644\u064a\u0629."}, {"key": "D", "text": "\u062a\u0643\u0631\u0627\u0631 \u0646\u0641\u0633 \u0627\u0644\u0639\u0646\u0627\u0635\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q23", "number": 23, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u064a \u064a\u062a\u0645 \u0641\u064a\u0647\u0627 \u0625\u0646\u0634\u0627\u0621 \"\u0627\u0644\u0634\u062e\u0635\u064a\u0627\u062a\" (Personas) \u0641\u064a \u0639\u0645\u0644\u064a\u0629 UX\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "C", "text": "\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "D", "text": "\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q24", "number": 24, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `col-sm-4` \u0648 `col-md-4` \u0641\u064a Bootstrap\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "B", "text": "`col-sm-4` \u064a\u0638\u0647\u0631 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629\u060c \u0648 `col-md-4` \u0639\u0644\u0649 \u0627\u0644\u0635\u063a\u064a\u0631\u0629."}, {"key": "C", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u064a\u0639\u0637\u064a \u0639\u0631\u0636\u0627\u064b \u064a\u0633\u0627\u0648\u064a \u062b\u0644\u062b \u0627\u0644\u0635\u0641\u062d\u0629 (4 \u0645\u0646 12)\u060c \u0644\u0643\u0646 `col-sm` \u064a\u0646\u0637\u0628\u0642 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629 \u0648\u0645\u0627\u0641\u0648\u0642\u0647\u0627\u060c \u0648 `col-md` \u0639\u0644\u0649 \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629 \u0648\u0645\u0627 \u0641\u0648\u0642\u0647\u0627."}, {"key": "D", "text": "`col-md-4` \u064a\u062c\u0639\u0644 \u0627\u0644\u0639\u0646\u0635\u0631 \u0645\u062e\u0641\u064a\u0627\u064b."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q25", "number": 25, "text": "\u0623\u064a \u0645\u0645\u0627 \u064a\u0644\u064a \u064a\u0639\u062f \u0645\u0646 \u0645\u0647\u0627\u0631\u0627\u062a \"\u0645\u0635\u0645\u0645 UX\" \u0648\u0644\u064a\u0633 UI\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0623\u0644\u0648\u0627\u0646."}, {"key": "B", "text": "\u0623\u0628\u062d\u0627\u062b \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (User Research)."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Adobe XD."}, {"key": "D", "text": "\u0627\u0644\u0637\u0628\u0627\u0639\u0629 (Typography)."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q26", "number": 26, "text": "\u0645\u0627 \u0647\u064a \u0641\u0627\u0626\u062f\u0629 \"\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629\" (Wireframes)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0644\u0648\u064a\u0646 \u0627\u0644\u0648\u0627\u062c\u0647\u0629."}, {"key": "B", "text": "\u062a\u0648\u0636\u064a\u062d \u0647\u064a\u0643\u0644 \u0627\u0644\u0635\u0641\u062d\u0629 \u0648\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u062f\u0648\u0646 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u062c\u0645\u0627\u0644\u064a\u0629."}, {"key": "C", "text": "\u0643\u062a\u0627\u0628\u0629 \u0643\u0648\u062f \u0627\u0644\u062e\u0627\u062f\u0645."}, {"key": "D", "text": "\u0628\u064a\u0639 \u0627\u0644\u0645\u0646\u062a\u062c."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q27", "number": 27, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0645\u062e\u0631\u062c \u0627\u0644\u0637\u0648\u0627\u0631\u0626\" \u0641\u064a \u0645\u0628\u062f\u0623 \u062a\u062d\u0643\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u0631 \u0644\u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0627\u0644\u0634\u0631\u0637\u0629."}, {"key": "B", "text": "\u062e\u064a\u0627\u0631 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 (Undo) \u0623\u0648 \u0627\u0644\u0625\u0644\u063a\u0627\u0621 \u0644\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u062d\u0627\u0644\u0629 \u063a\u064a\u0631 \u0645\u0631\u063a\u0648\u0628 \u0641\u064a\u0647\u0627."}, {"key": "C", "text": "\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u062c\u0647\u0627\u0632."}, {"key": "D", "text": "\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q28", "number": 28, "text": "\u0645\u0627 \u0647\u064a \u0623\u0643\u0628\u0631 \u0634\u0627\u0634\u0629 \u064a\u062f\u0639\u0645\u0647\u0627 \u0643\u0644\u0627\u0633 `col-lg`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "768px."}, {"key": "B", "text": "992px."}, {"key": "C", "text": "1200px \u0641\u0623\u0643\u062b\u0631."}, {"key": "D", "text": "576px."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q29", "number": 29, "text": "\u0643\u064a\u0641 \u064a\u0645\u0643\u0646 \u062a\u062d\u0642\u064a\u0642 \"\u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0647\u0631\u0645\u064a\" \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0644\u0648\u0646\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062f\u0627\u0643\u0646\u0629 \u0644\u0643\u0644 \u0634\u064a\u0621."}, {"key": "B", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u0644\u0648\u0627\u0646 \u0632\u0627\u0647\u064a\u0629 \u0644\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0642\u0644 \u0623\u0647\u0645\u064a\u0629."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u0644\u0648\u0627\u0646 \u0645\u062a\u0628\u0627\u064a\u0646\u0629 \u0648\u062c\u0630\u0627\u0628\u0629 \u0644\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0643\u062b\u0631 \u0623\u0647\u0645\u064a\u0629."}, {"key": "D", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u0648\u0646 \u0648\u0627\u062d\u062f \u0641\u0642\u0637."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q30", "number": 30, "text": "\u0645\u0627 \u0647\u0648 \"\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c\" (Product Definition)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0631\u062d\u0644\u0629 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f."}, {"key": "B", "text": "\u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u062a\u062d\u062f\u064a\u062f \u0645\u0627 \u0647\u0648 \u0645\u0637\u0644\u0648\u0628 \u0648\u0641\u0647\u0645 \u0633\u064a\u0627\u0642 \u0627\u0644\u0645\u0634\u0631\u0648\u0639."}, {"key": "C", "text": "\u0645\u0631\u062d\u0644\u0629 \u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u0645\u0648\u0642\u0639."}, {"key": "D", "text": "\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0633\u0648\u064a\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q31", "number": 31, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u0644\u064a\u0633 \u0645\u0646 \u0645\u0632\u0627\u064a\u0627 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0628 (RWD)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u062d\u0633\u064a\u0646 \u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "B", "text": "\u062a\u062d\u0633\u064a\u0646 \u062a\u0631\u062a\u064a\u0628 \u0645\u062d\u0631\u0643\u0627\u062a \u0627\u0644\u0628\u062d\u062b (SEO)."}, {"key": "C", "text": "\u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0635\u064a\u0627\u0646\u0629 \u0645\u0648\u0642\u0639\u064a\u0646 \u0645\u0646\u0641\u0635\u0644\u064a\u0646."}, {"key": "D", "text": "\u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0648\u0642\u062a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q32", "number": 32, "text": "\u0645\u0627 \u0647\u0648 \u062f\u0648\u0631 \"\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u0646\u0642\u0644\" (Navigational Elements)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a."}, {"key": "B", "text": "\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u0646\u0642\u0644 \u0641\u064a \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0648\u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u0647\u0627\u0645."}, {"key": "C", "text": "\u0639\u0631\u0636 \u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062e\u0637\u0623."}, {"key": "D", "text": "\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0635\u0648\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q33", "number": 33, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \u0627\u0644\u0643\u0644\u0627\u0633 `col-12` \u0641\u064a Bootstrap\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0639\u0646\u0635\u0631 \u0645\u062e\u0641\u064a."}, {"key": "B", "text": "\u0639\u0646\u0635\u0631 \u064a\u0623\u062e\u0630 \u0643\u0627\u0645\u0644 \u0639\u0631\u0636 \u0627\u0644\u0635\u0641 (100%)."}, {"key": "C", "text": "\u0639\u0646\u0635\u0631 \u064a\u0623\u062e\u0630 \u0646\u0635\u0641 \u0627\u0644\u0635\u0641."}, {"key": "D", "text": "\u0639\u0646\u0635\u0631 \u064a\u0623\u062e\u0630 12 \u0639\u0645\u0648\u062f\u0627\u064b \u0645\u062a\u062c\u0627\u0648\u0632\u0627\u064b \u0627\u0644\u062d\u062f."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q34", "number": 34, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 UI \u0648 UX \u0645\u0646 \u062d\u064a\u062b \"\u0627\u0644\u0646\u0637\u0627\u0642\" (Scope)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "UI \u0623\u0648\u0633\u0639 \u0646\u0637\u0627\u0642\u0627\u064b."}, {"key": "B", "text": "UX \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0634\u0643\u0644 \u0641\u0642\u0637."}, {"key": "C", "text": "UI \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0648\u0627\u0644\u0623\u0632\u0631\u0627\u0631\u060c \u0628\u064a\u0646\u0645\u0627 UX \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0631\u062d\u0644\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q35", "number": 35, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0645\u0631\u0648\u0646\u0629\" \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0644\u0644\u0645\u0628\u0631\u0645\u062c\u064a\u0646 \u0641\u0642\u0637."}, {"key": "B", "text": "\u0642\u062f\u0631\u0629 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0639\u0644\u0649 \u062e\u062f\u0645\u0629 \u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0628\u0645\u0647\u0627\u0631\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629 (\u0645\u0628\u062a\u062f\u0626/\u062e\u0628\u064a\u0631) \u0648\u0623\u062c\u0647\u0632\u0629 \u0645\u062e\u062a\u0644\u0641\u0629."}, {"key": "C", "text": "\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0628\u0627\u0633\u062a\u0645\u0631\u0627\u0631."}, {"key": "D", "text": "\u0625\u0636\u0627\u0641\u0629 \u0645\u0645\u064a\u0632\u0627\u062a \u0645\u0639\u0642\u062f\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q36", "number": 36, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u064a\u0629\" (Informational Components)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0632\u0631\u0627\u0631 \u0627\u0644\u0625\u0631\u0633\u0627\u0644."}, {"key": "B", "text": "\u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u064a \u062a\u0648\u0635\u0644 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (\u0645\u062b\u0644 \u0623\u0634\u0631\u0637\u0629 \u0627\u0644\u062a\u0642\u062f\u0645)."}, {"key": "C", "text": "\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u062a\u0646\u0642\u0644."}, {"key": "D", "text": "\u062d\u0642\u0648\u0644 \u0627\u0644\u0646\u0635."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q37", "number": 37, "text": "\u0643\u064a\u0641 \u064a\u0633\u0627\u0647\u0645 Bootstrap \u0641\u064a \"\u0627\u0644\u0627\u062a\u0633\u0627\u0642\" (Consistency)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0641\u0631\u0636 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u0648\u0646 \u0648\u0627\u062d\u062f."}, {"key": "B", "text": "\u064a\u0648\u0641\u0631 \u0645\u0643\u062a\u0628\u0629 \u0645\u0648\u062d\u062f\u0629 \u0645\u0646 \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0630\u0627\u062a \u0627\u0644\u0634\u0643\u0644 \u0627\u0644\u0645\u0648\u062d\u062f."}, {"key": "C", "text": "\u064a\u0645\u0646\u0639 \u0627\u0644\u062a\u0639\u062f\u064a\u0644 \u0639\u0644\u0649 \u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0633\u0627\u0647\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q38", "number": 38, "text": "\u0645\u0627 \u0647\u064a \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0628\u062d\u062b\" (Product Research)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0642\u0648\u0627\u0644\u0628 \u062c\u0627\u0647\u0632\u0629."}, {"key": "B", "text": "\u0625\u062c\u0631\u0627\u0621 \u0623\u0628\u062d\u0627\u062b \u0627\u0644\u0633\u0648\u0642 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0633\u064a\u0646 \u0644\u0641\u0647\u0645 \u0627\u0644\u0641\u0631\u0635."}, {"key": "C", "text": "\u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0645\u0633\u062a\u062b\u0645\u0631\u064a\u0646."}, {"key": "D", "text": "\u0627\u0644\u0628\u062d\u062b \u0641\u064a \u0645\u062d\u0631\u0643\u0627\u062a \u0627\u0644\u0628\u062d\u062b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q39", "number": 39, "text": "\u0645\u0627\u0630\u0627 \u064a\u062d\u062f\u062b \u0625\u0630\u0627 \u062a\u062c\u0627\u0648\u0632 \u0645\u062c\u0645\u0648\u0639 \u0627\u0644\u0623\u0639\u0645\u062f\u0629 \u0641\u064a \u0627\u0644\u0635\u0641 \u0627\u0644\u0648\u0627\u062d\u062f 12\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0627 \u064a\u062d\u062f\u062b \u0634\u064a\u0621."}, {"key": "B", "text": "\u064a\u062a\u0645 \u0642\u0637\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0632\u0627\u0626\u062f."}, {"key": "C", "text": "\u064a\u062a\u0645 \u062f\u0641\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0632\u0627\u0626\u062f\u0629 \u0644\u0633\u0637\u0631 \u062c\u062f\u064a\u062f \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b."}, {"key": "D", "text": "\u064a\u0639\u0637\u064a \u0627\u0644\u0646\u0638\u0627\u0645 \u062e\u0637\u0623."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q40", "number": 40, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u062e\u062a\u0628\u0627\u0631 \u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\" (Usability Testing) \u0645\u0647\u0645\u0627\u064b\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0646\u062a\u062c \u0645\u0639 \u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u062d\u0642\u064a\u0642\u064a\u064a\u0646 \u0648\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0623\u062e\u0637\u0627\u0621."}, {"key": "B", "text": "\u0644\u0632\u064a\u0627\u062f\u0629 \u0645\u0628\u064a\u0639\u0627\u062a \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "C", "text": "\u0644\u062a\u062d\u0633\u064a\u0646 \u0634\u0643\u0644 \u0627\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "D", "text": "\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u0648\u062b\u064a\u0642."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q41", "number": 41, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0647\u062f\u0641 \u0645\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \"\u0627\u0644\u062a\u0628\u0627\u064a\u0646\" \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0625\u0631\u0628\u0627\u0643 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "B", "text": "\u0644\u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0645\u0647\u0645\u0629 \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0639\u064a\u0646."}, {"key": "C", "text": "\u0644\u062a\u062c\u0645\u064a\u0644 \u0627\u0644\u0635\u0641\u062d\u0629 \u0641\u0642\u0637."}, {"key": "D", "text": "\u0644\u062a\u0642\u0644\u064a\u0644 \u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062a\u062d\u0645\u064a\u0644."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q42", "number": 42, "text": "\u0645\u0627 \u0647\u064a \"\u0646\u0642\u0637\u0629 \u0627\u0644\u0627\u0646\u0643\u0633\u0627\u0631\" (Breakpoint) \u0644\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629 (md)\u061f", "questionType": "choice", "options": [{"key": "A", "text": ">= 576px."}, {"key": "B", "text": ">= 768px."}, {"key": "C", "text": ">= 992px."}, {"key": "D", "text": ">= 1200px."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q43", "number": 43, "text": "\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u0645\u064a\u0632 \u0645\u0635\u0645\u0645 UI \u0639\u0646 \u0645\u0635\u0645\u0645 \u0627\u0644\u062c\u0631\u0627\u0641\u064a\u0643 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0635\u0645\u0645 UI \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0648\u0633\u0644\u0648\u0643 \u0627\u0644\u0639\u0646\u0627\u0635\u0631\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u062c\u0631\u0627\u0641\u064a\u0643 \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0637\u0628\u0627\u0639\u0629 \u0648\u0627\u0644\u0635\u0648\u0631\u0629 \u0627\u0644\u062b\u0627\u0628\u062a\u0629."}, {"key": "B", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "C", "text": "\u0645\u0635\u0645\u0645 \u0627\u0644\u062c\u0631\u0627\u0641\u064a\u0643 \u064a\u0628\u0631\u0645\u062c."}, {"key": "D", "text": "\u0645\u0635\u0645\u0645 UI \u0644\u0627 \u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0623\u0644\u0648\u0627\u0646."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q44", "number": 44, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0645\u0647\u0627\u0645\" (Tasks) \u0641\u064a \u0633\u064a\u0627\u0642 UX\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0648\u0627\u062c\u0628\u0627\u062a \u0627\u0644\u0645\u0628\u0631\u0645\u062c\u064a\u0646."}, {"key": "B", "text": "\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u064a \u064a\u0633\u0639\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u062d\u0642\u064a\u0642\u0647\u0627 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "C", "text": "\u0623\u0648\u0627\u0645\u0631 \u0646\u0638\u0627\u0645 \u0627\u0644\u062a\u0634\u063a\u064a\u0644."}, {"key": "D", "text": "\u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q45", "number": 45, "text": "\u0643\u064a\u0641 \u064a\u0648\u0641\u0631 Bootstrap \"\u0648\u0642\u062a \u0627\u0644\u0645\u0637\u0648\u0631\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0643\u062a\u0628 \u0627\u0644\u0643\u0648\u062f \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u062f\u0648\u0646 \u062a\u062f\u062e\u0644."}, {"key": "B", "text": "\u064a\u0648\u0641\u0631 \u0643\u0648\u062f CSS \u0648 HTML \u062c\u0627\u0647\u0632\u0627\u064b \u0644\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0634\u0627\u0626\u0639\u0629."}, {"key": "C", "text": "\u064a\u0645\u0646\u0639 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "D", "text": "\u064a\u062c\u0639\u0644 \u0627\u0644\u0645\u0648\u0642\u0639 \u0623\u0633\u0631\u0639 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q46", "number": 46, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"Viewport\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0643\u0628\u064a\u0631."}, {"key": "B", "text": "\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a\u0629 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632."}, {"key": "C", "text": "\u062d\u062c\u0645 \u0627\u0644\u0645\u0644\u0641."}, {"key": "D", "text": "\u062f\u0642\u0629 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q47", "number": 47, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062a\u0628\u0631 \u0645\u064a\u0632\u0629 \"\u062a\u0646\u0627\u0641\u0633\u064a\u0629\" \u0644\u062a\u0635\u0645\u064a\u0645 UI \u0627\u0644\u062c\u064a\u062f\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u064a\u0627\u062f\u0629 \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0645\u0646\u062a\u062c \u0648\u062a\u0648\u0641\u064a\u0631 \u062a\u062c\u0631\u0628\u0629 \u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u0627\u0626\u0642\u0629."}, {"key": "C", "text": "\u062a\u0639\u0642\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645."}, {"key": "D", "text": "\u062a\u0642\u0644\u064a\u062f \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u064a\u0646."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q48", "number": 48, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0642\u0627\u0628\u0644\u064a\u0629 \u0644\u0644\u062a\u0639\u0644\u0645\" (Learnability) \u0641\u064a \u0645\u0628\u0627\u062f\u0626 UI\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u0630\u0643\u064a\u0627\u064b."}, {"key": "B", "text": "\u0645\u062f\u0649 \u0633\u0647\u0648\u0644\u0629 \u062a\u0639\u0644\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u0646\u0638\u0627\u0645 \u0645\u0646 \u0623\u0648\u0644 \u0645\u0631\u0629."}, {"key": "C", "text": "\u0648\u062c\u0648\u062f \u062f\u0648\u0631\u0627\u062a \u062a\u062f\u0631\u064a\u0628\u064a\u0629 \u0645\u0643\u062b\u0641\u0629."}, {"key": "D", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q49", "number": 49, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0644\u062c\u0639\u0644 \u0639\u0646\u0635\u0631 \u064a\u0639\u0631\u0636 \u0643\u0639\u0645\u0648\u062f \u0648\u0627\u062d\u062f (Full Width) \u0639\u0644\u0649 \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644\u060c \u0648\u0639\u0645\u0648\u062f\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062a\u0627\u0628\u0644\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`col-6 col-sm-12`."}, {"key": "B", "text": "`col-12 col-sm-6`."}, {"key": "C", "text": "`col-xs-1 col-sm-2`."}, {"key": "D", "text": "`col-12 col-lg-6`."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q50", "number": 50, "text": "\u0645\u0627 \u0647\u064a \u062e\u0637\u0648\u0631\u0629 \u062a\u062c\u0627\u0647\u0644 \"\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644\" (Accessibility)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062e\u0633\u0627\u0631\u0629 \u0645\u0627\u0644\u064a\u0629 \u0641\u0642\u0637."}, {"key": "B", "text": "\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0634\u0631\u064a\u062d\u0629 \u0643\u0628\u064a\u0631\u0629 \u0645\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0645\u0634\u0627\u0643\u0644 \u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0645\u062d\u062a\u0645\u0644\u0629."}, {"key": "C", "text": "\u0644\u0627 \u062e\u0637\u0648\u0631\u0629."}, {"key": "D", "text": "\u0628\u0637\u0621 \u0627\u0644\u0645\u0648\u0642\u0639."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q51", "number": 51, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI) \u0648\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UX) \u0645\u0646 \u062d\u064a\u062b \u0627\u0644\u062a\u0639\u0631\u064a\u0641 \u0648\u0627\u0644\u0647\u062f\u0641.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-3-q52", "number": 52, "text": "\u0623\u0630\u0643\u0631 \u0645\u0628\u0627\u062f\u0626 \u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI) \u0627\u0644\u0633\u062a\u0629.", "questionType": "text", "answerText": "1. \u0627\u0644\u0648\u0636\u0648\u062d. 2. \u0627\u0644\u0623\u0644\u0641\u0629. 3. \u062a\u062d\u0643\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645. 4. \u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0647\u0631\u0645\u064a. 5. \u0627\u0644\u0645\u0631\u0648\u0646\u0629. 6. \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644."}, {"id": "hci-lecture-3-q53", "number": 53, "text": "\u0627\u0634\u0631\u062d \u0645\u0631\u0627\u062d\u0644 \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UX) \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0628\u0627\u062e\u062a\u0635\u0627\u0631.", "questionType": "text", "answerText": "1. \u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c (\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a). 2. \u0628\u062d\u062b \u0627\u0644\u0645\u0646\u062a\u062c (\u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u0633\u0648\u0642). 3. \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (\u0634\u062e\u0635\u064a\u0627\u062a \u0648\u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a). 4. \u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a (\u0627\u0644\u0647\u064a\u0643\u0644 \u0648\u0627\u0644\u062a\u0646\u0642\u0644). 5. \u0627\u0644\u062a\u0635\u0645\u064a\u0645 (\u0627\u0644\u0631\u0633\u0648\u0645\u0627\u062a \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062c). 6. \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0648\u0627\u0644\u062a\u062d\u0642\u0642."}, {"id": "hci-lecture-3-q54", "number": 54, "text": "\u0645\u0627 \u0647\u0648 \"\u0646\u0638\u0627\u0645 \u0627\u0644\u0634\u0628\u0643\u0629\" (Grid System) \u0641\u064a Bootstrap\u061f \u0648\u0643\u064a\u0641 \u064a\u0639\u0645\u0644\u061f", "questionType": "text", "answerText": "\u0647\u0648 \u0646\u0638\u0627\u0645 \u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0635\u0641\u062d\u0629 \u064a\u0642\u0633\u0645\u0647\u0627 \u0625\u0644\u0649 12 \u0639\u0645\u0648\u062f\u0627\u064b \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0627\u064b. \u064a\u0633\u0645\u062d \u0644\u0644\u0645\u0637\u0648\u0631 \u0628\u062a\u062d\u062f\u064a\u062f \u0639\u0631\u0636 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a (\u0645\u062b\u0644 `col-md-6`) \u0644\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0643\u064a\u0641\u064a\u0629 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0623\u0641\u0642\u064a\u0627\u064b."}, {"id": "hci-lecture-3-q55", "number": 55, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644\" (Accessibility)\u061f \u0648\u0643\u064a\u0641 \u064a\u0645\u0643\u0646 \u062a\u0637\u0628\u064a\u0642\u0647\u0627\u061f", "questionType": "text", "answerText": "\u062a\u0639\u0646\u064a \u062a\u0635\u0645\u064a\u0645 \u0645\u0646\u062a\u062c\u0627\u062a \u064a\u0645\u0643\u0646 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0645\u060c \u0628\u0645\u0627 \u0641\u064a\u0647\u0645 \u0630\u0648\u0648 \u0627\u0644\u0625\u0639\u0627\u0642\u0629."}, {"id": "hci-lecture-3-q56", "number": 56, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `col-sm` \u0648 `col-lg`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-3-q57", "number": 57, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u0643\u0648\u0646 \u0645\u0646\u0647\u0627 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI Elements)\u061f", "questionType": "text", "answerText": "1. \u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0625\u062f\u062e\u0627\u0644 (Input Controls). 2. \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u0646\u0642\u0644 (Navigational Components). 3. \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u064a\u0629 (Informational Components). 4. \u0627\u0644\u062d\u0627\u0648\u064a\u0627\u062a (Containers)."}, {"id": "hci-lecture-3-q58", "number": 58, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u0641\u0631\u0627\u063a \u0627\u0644\u0633\u0644\u0628\u064a\" (Negative Space) \u0645\u0647\u0645\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "text", "answerText": "\u0644\u0627 \u064a\u0639\u062a\u0628\u0631 \u0645\u0633\u0627\u062d\u0629 \u0645\u0647\u062f\u0631\u0629\u060c \u0628\u0644 \u0639\u0646\u0635\u0631 \u062a\u0635\u0645\u064a\u0645\u064a \u064a\u0633\u0627\u0639\u062f \u0639\u0644\u0649 \u0641\u0635\u0644 \u0627\u0644\u0639\u0646\u0627\u0635\u0631\u060c \u0625\u0631\u0627\u062d\u0629 \u0627\u0644\u0639\u064a\u0646\u060c \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0644\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0647\u0645."}, {"id": "hci-lecture-3-q59", "number": 59, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0645\u0647\u0627\u0645 \u0645\u0635\u0645\u0645 UI \u0648\u0645\u0635\u0645\u0645 UX\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-3-q60", "number": 60, "text": "\u0643\u064a\u0641 \u064a\u062f\u0639\u0645 Bootstrap \u0645\u0641\u0647\u0648\u0645 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0633\u0631\u064a\u0639 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629\" (Responsive Design)\u061f", "questionType": "text", "answerText": "\u0645\u0646 \u062e\u0644\u0627\u0644 \u0646\u0638\u0627\u0645 \u0627\u0644\u0634\u0628\u0643\u0629 \u0627\u0644\u0645\u062a\u063a\u064a\u0631\u060c \u062d\u064a\u062b \u064a\u0645\u0643\u0646 \u0644\u0644\u0645\u0637\u0648\u0631 \u062a\u062d\u062f\u064a\u062f \u0643\u0644\u0627\u0633\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629 \u0644\u0646\u0641\u0633 \u0627\u0644\u0639\u0646\u0635\u0631 \u0644\u064a\u062a\u0635\u0631\u0641 \u0628\u0634\u0643\u0644 \u0645\u062e\u062a\u0644\u0641 \u0639\u0644\u0649 \u0623\u062d\u062c\u0627\u0645 \u0634\u0627\u0634\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629 (\u0645\u062b\u0644\u0627\u064b: \u0639\u0645\u0648\u062f \u0643\u0627\u0645\u0644 \u0641\u064a \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644\u060c \u0648\u0646\u0635\u0641 \u0639\u0645\u0648\u062f \u0641\u064a \u0627\u0644\u0643\u0645\u0628\u064a\u0648\u062a\u0631)."}]}, {"id": "hci-lecture-4", "title": "\u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629", "questions": [{"id": "hci-lecture-4-q1", "number": 1, "text": "\u064a\u0645\u0643\u0646 \u062a\u0637\u0628\u064a\u0642 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0623\u0632\u0631\u0627\u0631 (`.btn`) \u0639\u0644\u0649 \u0639\u0646\u0627\u0635\u0631 `<a>` \u0648 `<input>` \u0648\u0644\u064a\u0633 \u0641\u0642\u0637 `<button>`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q2", "number": 2, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.btn-outline-*` \u064a\u0639\u0637\u064a \u0627\u0644\u0632\u0631 \u062e\u0644\u0641\u064a\u0629 \u0645\u0644\u0648\u0646\u0629 \u0645\u0639 \u062d\u062f\u0648\u062f \u0634\u0641\u0627\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q3", "number": 3, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.btn-sm` \u064a\u062c\u0639\u0644 \u0627\u0644\u0632\u0631 \u0643\u0628\u064a\u0631\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q4", "number": 4, "text": "`.nav-tabs` \u0648 `.nav-pills` \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0645\u0627 \u0645\u0639\u0627\u064b \u0644\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u0642\u0627\u0626\u0645\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q5", "number": 5, "text": "\u0627\u0644\u062a\u0628\u0648\u064a\u0628\u0627\u062a \u0627\u0644\u062f\u064a\u0646\u0627\u0645\u064a\u0643\u064a\u0629 (Dynamic Tabs) \u062a\u062a\u0637\u0644\u0628 \u0648\u062c\u0648\u062f `.tab-content` \u0648 `.tab-pane`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q6", "number": 6, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.navbar-expand-lg` \u064a\u062c\u0639\u0644 \u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0646\u0642\u0644 \u0645\u0637\u0648\u064a\u0627\u064b (Collapsed) \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0643\u0628\u064a\u0631\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q7", "number": 7, "text": "`.table-striped` \u064a\u0636\u064a\u0641 \u0644\u0648\u0646\u0627\u064b \u0645\u062e\u062a\u0644\u0641\u0627\u064b \u0644\u0644\u0635\u0641\u0648\u0641 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 (Zebra Striping).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q8", "number": 8, "text": "`.table-hover` \u064a\u063a\u064a\u0631 \u0644\u0648\u0646 \u0627\u0644\u0635\u0641 \u0639\u0646\u062f \u0627\u0644\u0646\u0642\u0631 \u0639\u0644\u064a\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q9", "number": 9, "text": "`.table-dark` \u064a\u062d\u0648\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u062f\u0627\u0643\u0646 (\u062e\u0644\u0641\u064a\u0629 \u0633\u0648\u062f\u0627\u0621 \u0648\u0646\u0635 \u0623\u0628\u064a\u0636).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q10", "number": 10, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.table-responsive` \u064a\u062c\u0639\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u064a\u062a\u063a\u064a\u0631 \u0634\u0643\u0644\u0647 \u0644\u064a\u062a\u0646\u0627\u0633\u0628 \u0645\u0639 \u0627\u0644\u0634\u0627\u0634\u0629 \u0627\u0644\u0635\u063a\u064a\u0631\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0623\u0639\u0645\u062f\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q11", "number": 11, "text": "\"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0639\u0645\u0648\u062f\u064a\" (Vertical Form) \u0647\u0648 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0641\u064a Bootstrap.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q12", "number": 12, "text": "\"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0623\u0641\u0642\u064a\" (Horizontal Form) \u064a\u062a\u0637\u0644\u0628 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0634\u0628\u0643\u0629 (Grid classes) \u0645\u062b\u0644 `.row` \u0648 `.col`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q13", "number": 13, "text": "\"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u0636\u0645\u0646\" (Inline Form) \u064a\u0639\u0631\u0636 \u062c\u0645\u064a\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0641\u064a \u0633\u0637\u0631 \u0648\u0627\u062d\u062f \u0645\u062a\u0635\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q14", "number": 14, "text": "`.card-group` \u064a\u0639\u0631\u0636 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a \u0628\u0641\u0648\u0627\u0635\u0644 \u0648\u0645\u0633\u0627\u0641\u0627\u062a \u0628\u064a\u0646\u0647\u0627.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q15", "number": 15, "text": "`.card-img-top` \u064a\u0636\u0639 \u0627\u0644\u0635\u0648\u0631\u0629 \u0641\u064a \u0623\u0639\u0644\u0649 \u0627\u0644\u0628\u0637\u0627\u0642\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q16", "number": 16, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.stretched-link` \u064a\u062c\u0639\u0644 \u0643\u0627\u0645\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0646\u0642\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q17", "number": 17, "text": "\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 `.table-danger` \u0644\u062a\u0644\u0648\u064a\u0646 \u0635\u0641 \u0641\u064a \u0627\u0644\u062c\u062f\u0648\u0644 \u0628\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u062d\u0645\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q18", "number": 18, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.active` \u0641\u064a \u0627\u0644\u062a\u0646\u0642\u0644 \u064a\u062c\u0639\u0644 \u0627\u0644\u0639\u0646\u0635\u0631 \u064a\u0628\u062f\u0648 \u0645\u0641\u0639\u0644\u0627\u064b (\u0645\u0638\u0644\u0644\u0627\u064b).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q19", "number": 19, "text": "Spinner \u0647\u0648 \u0645\u0643\u0648\u0646 \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0639\u0631\u0636 \u0642\u0627\u0626\u0645\u0629 \u0645\u0646\u0633\u062f\u0644\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q20", "number": 20, "text": "`.container-fluid` \u064a\u0639\u0637\u064a \u062d\u0627\u0648\u064a\u0629 \u0628\u0639\u0631\u0636 \u0643\u0627\u0645\u0644 \u0627\u0644\u0634\u0627\u0634\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q21", "number": 21, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u0625\u0646\u0634\u0627\u0621 \u0632\u0631 \u0623\u062d\u0645\u0631 \u064a indicate \u062e\u0637\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.btn-danger`"}, {"key": "B", "text": "`.btn-warning`"}, {"key": "C", "text": "`.btn-red`"}, {"key": "D", "text": "`.btn-error`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q22", "number": 22, "text": "\u0643\u064a\u0641 \u062a\u0635\u0646\u0639 \u0632\u0631\u0627\u064b \u0634\u0641\u0627\u0641\u0627\u064b \u0630\u0627 \u062d\u062f\u0648\u062f \u0632\u0631\u0642\u0627\u0621\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.btn-primary`"}, {"key": "B", "text": "`.btn-outline-primary`"}, {"key": "C", "text": "`.btn-transparent`"}, {"key": "D", "text": "`.btn-border`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q23", "number": 23, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.nav-tabs` \u0648 `.nav-pills`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Tabs \u0623\u0641\u0642\u064a\u0629\u060c Pills \u0639\u0645\u0648\u062f\u064a\u0629."}, {"key": "B", "text": "Tabs \u062a\u0628\u062f\u0648 \u0643\u0645\u0644\u0641\u0627\u062a\u060c Pills \u062a\u0628\u062f\u0648 \u0643\u0623\u0632\u0631\u0627\u0631 \u0645\u0633\u062a\u062f\u064a\u0631\u0629."}, {"key": "C", "text": "Tabs \u0644\u0644\u062a\u0646\u0642\u0644\u060c Pills \u0644\u0644\u0625\u062f\u062e\u0627\u0644."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q24", "number": 24, "text": "\u0644\u062c\u0639\u0644 \u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0646\u0642\u0644 (Navbar) \u064a\u062e\u062a\u0641\u064a \u0648\u064a\u0638\u0647\u0631 \u0643\u0642\u0627\u0626\u0645\u0629 (Toggle) \u0639\u0644\u0649 \u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062a\u0627\u0628\u0644\u062a\u060c \u0646\u0633\u062a\u062e\u062f\u0645:", "questionType": "choice", "options": [{"key": "A", "text": "`.navbar-expand-sm`"}, {"key": "B", "text": "`.navbar-expand-lg`"}, {"key": "C", "text": "`.navbar-hide`"}, {"key": "D", "text": "`.navbar-toggle`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q25", "number": 25, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0630\u064a \u064a\u0636\u064a\u0641 \u062d\u062f\u0648\u062f\u0627\u064b \u0644\u062c\u0645\u064a\u0639 \u062e\u0644\u0627\u064a\u0627 \u0627\u0644\u062c\u062f\u0648\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.table-striped`"}, {"key": "B", "text": "`.table-bordered`"}, {"key": "C", "text": "`.table-hover`"}, {"key": "D", "text": "`.table-borderless`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q26", "number": 26, "text": "\u0623\u064a \u0646\u0645\u0648\u0630\u062c (Form) \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0648\u0636\u0639 \u0627\u0644\u062a\u0633\u0645\u064a\u0629 (Label) \u0648\u0627\u0644\u062d\u0642\u0644 (Input) \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0633\u0637\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Vertical Form."}, {"key": "B", "text": "Horizontal Form."}, {"key": "C", "text": "Inline Form."}, {"key": "D", "text": "Grid Form."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q27", "number": 27, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.card-group` \u0648 `.card-deck`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Group \u064a\u0644\u0635\u0642 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a\u060c Deck \u064a\u062a\u0631\u0643 \u0641\u0631\u0627\u063a\u0627\u062a \u0628\u064a\u0646\u0647\u0627."}, {"key": "B", "text": "Deck \u064a\u0644\u0635\u0642 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a\u060c Group \u064a\u062a\u0631\u0643 \u0641\u0631\u0627\u063a\u0627\u062a."}, {"key": "C", "text": "Group \u0639\u0645\u0648\u062f\u064a\u060c Deck \u0623\u0641\u0642\u064a."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q28", "number": 28, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u0639\u0631\u0636 \u0646\u0635 \u0641\u0648\u0642 \u0635\u0648\u0631\u0629 \u062e\u0644\u0641\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.card-img-top`"}, {"key": "B", "text": "`.card-img-overlay`"}, {"key": "C", "text": "`.card-text-overlay`"}, {"key": "D", "text": "`.img-text`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q29", "number": 29, "text": "\u0645\u0627 \u0647\u0648 \u062f\u0648\u0631 `.spinner-border`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0625\u0636\u0627\u0641\u0629 \u062d\u062f\u0648\u062f \u0644\u0644\u062c\u062f\u0648\u0644."}, {"key": "B", "text": "\u0639\u0631\u0636 \u062f\u0627\u0626\u0631\u0629 \u062a\u062d\u0645\u064a\u0644 (Loading) \u062a\u062f\u0648\u0631."}, {"key": "C", "text": "\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062d\u062f\u0648\u062f."}, {"key": "D", "text": "\u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u0639\u0646\u0635\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q30", "number": 30, "text": "\u0643\u064a\u0641 \u062a\u062c\u0639\u0644 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u064a\u0639\u0631\u0636 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0641\u064a \u0635\u0641 \u0648\u0627\u062d\u062f \u0645\u0636\u063a\u0648\u0637\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.form-horizontal`"}, {"key": "B", "text": "`.form-inline`"}, {"key": "C", "text": "`.form-row`"}, {"key": "D", "text": "`.inline-form`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q31", "number": 31, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0633\u064a\u0627\u0642\u064a \u0644\u0644\u062f\u0644\u0627\u0644\u0629 \u0639\u0644\u0649 \"\u0646\u062c\u0627\u062d\" \u0641\u064a \u0627\u0644\u062c\u062f\u0648\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.table-primary`"}, {"key": "B", "text": "`.table-warning`"}, {"key": "C", "text": "`.table-success`"}, {"key": "D", "text": "`.table-info`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-4-q32", "number": 32, "text": "\u0645\u0627 \u0641\u0627\u0626\u062f\u0629 `.stretched-link`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u064a\u0627\u062f\u0629 \u0637\u0648\u0644 \u0627\u0644\u0631\u0627\u0628\u0637."}, {"key": "B", "text": "\u062c\u0639\u0644 \u0643\u0627\u0645\u0644 \u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062d\u0627\u0648\u064a\u0629 (Card) \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0646\u0642\u0631 \u0643\u0631\u0627\u0628\u0637."}, {"key": "C", "text": "\u0641\u062a\u062d \u0627\u0644\u0631\u0627\u0628\u0637 \u0641\u064a \u0635\u0641\u062d\u0629 \u062c\u062f\u064a\u062f\u0629."}, {"key": "D", "text": "\u062a\u063a\u064a\u064a\u0631 \u0644\u0648\u0646 \u0627\u0644\u0631\u0627\u0628\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q33", "number": 33, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u062c\u0639\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0645\u0631\u064a\u0631 \u0627\u0644\u0623\u0641\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.table-scroll`"}, {"key": "B", "text": "`.table-responsive`"}, {"key": "C", "text": "`.responsive-table`"}, {"key": "D", "text": "`.table-fluid`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q34", "number": 34, "text": "\u0641\u064a \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0623\u0641\u0642\u064a\u060c \u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u0636\u0628\u0637 \u0645\u062d\u0627\u0630\u0627\u0629 \u0627\u0644\u062a\u0633\u0645\u064a\u0627\u062a (Labels) \u0639\u0645\u0648\u062f\u064a\u0627\u064b\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.col-form-label`"}, {"key": "B", "text": "`.form-label`"}, {"key": "C", "text": "`.label-vertical`"}, {"key": "D", "text": "`.align-label`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q35", "number": 35, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 \u0627\u0644\u0643\u0644\u0627\u0633 `.disabled` \u0639\u0644\u0649 \u0627\u0644\u0632\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u062c\u0639\u0644\u0647 \u064a\u0644\u0645\u0639."}, {"key": "B", "text": "\u064a\u062c\u0639\u0644\u0647 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644 \u0644\u0644\u0646\u0642\u0631 \u0648\u0634\u0643\u0644\u0647 \u0628\u0627\u0647\u062a."}, {"key": "C", "text": "\u064a\u062c\u0639\u0644\u0647 \u0623\u0635\u063a\u0631."}, {"key": "D", "text": "\u064a\u062d\u0630\u0641\u0647."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q36", "number": 36, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u0644\u064a\u0633 \u0645\u0646 \u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0628\u0637\u0627\u0642\u0629 (Card)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.card-body`"}, {"key": "B", "text": "`.card-footer`"}, {"key": "C", "text": "`.card-input`"}, {"key": "D", "text": "`.card-title`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-4-q37", "number": 37, "text": "\u0643\u064a\u0641 \u062a\u0636\u064a\u0641 \"\u062a\u0623\u062e\u064a\u0631\u0627\u064b\" (Fade) \u0639\u0646\u062f \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0628\u064a\u0646 \u0627\u0644\u062a\u0628\u0648\u064a\u0628\u0627\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0643\u0644\u0627\u0633 `.fade`"}, {"key": "B", "text": "\u0643\u0644\u0627\u0633 `.slow`"}, {"key": "C", "text": "\u062e\u0627\u0635\u064a\u0629 `delay`"}, {"key": "D", "text": "\u0644\u0627 \u064a\u0645\u0643\u0646 \u0630\u0644\u0643"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q38", "number": 38, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0646\u0642\u0644 \u0627\u0644\u062f\u0627\u0643\u0646 (Dark Navbar)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.bg-black`"}, {"key": "B", "text": "`.navbar-dark`"}, {"key": "C", "text": "`.bg-dark`"}, {"key": "D", "text": "`.dark-navbar`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-4-q39", "number": 39, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.table-borderless` \u0648 `.table` \u0627\u0644\u0639\u0627\u062f\u064a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Borderless \u064a\u0636\u064a\u0641 \u062d\u062f\u0648\u062f\u0627\u064b."}, {"key": "B", "text": "Borderless \u064a\u0632\u064a\u0644 \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u062f\u0648\u062f."}, {"key": "C", "text": "Borderless \u064a\u062c\u0639\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u0635\u063a\u064a\u0631\u0627\u064b."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q40", "number": 40, "text": "\u0645\u0627 \u0647\u0648 `.card-subtitle`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0639\u0646\u0648\u0627\u0646 \u0631\u0626\u064a\u0633\u064a."}, {"key": "B", "text": "\u0639\u0646\u0648\u0627\u0646 \u0641\u0631\u0639\u064a \u064a\u0638\u0647\u0631 \u062a\u062d\u062a \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0631\u0626\u064a\u0633\u064a \u0628\u0644\u0648\u0646 \u0623\u0641\u062a\u062d."}, {"key": "C", "text": "\u062a\u0630\u064a\u064a\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629."}, {"key": "D", "text": "\u0631\u0627\u0628\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q41", "number": 41, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u062c\u0645\u064a\u0639 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0646\u0645\u0648\u0630\u062c (Label + Input) \u0648\u0625\u0636\u0627\u0641\u0629 \u0647\u0627\u0645\u0634 \u0633\u0641\u0644\u064a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.form-group`"}, {"key": "B", "text": "`.group-form`"}, {"key": "C", "text": "`.input-group`"}, {"key": "D", "text": "`.form-row`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q42", "number": 42, "text": "\u0623\u064a \u0643\u0644\u0627\u0633 \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u062c\u0639\u0644 \u0627\u0644\u0635\u0648\u0631\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u062a\u0623\u062e\u0630 \u0643\u0627\u0645\u0644 \u0639\u0631\u0636 \u0627\u0644\u0628\u0637\u0627\u0642\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.img-fluid`"}, {"key": "B", "text": "`.card-img-top` (\u0623\u0648 `.card-img`)"}, {"key": "C", "text": "`.img-full`"}, {"key": "D", "text": "`.w-100`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q43", "number": 43, "text": "\u0645\u0627 \u0647\u064a \u0648\u0638\u064a\u0641\u0629 `.navbar-toggler`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u0631 \u0644\u0641\u062a\u062d \u0648\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629."}, {"key": "B", "text": "\u062a\u063a\u064a\u064a\u0631 \u0644\u0648\u0646 \u0627\u0644\u0634\u0631\u064a\u0637."}, {"key": "C", "text": "\u0625\u0636\u0627\u0641\u0629 \u0634\u0639\u0627\u0631."}, {"key": "D", "text": "\u0631\u0628\u0637 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0627\u0639\u062f\u0629 \u0628\u064a\u0627\u0646\u0627\u062a."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q44", "number": 44, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u0644\u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \"\u062a\u062d\u0630\u064a\u0631\" (Warning) \u0641\u064a \u0627\u0644\u062c\u062f\u0627\u0648\u0644 \u0648\u0627\u0644\u0623\u0632\u0631\u0627\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.danger`"}, {"key": "B", "text": "`.warning`"}, {"key": "C", "text": "`.alert`"}, {"key": "D", "text": "`.info`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q45", "number": 45, "text": "\u0643\u064a\u0641 \u064a\u0645\u0643\u0646\u0643 \u062c\u0639\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a \u0645\u062a\u0633\u0627\u0648\u064a\u0629 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u0641\u064a `.card-deck`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u062c\u0628 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u064a\u062f\u0648\u064a\u0627\u064b."}, {"key": "B", "text": "\u064a\u062d\u062f\u062b \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Flexbox."}, {"key": "C", "text": "\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633 `.h-equal`."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0645\u0643\u0646 \u0630\u0644\u0643."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q46", "number": 46, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `form-control` \u0648 `btn`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`form-control` \u0644\u0644\u062d\u0642\u0648\u0644\u060c `btn` \u0644\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "B", "text": "`form-control` \u0644\u0644\u0623\u0632\u0631\u0627\u0631\u060c `btn` \u0644\u0644\u062d\u0642\u0648\u0644."}, {"key": "C", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u0644\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "D", "text": "\u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647\u0645\u0627."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q47", "number": 47, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0644\u062c\u0639\u0644 `.nav` \u062a\u0645\u062a\u062f \u0628\u0639\u0631\u0636 \u0643\u0627\u0645\u0644 \u0648\u062a\u0648\u0632\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.nav-fill`"}, {"key": "B", "text": "`.nav-full`"}, {"key": "C", "text": "`.nav-wide`"}, {"key": "D", "text": "`.nav-stretch`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q48", "number": 48, "text": "\u0645\u0627 \u0627\u0644\u0641\u0627\u0626\u062f\u0629 \u0645\u0646 `.form-control-lg`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0635\u063a\u064a\u0631\u0627\u064b."}, {"key": "B", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0643\u0628\u064a\u0631\u0627\u064b."}, {"key": "C", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637."}, {"key": "D", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0625\u0644\u0632\u0627\u0645\u064a\u0627\u064b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q49", "number": 49, "text": "\u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0625\u0636\u0627\u0641\u0629 \u0631\u0627\u0628\u0637 \u062f\u0627\u062e\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629\u060c \u0623\u064a \u0643\u0644\u0627\u0633 \u062a\u0636\u064a\u0641 \u0644\u0647\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.card-url`"}, {"key": "B", "text": "`.card-link`"}, {"key": "C", "text": "`.card-a`"}, {"key": "D", "text": "`.link-card`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q50", "number": 50, "text": "\u0623\u064a\u0646 \u0646\u0636\u0639 \u0627\u0644\u0643\u0644\u0627\u0633 `.table-responsive`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062f\u0627\u062e\u0644 `<table>`."}, {"key": "B", "text": "\u062f\u0627\u062e\u0644 `<div>` \u064a\u062d\u064a\u0637 \u0628\u0640 `<table>`."}, {"key": "C", "text": "\u062f\u0627\u062e\u0644 `<tr>`."}, {"key": "D", "text": "\u062f\u0627\u062e\u0644 `<td>`."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q51", "number": 51, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 `.btn-primary` \u0648 `.btn-outline-primary`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q52", "number": 52, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062e\u0637\u0648\u0627\u062a \u0644\u0625\u0646\u0634\u0627\u0621 \"\u062a\u0628\u0648\u064a\u0628\u0627\u062a \u062f\u064a\u0646\u0627\u0645\u064a\u0643\u064a\u0629\" (Dynamic Tabs) \u0641\u064a Bootstrap\u061f", "questionType": "text", "answerText": "1. \u0625\u0646\u0634\u0627\u0621 \u0642\u0627\u0626\u0645\u0629 \u062a\u0646\u0642\u0644 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `.nav-tabs` \u0648\u0625\u0636\u0627\u0641\u0629 `data-toggle=\"tab\"`. 2. \u0625\u0646\u0634\u0627\u0621 \u062d\u0627\u0648\u064a\u0629 \u0645\u062d\u062a\u0648\u0649 `.tab-content`. 3. \u0625\u0636\u0627\u0641\u0629 `.tab-pane` \u0644\u0643\u0644 \u0645\u062d\u062a\u0648\u0649 \u0645\u0639 `id` \u0641\u0631\u064a\u062f. 4. \u0631\u0628\u0637 \u0627\u0644\u0631\u0648\u0627\u0628\u0637 \u0628\u0627\u0644\u0640 `id` \u0639\u0628\u0631 `href`."}, {"id": "hci-lecture-4-q53", "number": 53, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.table-striped` \u0648 `.table-hover`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q54", "number": 54, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.card-group` \u0648 `.card-deck`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q55", "number": 55, "text": "\u0643\u064a\u0641 \u062a\u0646\u0634\u0626 \u0646\u0645\u0648\u0630\u062c\u0627\u064b \u0623\u0641\u0642\u064a\u0627\u064b (Horizontal Form)\u061f", "questionType": "text", "answerText": "1. \u0625\u0636\u0627\u0641\u0629 \u0643\u0644\u0627\u0633 `.row` \u0644\u0644\u0645\u062c\u0645\u0648\u0639\u0629 (`.form-group`). 2. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0634\u0628\u0643\u0629 (\u0645\u062b\u0644 `.col-sm-2`) \u0644\u0644\u062a\u0633\u0645\u064a\u0627\u062a. 3. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0634\u0628\u0643\u0629 (\u0645\u062b\u0644 `.col-sm-10`) \u0644\u0644\u062d\u0642\u0648\u0644. 4. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 `.col-form-label` \u0644\u0644\u062a\u0633\u0645\u064a\u0627\u062a \u0644\u0645\u062d\u0627\u0630\u0627\u062a\u0647\u0627 \u0639\u0645\u0648\u062f\u064a\u0627\u064b."}, {"id": "hci-lecture-4-q56", "number": 56, "text": "\u0645\u0627 \u0647\u064a \u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0628\u0637\u0627\u0642\u0629 (Card) \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q57", "number": 57, "text": "\u0645\u0627 \u0641\u0627\u0626\u062f\u0629 `.stretched-link`\u061f", "questionType": "text", "answerText": "\u064a\u062c\u0639\u0644 \u0643\u0627\u0645\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0646\u0642\u0631 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0631\u0627\u0628\u0637 `::after` \u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u062d\u0627\u0648\u064a\u0629 \u0627\u0644\u0623\u0628 (\u0645\u0641\u064a\u062f \u0644\u0644\u0633\u064a\u0648 \u0648\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645)."}, {"id": "hci-lecture-4-q58", "number": 58, "text": "\u0627\u0634\u0631\u062d \u0645\u0641\u0647\u0648\u0645 \"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u0636\u0645\u0646\" (Inline Form).", "questionType": "text", "answerText": "\u0647\u0648 \u0646\u0645\u0648\u0630\u062c \u064a\u062a\u0645 \u0641\u064a\u0647 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 (\u0627\u0644\u062a\u0633\u0645\u064a\u0627\u062a \u0648\u0627\u0644\u062d\u0642\u0648\u0644 \u0648\u0627\u0644\u0623\u0632\u0631\u0627\u0631) \u0641\u064a \u0635\u0641 \u0623\u0641\u0642\u064a \u0648\u0627\u062d\u062f\u060c \u0648\u064a\u0633\u062a\u062e\u062f\u0645 \u0639\u0627\u062f\u0629\u064b \u0644\u062d\u0642\u0648\u0644 \u0627\u0644\u0628\u062d\u062b \u0623\u0648 \u0646\u0645\u0627\u0630\u062c \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0627\u0644\u0628\u0633\u064a\u0637\u0629. \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0643\u0644\u0627\u0633 `.form-inline`."}, {"id": "hci-lecture-4-q59", "number": 59, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.navbar-light` \u0648 `.navbar-dark`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q60", "number": 60, "text": "\u0643\u064a\u0641 \u062a\u0636\u064a\u0641 \u0623\u064a\u0642\u0648\u0646\u0629 \u062a\u062d\u0645\u064a\u0644 (Spinner) \u062f\u0627\u062e\u0644 \u0632\u0631\u061f", "questionType": "text", "answerText": "\u0628\u0648\u0636\u0639 \u0639\u0646\u0635\u0631 `<span>` \u062f\u0627\u062e\u0644 \u0627\u0644\u0632\u0631 \u0648\u0625\u0639\u0637\u0627\u0626\u0647 \u0643\u0644\u0627\u0633 `.spinner-border` \u0623\u0648 `.spinner-grow`\u060c \u0645\u0639 \u0625\u062e\u0641\u0627\u0621 \u0646\u0635 \u0627\u0644\u0632\u0631 \u0623\u0648 \u062a\u063a\u064a\u064a\u0631\u0647 \u0644\u064a\u0643\u0648\u0646 \"\u062c\u0627\u0631\u064a \u0627\u0644\u062a\u062d\u0645\u064a\u0644\"."}]}, {"id": "hci-lecture-5", "title": "\u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0627\u0644\u062e\u0627\u0645\u0633\u0629", "questions": [{"id": "hci-lecture-5-q1", "number": 1, "text": "Regex \u0641\u064a PHP \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q2", "number": 2, "text": "\u0627\u0644\u062f\u0627\u0644\u0629 `preg_match()` \u062a\u062a\u0648\u0642\u0641 \u0639\u0646\u062f \u0623\u0648\u0644 \u062a\u0637\u0627\u0628\u0642 \u062a\u062c\u062f\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q3", "number": 3, "text": "\u0627\u0644\u0646\u0645\u0637 `[1-100]` \u064a\u0639\u0646\u064a \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 1 \u0625\u0644\u0649 100.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q4", "number": 4, "text": "\u0627\u0644\u0631\u0645\u0632 `^` \u062e\u0627\u0631\u062c \u0627\u0644\u0623\u0642\u0648\u0627\u0633 `[]` \u064a\u0639\u0646\u064a \"\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631\".", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q5", "number": 5, "text": "`\\d` \u064a\u0637\u0627\u0628\u0642 \u0623\u064a \u062d\u0631\u0641 \u0644\u064a\u0633 \u0631\u0642\u0645\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q6", "number": 6, "text": "`+` \u062a\u0639\u0646\u064a \u0635\u0641\u0631 \u0623\u0648 \u0623\u0643\u062b\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q7", "number": 7, "text": "`\\s` \u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u0627\u0644\u0628\u064a\u0636\u0627\u0621 (Space, Tab, Newline).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q8", "number": 8, "text": "\u0627\u0644\u0645\u0639\u062f\u0644 `i` \u064a\u062c\u0639\u0644 \u0627\u0644\u0628\u062d\u062b \u062d\u0633\u0627\u0633\u0627\u064b \u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0623\u062d\u0631\u0641.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q9", "number": 9, "text": "`preg_replace` \u062a\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u0628\u062d\u062b \u0648\u0627\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q10", "number": 10, "text": "`?` \u062a\u0639\u0646\u064a \u0623\u0646 \u0627\u0644\u0639\u0646\u0635\u0631 \u0627\u0644\u0633\u0627\u0628\u0642 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0638\u0647\u0631 \u0645\u0631\u062a\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q11", "number": 11, "text": "`[A-Z]` \u064a\u0637\u0627\u0628\u0642 \u0623\u064a \u062d\u0631\u0641 \u0643\u0628\u064a\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q12", "number": 12, "text": "`{2,4}` \u064a\u0639\u0646\u064a \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0645\u0631\u062a\u064a\u0646 \u0623\u0648 4 \u0645\u0631\u0627\u062a \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q13", "number": 13, "text": "`|` \u062a\u0639\u0646\u064a \"\u0623\u0648\" (OR).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q14", "number": 14, "text": "\u0627\u0644\u0646\u0645\u0637 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0628\u064a\u0646 \u0634\u0631\u0637\u062a\u064a\u0646 `/pattern/` \u0641\u064a PHP.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q15", "number": 15, "text": "`$` \u062a\u0639\u0646\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0646\u0635.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q16", "number": 16, "text": "`[abc]` \u062a\u0637\u0627\u0628\u0642 \u0627\u0644\u0643\u0644\u0645\u0629 \"abc\" \u0628\u0627\u0644\u0643\u0627\u0645\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q17", "number": 17, "text": "`[^abc]` \u062a\u0637\u0627\u0628\u0642 \u0623\u064a \u062d\u0631\u0641 \u0639\u062f\u0627 a, b, c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q18", "number": 18, "text": "`preg_match_all` \u062a\u0639\u064a\u062f \u0645\u0635\u0641\u0648\u0641\u0629 \u0628\u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0637\u0627\u0628\u0642\u0627\u062a.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q19", "number": 19, "text": "`\\w` \u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u062d\u0631\u0648\u0641 \u0648\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0648\u0627\u0644\u0634\u0631\u0637\u0629 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q20", "number": 20, "text": "\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 Regex \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u064a\u063a\u0629 \u0627\u0644\u0625\u064a\u0645\u064a\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q21", "number": 21, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062f\u0627\u0644\u0629 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0646\u0645\u0637 \u0645\u0639\u064a\u0646 \u0641\u0642\u0637 (\u0646\u0639\u0645/\u0644\u0627)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`preg_replace`"}, {"key": "B", "text": "`preg_match_all`"}, {"key": "C", "text": "`preg_match`"}, {"key": "D", "text": "`preg_split`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-5-q22", "number": 22, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \u0627\u0644\u0646\u0645\u0637 `[0-9]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 0 \u0625\u0644\u0649 9."}, {"key": "B", "text": "\u0627\u0644\u0646\u0635 \"0-9\"."}, {"key": "C", "text": "\u0623\u064a \u0631\u0642\u0645 \u0639\u062f\u0627 0 \u0648 9."}, {"key": "D", "text": "\u0627\u0644\u0633\u0627\u0644\u0628 \u0648\u0627\u0644\u0635\u0641\u0631."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q23", "number": 23, "text": "\u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0639\u0646 \u0631\u0642\u0645 \u0647\u0627\u062a\u0641 \u0645\u0643\u0648\u0646 \u0645\u0646 10 \u0623\u0631\u0642\u0627\u0645 \u0628\u0627\u0644\u0636\u0628\u0637:", "questionType": "choice", "options": [{"key": "A", "text": "`\\d{10}`"}, {"key": "B", "text": "`\\d*`"}, {"key": "C", "text": "`\\d+`"}, {"key": "D", "text": "`\\d{1,10}`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q24", "number": 24, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `+` \u0648 `*`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`+` \u0635\u0641\u0631 \u0623\u0648 \u0623\u0643\u062b\u0631\u060c `*` \u0648\u0627\u062d\u062f \u0623\u0648 \u0623\u0643\u062b\u0631."}, {"key": "B", "text": "`+` \u0648\u0627\u062d\u062f \u0623\u0648 \u0623\u0643\u062b\u0631\u060c `*` \u0635\u0641\u0631 \u0623\u0648 \u0623\u0643\u062b\u0631."}, {"key": "C", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u0645\u062a\u0633\u0627\u0648\u064a."}, {"key": "D", "text": "`+` \u0644\u0644\u062c\u0645\u0639."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q25", "number": 25, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `^` \u062f\u0627\u062e\u0644 `[]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631."}, {"key": "B", "text": "\u0627\u0644\u0646\u0641\u064a (Not)."}, {"key": "C", "text": "\u0627\u0644\u0642\u0648\u0629."}, {"key": "D", "text": "\u0627\u0644\u062a\u0643\u0631\u0627\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q26", "number": 26, "text": "\u0643\u064a\u0641 \u062a\u0643\u062a\u0628 \u0646\u0645\u0637\u0627\u064b \u064a\u0642\u0628\u0644 \"color\" \u0623\u0648 \"colour\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`colou?r`"}, {"key": "B", "text": "`color|colour`"}, {"key": "C", "text": "`col(o|ou)r`"}, {"key": "D", "text": "\u062c\u0645\u064a\u0639 \u0645\u0627 \u0633\u0628\u0642 \u0635\u062d\u064a\u062d."}], "answerIndex": 3, "answerText": "D"}, {"id": "hci-lecture-5-q27", "number": 27, "text": "\u0645\u0627 \u0647\u0648 \u0646\u0627\u062a\u062c `preg_match(\"/a/\", \"A\")` \u0628\u062f\u0648\u0646 \u0645\u0639\u062f\u0644 `i`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "0"}, {"key": "C", "text": "Error"}, {"key": "D", "text": "True"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q28", "number": 28, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `\\S`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0633\u0627\u0641\u0629."}, {"key": "B", "text": "\u062d\u0631\u0641 \u063a\u064a\u0631 \u0645\u0633\u0627\u0641\u0629."}, {"key": "C", "text": "\u062d\u0631\u0641 \u062e\u0627\u0635."}, {"key": "D", "text": "\u0643\u0644\u0645\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q29", "number": 29, "text": "\u0623\u064a \u0646\u0645\u0637 \u064a\u0637\u0627\u0628\u0642 \u0643\u0644\u0645\u0629 \u062a\u0628\u062f\u0623 \u0628\u062d\u0631\u0641 \u0643\u0628\u064a\u0631 \u0648\u062a\u0644\u064a\u0647\u0627 \u0623\u062d\u0631\u0641 \u0635\u063a\u064a\u0631\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`^[a-z]`"}, {"key": "B", "text": "`^[A-Z][a-z]+$`"}, {"key": "C", "text": "`[A-Z].*`"}, {"key": "D", "text": "`^[A-Z]+$`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q30", "number": 30, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `\\d` \u0648 `\\D`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\\d` \u0644\u0644\u0623\u0631\u0642\u0627\u0645\u060c `\\D` \u0644\u063a\u064a\u0631 \u0627\u0644\u0623\u0631\u0642\u0627\u0645."}, {"key": "B", "text": "\u0627\u0644\u0639\u0643\u0633."}, {"key": "C", "text": "`\\d` \u0644\u0644\u062a\u0627\u0631\u064a\u062e."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q31", "number": 31, "text": "\u0645\u0627 \u0647\u064a \u0641\u0627\u0626\u062f\u0629 `{n,m}`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0645\u0646 n \u0625\u0644\u0649 m \u0645\u0631\u0627\u062a."}, {"key": "B", "text": "\u0627\u0644\u062c\u0645\u0639 \u0628\u064a\u0646 n \u0648 m."}, {"key": "C", "text": "\u0627\u062e\u062a\u064a\u0627\u0631 n \u0623\u0648 m."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q32", "number": 32, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a `$`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062f\u0648\u0644\u0627\u0631."}, {"key": "B", "text": "\u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0646\u0635."}, {"key": "C", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0646\u0635."}, {"key": "D", "text": "\u0645\u062a\u063a\u064a\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q33", "number": 33, "text": "\u0643\u064a\u0641 \u062a\u0645\u0646\u0639 \u062a\u0637\u0627\u0628\u0642 \u0646\u0635 \u064a\u0648\u062c\u062f \u0641\u064a \u0648\u0633\u0637 \u062c\u0645\u0644\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `^` \u0648 `$`."}, {"key": "B", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `*`."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `+`."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0645\u0643\u0646."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q34", "number": 34, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0646\u0645\u0637 \u0627\u0644\u0635\u062d\u064a\u062d \u0644\u0645\u0637\u0627\u0628\u0642\u0629 \u0631\u0642\u0645 \u0645\u0646 1 \u0625\u0644\u0649 9\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`[1-9]`"}, {"key": "B", "text": "`[0-9]`"}, {"key": "C", "text": "`\\d`"}, {"key": "D", "text": "`[1-9]+`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q35", "number": 35, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `\\` \u0642\u0628\u0644 \u062d\u0631\u0641 \u062e\u0627\u0635 \u0645\u062b\u0644 `.`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0644\u063a\u0649 \u0627\u0644\u062e\u0627\u0635\u064a\u0629 \u0648\u064a\u062c\u0639\u0644\u0647 \u0646\u0642\u0637\u0629 \u0639\u0627\u062f\u064a\u0629."}, {"key": "B", "text": "\u064a\u0632\u064a\u062f \u0645\u0646 \u0642\u0648\u062a\u0647."}, {"key": "C", "text": "\u064a\u062c\u0639\u0644\u0647 \u064a\u0639\u0645\u0644 \u0643\u0640 `*`."}, {"key": "D", "text": "\u064a\u0633\u0628\u0628 \u062e\u0637\u0623."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q36", "number": 36, "text": "\u0645\u0627 \u0647\u064a \u0646\u062a\u064a\u062c\u0629 `preg_match(\"/a*b/\", \"b\")`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "0 (\u0644\u0627 \u064a\u0648\u062c\u062f \u062a\u0637\u0627\u0628\u0642)."}, {"key": "B", "text": "1 (\u062a\u0637\u0627\u0628\u0642 \u0645\u0648\u062c\u0648\u062f)."}, {"key": "C", "text": "\u062e\u0637\u0623."}, {"key": "D", "text": "`ab`."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q37", "number": 37, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `(a|b)`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0631\u0641 a \u062b\u0645 b."}, {"key": "B", "text": "\u062d\u0631\u0641 a \u0623\u0648 \u062d\u0631\u0641 b."}, {"key": "C", "text": "\u062d\u0631\u0641 ab."}, {"key": "D", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q38", "number": 38, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0637\u0627\u0628\u0642 \"carries\" \u0648 \"car\" \u0648 \"carry\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`car(r|ri|ries)?`"}, {"key": "B", "text": "`car*`"}, {"key": "C", "text": "`car+`"}, {"key": "D", "text": "`car?`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q39", "number": 39, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0639\u062f\u0644 \u0627\u0644\u0630\u064a \u064a\u0633\u0645\u062d \u0628\u0627\u0644\u0628\u062d\u062b \u0641\u064a \u0633\u0637\u0648\u0631 \u0645\u062a\u0639\u062f\u062f\u0629 (Multiline)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`i`"}, {"key": "B", "text": "`m`"}, {"key": "C", "text": "`u`"}, {"key": "D", "text": "`s`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q40", "number": 40, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `{5}`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0646 1 \u0625\u0644\u0649 5."}, {"key": "B", "text": "\u0628\u0627\u0644\u0636\u0628\u0637 5 \u0645\u0631\u0627\u062a."}, {"key": "C", "text": "\u0623\u0643\u062b\u0631 \u0645\u0646 5."}, {"key": "D", "text": "\u0623\u0642\u0644 \u0645\u0646 5."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q41", "number": 41, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.` \u0648 `\\.`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.` \u0623\u064a \u062d\u0631\u0641\u060c `\\.` \u0646\u0642\u0637\u0629 \u062d\u0642\u064a\u0642\u064a\u0629."}, {"key": "B", "text": "`\\.` \u0623\u064a \u062d\u0631\u0641\u060c `.` \u0646\u0642\u0637\u0629."}, {"key": "C", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "D", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u0646\u0642\u0637\u0629."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q42", "number": 42, "text": "\u0643\u064a\u0641 \u062a\u0637\u0627\u0628\u0642 \u0646\u0635 \u064a\u0628\u062f\u0648 \u0643\u062a\u0627\u0631\u064a\u062e (YYYY-MM-DD)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\\d\\d-\\d\\d-\\d\\d\\d\\d`"}, {"key": "B", "text": "`\\d{4}-\\d{2}-\\d{2}`"}, {"key": "C", "text": "`[0-9]-[0-9]-[0-9]`"}, {"key": "D", "text": "`Date`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q43", "number": 43, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u064a\u062f `preg_match` \u0639\u0646\u062f \u0627\u0644\u0641\u0634\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`null`"}, {"key": "B", "text": "`false` \u0623\u0648 `0`."}, {"key": "C", "text": "`-1`"}, {"key": "D", "text": "\u0646\u0635 \u0641\u0627\u0631\u063a."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q44", "number": 44, "text": "\u0645\u0627 \u0647\u064a \u0648\u0638\u064a\u0641\u0629 `preg_split`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062f\u0645\u062c \u0627\u0644\u0646\u0635\u0648\u0635."}, {"key": "B", "text": "\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0645\u0635\u0641\u0648\u0641\u0629 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0646\u0645\u0637."}, {"key": "C", "text": "\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0646\u0635."}, {"key": "D", "text": "\u0627\u0644\u0628\u062d\u062b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q45", "number": 45, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `[a-zA-Z]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0631\u0648\u0641 \u0635\u063a\u064a\u0631\u0629 \u0641\u0642\u0637."}, {"key": "B", "text": "\u062d\u0631\u0648\u0641 \u0643\u0628\u064a\u0631\u0629 \u0641\u0642\u0637."}, {"key": "C", "text": "\u0623\u064a \u062d\u0631\u0641 \u0625\u0646\u062c\u0644\u064a\u0632\u064a \u0643\u0628\u064a\u0631 \u0623\u0648 \u0635\u063a\u064a\u0631."}, {"key": "D", "text": "\u0623\u0631\u0642\u0627\u0645."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-5-q46", "number": 46, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0640 Delimiter \u0627\u0644\u0642\u064a\u0627\u0633\u064a \u0641\u064a PHP Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`#`"}, {"key": "B", "text": "`~`"}, {"key": "C", "text": "`/`"}, {"key": "D", "text": "\u062c\u0645\u064a\u0639 \u0645\u0627 \u0633\u0628\u0642 \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u060c \u0644\u0643\u0646 `/` \u0647\u0648 \u0627\u0644\u0623\u0634\u0647\u0631."}], "answerIndex": 3, "answerText": "D"}, {"id": "hci-lecture-5-q47", "number": 47, "text": "\u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0646\u0645\u0637 `^a$`\u060c \u0645\u0627\u0630\u0627 \u064a\u0637\u0627\u0628\u0642\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u064a \u0646\u0635 \u064a\u062d\u062a\u0648\u064a \u0639\u0644\u0649 a."}, {"key": "B", "text": "\u0627\u0644\u0646\u0635 \"a\" \u0641\u0642\u0637."}, {"key": "C", "text": "\u0646\u0635 \u064a\u0628\u062f\u0623 \u0628\u0640 a."}, {"key": "D", "text": "\u0646\u0635 \u064a\u0646\u062a\u0647\u064a \u0628\u0640 a."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q48", "number": 48, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `\\w`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Whitespace."}, {"key": "B", "text": "Word Character (\u062d\u0631\u0648\u0641\u060c \u0623\u0631\u0642\u0627\u0645\u060c _)."}, {"key": "C", "text": "Wide."}, {"key": "D", "text": "Without."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q49", "number": 49, "text": "\u0645\u0627 \u0647\u064a \u0646\u062a\u064a\u062c\u0629 `preg_match(\"/a{2,}/\", \"aaaa\")`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0637\u0627\u0628\u0642 (\u0644\u0623\u0646 a \u062a\u0643\u0631\u0631\u062a 4 \u0645\u0631\u0627\u062a \u0648\u0647\u0648 \u0623\u0643\u0628\u0631 \u0645\u0646 2)."}, {"key": "B", "text": "\u0641\u0634\u0644."}, {"key": "C", "text": "\u062e\u0637\u0623."}, {"key": "D", "text": "\u064a\u0637\u0627\u0628\u0642 \u062d\u0631\u0641\u064a\u0646 \u0641\u0642\u0637."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q50", "number": 50, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 `[^\\d]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0631\u0642\u0645."}, {"key": "B", "text": "\u0644\u064a\u0633 \u0631\u0642\u0645\u0627\u064b."}, {"key": "C", "text": "\u0646\u0642\u0637\u0629."}, {"key": "D", "text": "\u062d\u0631\u0641 d."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q51", "number": 51, "text": "\u0639\u0631\u0641 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0642\u064a\u0627\u0633\u064a (Regex).", "questionType": "text", "answerText": "\u0647\u0648 \u0633\u0644\u0633\u0644\u0629 \u0645\u0646 \u0627\u0644\u0623\u062d\u0631\u0641 \u0648\u0627\u0644\u0631\u0645\u0648\u0632 \u0627\u0644\u062a\u064a \u062a\u0645\u062b\u0644 \u0646\u0645\u0637\u0627\u064b \u0644\u0644\u0628\u062d\u062b \u062f\u0627\u062e\u0644 \u0627\u0644\u0646\u0635\u0648\u0635\u060c \u062a\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u062a\u062d\u0642\u0642\u060c \u0627\u0644\u0628\u062d\u062b\u060c \u0627\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644\u060c \u0648\u0627\u0644\u062a\u0642\u0633\u064a\u0645."}, {"id": "hci-lecture-5-q52", "number": 52, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 `preg_match` \u0648 `preg_match_all`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q53", "number": 53, "text": "\u0627\u0634\u0631\u062d \u0648\u0638\u064a\u0641\u0629 \u0627\u0644\u0631\u0645\u0648\u0632 \u0627\u0644\u062a\u0627\u0644\u064a\u0629: `^`, `$`, `|`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q54", "number": 54, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `+` \u0648 `*` \u0648 `?`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q55", "number": 55, "text": "\u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u0646\u0645\u0637 `[1-100]` \u062e\u0627\u0637\u0626 \u0644\u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 1 \u0625\u0644\u0649 100\u061f", "questionType": "text", "answerText": "\u0644\u0623\u0646 Regex \u064a\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u0644\u0623\u062d\u0631\u0641 \u0648\u0644\u064a\u0633 \u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629. `[1-100]` \u062a\u0639\u0646\u064a \u062d\u0631\u0641\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 {1, 0}\u060c \u0644\u0623\u0646 \u0627\u0644\u0646\u0637\u0627\u0642 `1-1` \u063a\u064a\u0631 \u0645\u0646\u0637\u0642\u064a \u0648\u0627\u0644\u0640 `00` \u0645\u062c\u0631\u062f \u062a\u0643\u0631\u0627\u0631. \u0627\u0644\u062d\u0644 \u0627\u0644\u0635\u062d\u064a\u062d \u0647\u0648 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0646\u0637\u0642 \u0627\u0644\u0628\u0631\u0645\u062c\u0629: `^([1-9]|[1-9][0-9]|100)$`."}, {"id": "hci-lecture-5-q56", "number": 56, "text": "\u0627\u0643\u062a\u0628 \u0646\u0645\u0637\u0627\u064b \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062a\u062a\u0643\u0648\u0646 \u0645\u0646 6 \u0623\u062d\u0631\u0641 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644.", "questionType": "text", "answerText": "`^.{6,}$`."}, {"id": "hci-lecture-5-q57", "number": 57, "text": "\u0645\u0627 \u0647\u064a \u0648\u0638\u064a\u0641\u0629 `\\s` \u0648 `\\S`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q58", "number": 58, "text": "\u0643\u064a\u0641 \u062a\u0633\u062a\u062e\u062f\u0645 `preg_replace` \u0644\u062d\u0630\u0641 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 \u0646\u0635\u061f", "questionType": "text", "answerText": "\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0646\u0645\u0637 \u0627\u0644\u0628\u062d\u062b `\\d` \u0648\u0627\u0633\u062a\u0628\u062f\u0627\u0644\u0647 \u0628\u0646\u0635 \u0641\u0627\u0631\u063a `\"\"`."}, {"id": "hci-lecture-5-q59", "number": 59, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `[abc]` \u0648 `(abc)`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q60", "number": 60, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0645\u0639\u062f\u0644 `i` \u0645\u0639 \u0645\u062b\u0627\u0644.", "questionType": "text", "answerText": "\u064a\u062c\u0639\u0644 \u0627\u0644\u0628\u062d\u062b \u063a\u064a\u0631 \u062d\u0633\u0627\u0633 \u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0623\u062d\u0631\u0641."}]}, {"id": "hci-lecture-6", "title": "\u0627\u0644\u0645\u062d\u0627\u0636\u0631\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629", "questions": [{"id": "hci-lecture-6-q1", "number": 1, "text": "`filter_var` \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0625\u064a\u0645\u064a\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q2", "number": 2, "text": "`FILTER_SANITIZE_EMAIL` \u062a\u062d\u0630\u0641 \u062d\u0631\u0641 `@` \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u064a\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q3", "number": 3, "text": "\u0627\u0644\u062a\u062d\u0642\u0642 (Validation) \u064a\u063a\u064a\u0631 \u0627\u0644\u0646\u0635\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u062a\u0639\u0642\u064a\u0645 (Sanitization) \u064a\u0631\u0641\u0636\u0647 \u0623\u0648 \u064a\u0642\u0628\u0644\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q4", "number": 4, "text": "`FILTER_VALIDATE_URL` \u062a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0631\u0627\u0628\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q5", "number": 5, "text": "`FILTER_FLAG_QUERY_REQUIRED` \u062a\u0634\u062a\u0631\u0637 \u0648\u062c\u0648\u062f `?` \u0641\u064a \u0627\u0644\u0631\u0627\u0628\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q6", "number": 6, "text": "\u0641\u064a C#\u060c `Regex.IsMatch` \u062a\u0639\u064a\u062f \u0645\u0635\u0641\u0648\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q7", "number": 7, "text": "`Regex.Replace` \u0641\u064a C# \u062a\u0633\u062a\u062e\u062f\u0645 \u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0646\u0645\u0637 \u0628\u0646\u0635 \u0622\u062e\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q8", "number": 8, "text": "`\\d` \u0641\u064a C# \u062a\u0639\u0646\u064a \u0634\u064a\u0626\u0627\u064b \u0645\u062e\u062a\u0644\u0641\u0627\u064b \u0639\u0646 `\\d` \u0641\u064a PHP.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q9", "number": 9, "text": "`FILTER_SANITIZE_URL` \u062a\u0633\u0645\u062d \u0628\u0648\u062c\u0648\u062f \u0627\u0644\u0631\u0645\u0648\u0632 `$` \u0648 `_` \u0641\u064a \u0627\u0644\u0631\u0627\u0628\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q10", "number": 10, "text": "`Regex.Split` \u062a\u0642\u0633\u0645 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0645\u0635\u0641\u0648\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q11", "number": 11, "text": "`FILTER_VALIDATE_IP` \u062a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0639\u0646\u0648\u0627\u0646 IP.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q12", "number": 12, "text": "\u0644\u0627 \u064a\u0645\u0643\u0646 \u062f\u0645\u062c \u0639\u062f\u0629 Flags \u0641\u064a `filter_var`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q13", "number": 13, "text": "`FILTER_SANITIZE_STRING` \u062a\u0632\u064a\u0644 \u0627\u0644\u062a\u0627\u062c\u0627\u062a (Tags) \u0645\u0646 \u0627\u0644\u0646\u0635.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q14", "number": 14, "text": "\u0627\u0644\u0646\u0645\u0637 `\\d{2}` \u064a\u0637\u0627\u0628\u0642 \u0631\u0642\u0645\u064a\u0646 \u0628\u0627\u0644\u0636\u0628\u0637 \u0641\u064a C#.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q15", "number": 15, "text": "`filter_var` \u062a\u0639\u0648\u062f \u0628\u0640 `false` \u0639\u0646\u062f \u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q16", "number": 16, "text": "`Regex.Match` \u062a\u0639\u064a\u062f \u0623\u0648\u0644 \u062a\u0637\u0627\u0628\u0642 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q17", "number": 17, "text": "\u0627\u0644\u062a\u0639\u0642\u064a\u0645 (Sanitization) \u0644\u0627 \u064a\u062d\u0645\u064a \u0645\u0646 SQL Injection \u0628\u062d\u062f \u0630\u0627\u062a\u0647\u060c \u0628\u0644 \u0647\u0648 \u062e\u0637\u0648\u0629 \u0645\u0633\u0627\u0639\u062f\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q18", "number": 18, "text": "\u0627\u0644\u0646\u0645\u0637 `\\.(jpg|png)` \u0641\u064a C# \u064a\u0637\u0627\u0628\u0642 \u0627\u0645\u062a\u062f\u0627\u062f jpg \u0623\u0648 png.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q19", "number": 19, "text": "`FILTER_FLAG_HOST_REQUIRED` \u062a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u0636\u064a\u0641.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q20", "number": 20, "text": "\u0644\u0627 \u062d\u0627\u062c\u0629 \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `@` \u0642\u0628\u0644 \u0627\u0644\u0646\u0635 \u0641\u064a C# Regex \u0644\u0643\u0646\u0647\u0627 \u062a\u0641\u0636\u0644 \u0644\u062a\u062c\u0646\u0628 \u0645\u0634\u0627\u0643\u0644 `\\`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q21", "number": 21, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0641\u0644\u062a\u0631 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u0646\u0638\u064a\u0641 \u0627\u0644\u0625\u064a\u0645\u064a\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_VALIDATE_EMAIL`"}, {"key": "B", "text": "`FILTER_SANITIZE_EMAIL`"}, {"key": "C", "text": "`FILTER_CLEAN_EMAIL`"}, {"key": "D", "text": "`FILTER_EMAIL`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q22", "number": 22, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062f\u0627\u0644\u0629 \u0641\u064a C# \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0646\u0645\u0637 (Boolean)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`Regex.Match`"}, {"key": "B", "text": "`Regex.Matches`"}, {"key": "C", "text": "`Regex.IsMatch`"}, {"key": "D", "text": "`Regex.Check`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-6-q23", "number": 23, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `FILTER_VALIDATE_EMAIL` \u0645\u0639 \u0627\u0644\u0625\u064a\u0645\u064a\u0644 \u0627\u0644\u062e\u0627\u0637\u0626\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0635\u0644\u062d\u0647."}, {"key": "B", "text": "\u064a\u0639\u064a\u062f `false`."}, {"key": "C", "text": "\u064a\u062d\u0630\u0641\u0647."}, {"key": "D", "text": "\u064a\u0631\u0645\u064a \u0627\u0633\u062a\u062b\u0646\u0627\u0621."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q24", "number": 24, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 `\\d{2,4}` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0631\u0642\u0645\u064a\u0646."}, {"key": "B", "text": "4 \u0623\u0631\u0642\u0627\u0645."}, {"key": "C", "text": "\u0645\u0646 2 \u0625\u0644\u0649 4 \u0623\u0631\u0642\u0627\u0645."}, {"key": "D", "text": "\u0631\u0642\u0645\u064a\u0646 \u0645\u0641\u0635\u0648\u0644\u064a\u0646 \u0628\u0641\u0627\u0635\u0644\u0629."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-6-q25", "number": 25, "text": "\u0643\u064a\u0641 \u062a\u062c\u0628\u0631 \u0627\u0644\u0631\u0627\u0628\u0637 \u0639\u0644\u0649 \u0627\u062d\u062a\u0648\u0627\u0621 Query String\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_FLAG_QUERY_REQUIRED`"}, {"key": "B", "text": "`FILTER_FLAG_PATH_REQUIRED`"}, {"key": "C", "text": "`FILTER_FLAG_URL_REQUIRED`"}, {"key": "D", "text": "`FILTER_FLAG_STRING_REQUIRED`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q26", "number": 26, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0623\u062d\u0631\u0641 \u0627\u0644\u062a\u064a \u062a\u062d\u0630\u0641\u0647\u0627 `FILTER_SANITIZE_URL`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u0631\u0642\u0627\u0645."}, {"key": "B", "text": "\u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629."}, {"key": "C", "text": "\u0627\u0644\u0623\u062d\u0631\u0641 \u063a\u064a\u0631 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 (\u0645\u062b\u0644 \u0627\u0644\u0623\u0642\u0648\u0627\u0633 \u063a\u064a\u0631 \u0627\u0644\u0645\u0633\u0645\u0648\u062d\u0629)."}, {"key": "D", "text": "\u0627\u0644\u0646\u0642\u0627\u0637 \u0648\u0627\u0644\u0634\u0631\u0637\u0627\u062a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-6-q27", "number": 27, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `Regex.Match` \u0648 `Regex.Matches` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u0639\u064a\u062f \u0643\u0644 \u0627\u0644\u062a\u0637\u0627\u0628\u0642\u0627\u062a\u060c \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u062a\u0637\u0627\u0628\u0642 \u0648\u0627\u062d\u062f."}, {"key": "B", "text": "\u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u0639\u064a\u062f \u0623\u0648\u0644 \u062a\u0637\u0627\u0628\u0642\u060c \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0643\u0644 \u0627\u0644\u062a\u0637\u0627\u0628\u0642\u0627\u062a."}, {"key": "C", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "D", "text": "\u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u0644\u062a\u062d\u0642\u0642\u060c \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0644\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q28", "number": 28, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `Validation` \u0648 `Sanitization`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Validation \u062a\u0646\u0638\u0641\u060c Sanitization \u062a\u062a\u062d\u0642\u0642."}, {"key": "B", "text": "Validation \u062a\u062a\u062d\u0642\u0642 (\u062a\u0642\u0628\u0644/\u062a\u0631\u0641\u0636)\u060c Sanitization \u062a\u0646\u0638\u0641 (\u062a\u0632\u064a\u0644/\u062a\u0639\u062f\u0644)."}, {"key": "C", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "D", "text": "Validation \u0644\u0644\u0623\u0631\u0642\u0627\u0645 \u0641\u0642\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q29", "number": 29, "text": "\u0623\u064a \u0641\u0644\u062a\u0631 \u064a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0639\u0646\u0648\u0627\u0646 IP\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_VALIDATE_IP`"}, {"key": "B", "text": "`FILTER_VALIDATE_URL`"}, {"key": "C", "text": "`FILTER_VALIDATE_EMAIL`"}, {"key": "D", "text": "`FILTER_VALIDATE_INT`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q30", "number": 30, "text": "\u0645\u0627 \u0647\u0648 \u062f\u0648\u0631 \u0627\u0644\u0631\u0645\u0632 `@` \u0642\u0628\u0644 \u0627\u0644\u0646\u0635 \u0641\u064a C# Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0644\u0625\u0634\u0627\u0631\u0629 \u0644\u0644\u062e\u0637\u0623."}, {"key": "B", "text": "\u0644\u062c\u0639\u0644 \u0627\u0644\u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u0646\u0635\u064a\u0629 (String) \u062a\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 `\\` \u0643\u062d\u0631\u0641 \u0639\u0627\u062f\u064a (Verbatim)."}, {"key": "C", "text": "\u0644\u062a\u0639\u0644\u064a\u0642 \u0627\u0644\u0643\u0648\u062f."}, {"key": "D", "text": "\u0644\u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0646\u0645\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q31", "number": 31, "text": "\u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0643\u0644 \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u0641\u064a \u0646\u0635 \u0628\u0646\u062c\u0645\u0629 \u0641\u064a C#\u060c \u0645\u0627\u0630\u0627 \u062a\u0633\u062a\u062e\u062f\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`Regex.IsMatch`"}, {"key": "B", "text": "`Regex.Replace`"}, {"key": "C", "text": "`Regex.Split`"}, {"key": "D", "text": "`Regex.Space`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q32", "number": 32, "text": "\u0645\u0627 \u0646\u0627\u062a\u062c `filter_var(\"user@example.com\", FILTER_VALIDATE_EMAIL)`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\"user@example.com\"`"}, {"key": "B", "text": "`true`"}, {"key": "C", "text": "`false`"}, {"key": "D", "text": "`null`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q33", "number": 33, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `\\s` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0648\u0642\u0641 \u0627\u0644\u0628\u062d\u062b."}, {"key": "B", "text": "\u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0627\u0644\u0628\u064a\u0636\u0627\u0621."}, {"key": "C", "text": "\u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u062d\u0631\u0641 s."}, {"key": "D", "text": "\u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0635\u063a\u064a\u0631\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q34", "number": 34, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0646\u0645\u0637 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u0648\u0631\u0629 \u0628\u0627\u0645\u062a\u062f\u0627\u062f `jpg` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`*.jpg`"}, {"key": "B", "text": "`\\.jpg$`"}, {"key": "C", "text": "`jpg`"}, {"key": "D", "text": "`.jpg`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q35", "number": 35, "text": "\u0643\u064a\u0641 \u062a\u0646\u0634\u0626 Regex \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`new Regex()`"}, {"key": "B", "text": "`Regex.Create()`"}, {"key": "C", "text": "`Regex.Init()`"}, {"key": "D", "text": "`new Reg()`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q36", "number": 36, "text": "\u0645\u0627 \u0627\u0644\u0641\u0627\u0626\u062f\u0629 \u0645\u0646 `Regex.Split`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0642\u0637\u0639 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0646\u0635\u0641\u064a\u0646."}, {"key": "B", "text": "\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0645\u0635\u0641\u0648\u0641\u0629 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0646\u0645\u0637 \u0641\u0627\u0635\u0644."}, {"key": "C", "text": "\u062f\u0645\u062c \u0627\u0644\u0646\u0635\u0648\u0635."}, {"key": "D", "text": "\u062d\u0630\u0641 \u0623\u062c\u0632\u0627\u0621 \u0645\u0646 \u0627\u0644\u0646\u0635."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q37", "number": 37, "text": "\u0645\u0627\u0630\u0627 \u064a\u062d\u062f\u062b \u0644\u0648 \u0643\u0627\u0646 \u0627\u0644\u0646\u0635 `http://example` \u0645\u0639 `FILTER_FLAG_PATH_REQUIRED`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0642\u0628\u0644\u0647."}, {"key": "B", "text": "\u064a\u0631\u0641\u0636\u0647 (false) \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0633\u0627\u0631 `/path`."}, {"key": "C", "text": "\u064a\u0636\u064a\u0641 `/` \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b."}, {"key": "D", "text": "\u064a\u062d\u0630\u0641 \u0627\u0644\u062f\u0648\u0645\u064a\u0646."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q38", "number": 38, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u0639\u0627\u062f\u0629 \u0645\u0646 `filter_var` \u0639\u0646\u062f \u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`0`"}, {"key": "B", "text": "`false`"}, {"key": "C", "text": "`null`"}, {"key": "D", "text": "`-1`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q39", "number": 39, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u062a\u064a \u064a\u062c\u0628 \u0627\u0633\u062a\u064a\u0631\u0627\u062f\u0647\u0627 \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Regex \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`System.IO`"}, {"key": "B", "text": "`System.Text.RegularExpressions`"}, {"key": "C", "text": "`System.Net`"}, {"key": "D", "text": "`System.Web`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q40", "number": 40, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u062a\u062d\u0642\u0642\" (Validation)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0630\u0641 \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u0627\u0644\u0632\u0627\u0626\u062f\u0629."}, {"key": "B", "text": "\u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0623\u0646 \u0627\u0644\u0639\u0645\u0631 \u0623\u0643\u0628\u0631 \u0645\u0646 18."}, {"key": "C", "text": "\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0646\u0635 \u0644\u0623\u062d\u0631\u0641 \u0635\u063a\u064a\u0631\u0629."}, {"key": "D", "text": "\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0640 HTML Tags."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q41", "number": 41, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062a\u0628\u0631 \"\u062a\u0639\u0642\u064a\u0645\" (Sanitization)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0625\u064a\u0645\u064a\u0644."}, {"key": "B", "text": "\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0634\u0631\u0637\u0627\u062a \u0627\u0644\u0645\u0627\u0626\u0644\u0629 `/` \u0645\u0646 \u0646\u0635."}, {"key": "C", "text": "\u0645\u0642\u0627\u0631\u0646\u0629 \u0643\u0644\u0645\u062a\u064a\u0646."}, {"key": "D", "text": "\u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0637\u0648\u0644 \u0627\u0644\u0646\u0635."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q42", "number": 42, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a `\\w` \u0641\u064a C# Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Whitespace."}, {"key": "B", "text": "Word character."}, {"key": "C", "text": "Wildcard."}, {"key": "D", "text": "Web."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q43", "number": 43, "text": "\u0643\u064a\u0641 \u062a\u0633\u062a\u062e\u062f\u0645 Regex \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u0646\u0633\u064a\u0642 \u062a\u0627\u0631\u064a\u062e (Day-Month-Year)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\\d-\\d-\\d`"}, {"key": "B", "text": "`\\d{2}-\\d{2}-\\d{4}`"}, {"key": "C", "text": "`Date`"}, {"key": "D", "text": "`[0-9]-[0-9]-[0-9]`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q44", "number": 44, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0641\u0627\u0626\u062f\u0629 \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0644\u0644\u062a\u0639\u0642\u064a\u0645 (Sanitization)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0633\u0631\u064a\u0639 \u0627\u0644\u0645\u0648\u0642\u0639."}, {"key": "B", "text": "\u0645\u0646\u0639 \u062d\u0642\u0646 \u0627\u0644\u0623\u0643\u0648\u0627\u062f (Injection Attacks)."}, {"key": "C", "text": "\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0634\u0643\u0644."}, {"key": "D", "text": "\u062a\u0642\u0644\u064a\u0644 \u062d\u062c\u0645 \u0627\u0644\u0645\u0644\u0641."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q45", "number": 45, "text": "\u0627\u0644\u0631\u0645\u0632 `|` \u0641\u064a C# Regex \u064a\u0639\u0646\u064a:", "questionType": "choice", "options": [{"key": "A", "text": "AND."}, {"key": "B", "text": "OR."}, {"key": "C", "text": "NOT."}, {"key": "D", "text": "Concatenation."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q46", "number": 46, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `FILTER_SANITIZE_STRING`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u062d\u0648\u0644 \u0627\u0644\u0646\u0635 \u0644\u0623\u0631\u0642\u0627\u0645."}, {"key": "B", "text": "\u064a\u0632\u064a\u0644 \u0627\u0644\u062a\u0627\u062c\u0627\u062a (Tags) \u0648\u062a\u0631\u0645\u0632 \u0627\u0644\u0623\u062d\u0631\u0641 \u0627\u0644\u062e\u0627\u0635\u0629."}, {"key": "C", "text": "\u064a\u0636\u064a\u0641 \u0646\u0635\u0627\u064b."}, {"key": "D", "text": "\u064a\u062d\u0630\u0641 \u0627\u0644\u0623\u0631\u0642\u0627\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q47", "number": 47, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `Match` \u0648 `MatchCollection` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`Match` \u0646\u062a\u064a\u062c\u0629 \u0648\u0627\u062d\u062f\u0629\u060c `MatchCollection` \u0645\u062c\u0645\u0648\u0639\u0629 \u0646\u062a\u0627\u0626\u062c."}, {"key": "B", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "C", "text": "`Match` \u0644\u0644\u0628\u062d\u062b\u060c `MatchCollection` \u0644\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644."}, {"key": "D", "text": "`Match` \u0623\u0633\u0631\u0639."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q48", "number": 48, "text": "\u0623\u064a \u0641\u0644\u062a\u0631 \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0623\u0646 \u0627\u0644\u0642\u064a\u0645\u0629 \u0639\u062f\u062f \u0635\u062d\u064a\u062d (Integer)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_VALIDATE_INT`"}, {"key": "B", "text": "`FILTER_VALIDATE_NUMBER`"}, {"key": "C", "text": "`FILTER_SANITIZE_INT`"}, {"key": "D", "text": "`FILTER_CHECK_INT`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q49", "number": 49, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 \u0627\u0644\u0646\u0645\u0637 `\\b` \u0641\u064a Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0631\u0641 b."}, {"key": "B", "text": "\u062d\u062f\u0648\u062f \u0627\u0644\u0643\u0644\u0645\u0629 (Word Boundary)."}, {"key": "C", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631."}, {"key": "D", "text": "\u0645\u0633\u0627\u0641\u0629 \u062e\u0644\u0641\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q50", "number": 50, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0645\u062f\u062e\u0644\u0627\u062a \u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u064a PHP\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062a\u062d\u0642\u0642 \u062b\u0645 \u0627\u0644\u062a\u0639\u0642\u064a\u0645."}, {"key": "B", "text": "\u0627\u0644\u062a\u0639\u0642\u064a\u0645 \u062b\u0645 \u0627\u0644\u062a\u062d\u0642\u0642."}, {"key": "C", "text": "\u0627\u0644\u062d\u0641\u0638 \u0645\u0628\u0627\u0634\u0631\u0629."}, {"key": "D", "text": "\u0627\u0644\u0637\u0628\u0627\u0639\u0629."}], "answerIndex": 1, "answerText": "B"}]}, {"id": "hci-all", "title": "\u0627\u062e\u062a\u0628\u0627\u0631 \u0634\u0627\u0645\u0644", "isComprehensive": true, "questions": [{"id": "hci-lecture-1-q1", "number": 1, "text": "\u064a\u0631\u0643\u0632 \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0628\u064a\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u0627\u0633\u0648\u0628 (HCI) \u062d\u0635\u0631\u0627\u064b \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u062a\u0642\u0646\u064a \u0648\u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0623\u062c\u0647\u0632\u0629 \u0627\u0644\u0635\u0644\u0628\u0629 (Hardware).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q2", "number": 2, "text": "\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062a\u0641\u0627\u0639\u0644 (Interaction Model) \u064a\u0647\u062f\u0641 \u0644\u0641\u0647\u0645 \"\u0627\u0644\u062a\u0631\u062c\u0645\u0629\" \u0628\u064a\u0646 \u0645\u0627 \u064a\u0631\u064a\u062f\u0647 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0645\u0627 \u064a\u0641\u0639\u0644\u0647 \u0627\u0644\u0646\u0638\u0627\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q3", "number": 3, "text": "\u0645\u0628\u062f\u0623 \"\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0628\u0643\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0627\u0644\u0645\u0647\u0627\u0645\" \u064a\u0639\u0646\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0623\u0648\u0644\u0627\u064b \u062b\u0645 \u0627\u062e\u062a\u0628\u0627\u0631\u0647 \u0645\u0639 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u064a \u0627\u0644\u0646\u0647\u0627\u064a\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q4", "number": 4, "text": "\u0648\u0627\u062c\u0647\u0629 \u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 (Command Line Interface) \u062a\u062a\u0645\u064a\u0632 \u0628\u0643\u0648\u0646\u0647\u0627 \u0633\u0647\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q5", "number": 5, "text": "\u0646\u0645\u0637 \"\u0645\u0644\u0621 \u0627\u0644\u0646\u0645\u0627\u0630\u062c\" (Form-fills) \u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u062e\u0628\u0631\u0627\u0621 \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u063a\u064a\u0631 \u0627\u0644\u062e\u0628\u0631\u0627\u0621.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q6", "number": 6, "text": "\u0641\u064a \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0648\u0638\u064a\u0641\u064a\" (Functional Arrangement)\u060c \u064a\u062a\u0645 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0645\u062f\u0649 \u062a\u0643\u0631\u0627\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q7", "number": 7, "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 (Interaction Design) \u064a\u0642\u062a\u0635\u0631 \u0639\u0644\u0649 \u062a\u0635\u0645\u064a\u0645 \u0634\u0643\u0644 \u0627\u0644\u0623\u0632\u0631\u0627\u0631 \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q8", "number": 8, "text": "\u0627\u0644\u0628\u0639\u062f \u0627\u0644\u0631\u0627\u0628\u0639 \u0641\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0647\u0648 \"\u0627\u0644\u0633\u0644\u0648\u0643\" (Behavior).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q9", "number": 9, "text": "\u0645\u0628\u062f\u0623 \"\u0627\u0644\u0642\u0627\u0628\u0644\u064a\u0629 \u0644\u0644\u062a\u0646\u0628\u0624\" (Predictable) \u064a\u0639\u0646\u064a \u0623\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u0645\u0643\u0646\u0647 \u062a\u0648\u0642\u0639 \u0645\u0627 \u0633\u064a\u062d\u062f\u062b \u0642\u0628\u0644 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0625\u062c\u0631\u0627\u0621.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q10", "number": 10, "text": "\"\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629\" (Feedback) \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u062a\u0639\u0646\u064a \u062a\u0648\u0642\u0639 \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0645\u0646\u0639\u0647\u0627 \u0645\u0633\u0628\u0642\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q11", "number": 11, "text": "\u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u062e\u0637\u064a\u0629 (Linear)\u060c \u062d\u064a\u062b \u0646\u0646\u062a\u0642\u0644 \u0645\u0646 \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0644\u0644\u062a\u0635\u0645\u064a\u0645 \u0644\u0644\u062a\u0646\u0641\u064a\u0630 \u062f\u0648\u0646 \u0631\u062c\u0648\u0639.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q12", "number": 12, "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a (Visual Design) \u064a\u0623\u062a\u064a \u0642\u0628\u0644 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0641\u064a \u0645\u0631\u0627\u062d\u0644 \u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q13", "number": 13, "text": "\"\u0627\u0644\u0642\u064a\u0627\u0633 \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a\" (Empirical Measurement) \u064a\u062a\u0637\u0644\u0628 \u062a\u062d\u062f\u064a\u062f \u0623\u0647\u062f\u0627\u0641 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0642\u064a\u0627\u0633 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q14", "number": 14, "text": "\u0646\u0645\u0637 \"\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a\" (Instructing) \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0625\u062c\u0631\u0627\u0621 \u0645\u062d\u0627\u062f\u062b\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0627\u0644\u0646\u0638\u0627\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q15", "number": 15, "text": "\"\u0627\u0644\u0625\u062f\u0631\u0627\u0643\" (Perceivability) \u064a\u0647\u062f\u0641 \u0625\u0644\u0649 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062a\u0644\u0645\u064a\u062d\u0627\u062a \u0645\u0631\u0626\u064a\u0629 \u062a\u0633\u0627\u0639\u062f\u0647 \u0641\u064a \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0641\u0631\u0635 \u0627\u0644\u062a\u0641\u0627\u0639\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q16", "number": 16, "text": "\u0627\u0644\u0627\u062a\u0633\u0627\u0642 (Consistency) \u064a\u0642\u0644\u0644 \u0645\u0646 \u0639\u0628\u0621 \u0627\u0644\u062a\u0639\u0644\u0645 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q17", "number": 17, "text": "\"\u062d\u0648\u0627\u0631 \u0627\u0644\u0633\u0624\u0627\u0644 \u0648\u0627\u0644\u062c\u0648\u0627\u0628\" (Question/Answer Dialog) \u064a\u062a\u0645\u064a\u0632 \u0628\u0642\u0648\u062a\u0647 \u0648\u0645\u0631\u0648\u0646\u062a\u0647 \u0627\u0644\u0639\u0627\u0644\u064a\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q18", "number": 18, "text": "\u0641\u064a \u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a (Sequential Arrangement)\u060c \u064a\u062a\u0645 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u062e\u0637\u0648\u0627\u062a \u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0645\u0647\u0645\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q19", "number": 19, "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a \u0644\u0627 \u064a\u0624\u062b\u0631 \u0639\u0644\u0649 \u062b\u0642\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u064a \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q20", "number": 20, "text": "\u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0648\u0627\u0644\u0646\u0634\u0631\" (Implementation) \u062a\u062a\u0636\u0645\u0646 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f \u0648\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0646\u0638\u0627\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q21", "number": 21, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0645\u0646 \u0645\u0628\u062f\u0623 \"\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0628\u0643\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0627\u0644\u0645\u0647\u0627\u0645\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0642\u0644\u064a\u0644 \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u062a\u0637\u0648\u064a\u0631."}, {"key": "B", "text": "\u0628\u0646\u0627\u0621 \u0627\u0644\u0646\u0638\u0627\u0645 \u0623\u0648\u0644\u0627\u064b \u062b\u0645 \u062a\u0639\u062f\u064a\u0644\u0647 \u0644\u0627\u062d\u0642\u0627\u064b."}, {"key": "C", "text": "\u0641\u0647\u0645 \u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0633\u0644\u0648\u0643\u0647\u0645 \u0642\u0628\u0644 \u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "D", "text": "\u0625\u062c\u0628\u0627\u0631 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062a\u0643\u064a\u0641 \u0645\u0639 \u0627\u0644\u0646\u0638\u0627\u0645."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q22", "number": 22, "text": "\u0623\u064a \u0645\u0646 \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0623\u0646\u0633\u0628 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u063a\u064a\u0631 \u0627\u0644\u062e\u0628\u0631\u0627\u0621 (Non-experts)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 (Command Line)."}, {"key": "B", "text": "\u0644\u063a\u0627\u062a \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0645\u0631\u0643\u0628\u0629."}, {"key": "C", "text": "\u0645\u0644\u0621 \u0627\u0644\u0646\u0645\u0627\u0630\u062c (Form-fills)."}, {"key": "D", "text": "\u0627\u0644\u0646\u0648\u0627\u0641\u0630 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 (Direct Manipulation) \u0627\u0644\u0645\u0639\u0642\u062f\u0629."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q23", "number": 23, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u062c\u0648\u0647\u0631\u064a \u0628\u064a\u0646 \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0648\u0638\u064a\u0641\u064a\" \u0648\"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0648\u0638\u064a\u0641\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0647\u0645\u064a\u0629."}, {"key": "B", "text": "\u0627\u0644\u0648\u0638\u064a\u0641\u064a \u064a\u062c\u0645\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0630\u0627\u062a \u0627\u0644\u063a\u0631\u0636 \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a \u064a\u062a\u0628\u0639 \u062a\u0631\u062a\u064a\u0628 \u062e\u0637\u0648\u0627\u062a \u0627\u0644\u0639\u0645\u0644."}, {"key": "C", "text": "\u0627\u0644\u0648\u0638\u064a\u0641\u064a \u0644\u0644\u062e\u0628\u0631\u0627\u0621\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a \u0644\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u0631\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q24", "number": 24, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \u0627\u0644\u0628\u0639\u062f \u0627\u0644\u062e\u0627\u0645\u0633 \"\u0627\u0644\u0633\u0644\u0648\u0643\" (Behavior) \u0641\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0634\u0643\u0644 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u0631\u062f\u0648\u062f \u0641\u0639\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "C", "text": "\u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0629 \u0641\u064a \u062a\u0635\u0646\u064a\u0639 \u0627\u0644\u062c\u0647\u0627\u0632."}, {"key": "D", "text": "\u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u0632\u0645\u0646\u064a\u0629 \u0644\u0644\u062a\u0641\u0627\u0639\u0644."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q25", "number": 25, "text": "\u0625\u0630\u0627 \u0642\u0627\u0645 \u0645\u0635\u0645\u0645 \u0628\u062c\u0639\u0644 \u0632\u0631 \"\u0627\u0644\u062d\u0630\u0641\" \u0628\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u062d\u0645\u0631 \u0648\u0634\u0643\u0644\u0647 \u064a\u0648\u062d\u064a \u0628\u0627\u0644\u062e\u0637\u0631\u060c \u0641\u0623\u064a \u0645\u0628\u062f\u0623 \u062a\u0635\u0645\u064a\u0645\u064a \u064a\u0637\u0628\u0642\u0647\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0627\u062a\u0633\u0627\u0642 (Consistency)."}, {"key": "B", "text": "\u0627\u0644\u0625\u062f\u0631\u0627\u0643 (Perceivability)."}, {"key": "C", "text": "\u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 (Learnability)."}, {"key": "D", "text": "\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629 (Feedback)."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q26", "number": 26, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u064a \u062a\u0644\u064a \"\u0627\u0644\u062a\u062d\u0644\u064a\u0644\" \u0645\u0628\u0627\u0634\u0631\u0629 \u0641\u064a \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a."}, {"key": "B", "text": "\u0627\u0644\u062a\u0646\u0641\u064a\u0630."}, {"key": "C", "text": "\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629."}, {"key": "D", "text": "\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q27", "number": 27, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u0627\u062a\u0633\u0627\u0642\" (Consistency) \u0645\u0647\u0645\u0627\u064b \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0648\u0627\u062c\u0647\u0627\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u062c\u0639\u0644 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u062a\u0628\u062f\u0648 \u0645\u0645\u0644\u0629."}, {"key": "B", "text": "\u0644\u062a\u0642\u0644\u064a\u0644 \u0641\u0631\u0635 \u0627\u0631\u062a\u0643\u0627\u0628 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0648\u062a\u0633\u0647\u064a\u0644 \u0646\u0642\u0644 \u0627\u0644\u062e\u0628\u0631\u0629."}, {"key": "C", "text": "\u0644\u0632\u064a\u0627\u062f\u0629 \u0648\u0642\u062a \u0627\u0644\u062a\u0639\u0644\u0645."}, {"key": "D", "text": "\u0644\u062a\u0645\u064a\u064a\u0632 \u0643\u0644 \u0634\u0627\u0634\u0629 \u0639\u0646 \u0627\u0644\u0623\u062e\u0631\u0649 \u062a\u0645\u0627\u0645\u0627\u064b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q28", "number": 28, "text": "\u0623\u064a \u0645\u0645\u0627 \u064a\u0644\u064a \u064a\u0646\u062a\u0645\u064a \u0625\u0644\u0649 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\" (Visual Design) \u0648\u0644\u064a\u0633 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u062d\u062f\u064a\u062f \u062a\u062f\u0641\u0642 \u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642."}, {"key": "B", "text": "\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u062e\u0637\u0648\u0637 (Typography) \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u0646."}, {"key": "C", "text": "\u062a\u062d\u062f\u064a\u062f \u0633\u0644\u0648\u0643 \u0627\u0644\u0623\u0632\u0631\u0627\u0631 \u0639\u0646\u062f \u0627\u0644\u0646\u0642\u0631."}, {"key": "D", "text": "\u0625\u0646\u0634\u0627\u0621 \u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q29", "number": 29, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u064a\" (Iterative Design)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0625\u0637\u0644\u0627\u0642\u0647."}, {"key": "B", "text": "\u0646\u0633\u062e \u062a\u0635\u0645\u064a\u0645 \u0645\u0646\u062a\u062c \u0645\u0646\u0627\u0641\u0633."}, {"key": "C", "text": "\u0639\u0645\u0644\u064a\u0629 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0639\u062f\u0629 \u0645\u0631\u0627\u062a \u0644\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "D", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u062a\u0643\u0631\u0627\u0631 \u0645\u0639\u064a\u0646."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q30", "number": 30, "text": "\u0641\u064a \u0633\u064a\u0627\u0642 \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u060c \u0645\u062a\u0649 \u064a\u064f\u0641\u0636\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \"\u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0645\u0628\u062a\u062f\u0626\u0627\u064b."}, {"key": "B", "text": "\u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0647\u0627\u0645 \u0628\u0633\u064a\u0637\u0629 \u0648\u062a\u062a\u0637\u0644\u0628 \u0645\u0648\u0627\u0641\u0642\u0629 \u0646\u0639\u0645/\u0644\u0627."}, {"key": "C", "text": "\u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062e\u0628\u064a\u0631\u0627\u064b \u0648\u064a\u062d\u062a\u0627\u062c \u0644\u0642\u0648\u0629 \u0648\u062a\u062d\u0643\u0645 \u0645\u0628\u0627\u0634\u0631."}, {"key": "D", "text": "\u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0631\u0633\u0648\u0645\u064a\u0629 \u0648\u0645\u0639\u0642\u062f\u0629."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q31", "number": 31, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0641\u064a \u0646\u0645\u0637 \"\u062d\u0648\u0627\u0631 \u0627\u0644\u0633\u0624\u0627\u0644 \u0648\u0627\u0644\u062c\u0648\u0627\u0628\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u062a\u0639\u0644\u0645."}, {"key": "B", "text": "\u0645\u062d\u062f\u0648\u062f\u064a\u0629 \u0627\u0644\u0648\u0638\u0627\u0626\u0641 \u0648\u0627\u0644\u0642\u0648\u0629."}, {"key": "C", "text": "\u0639\u062f\u0645 \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647 \u0645\u0639 \u0644\u0648\u062d\u0629 \u0627\u0644\u0645\u0641\u0627\u062a\u064a\u062d."}, {"key": "D", "text": "\u062a\u0643\u0644\u0641\u062a\u0647 \u0627\u0644\u0639\u0627\u0644\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q32", "number": 32, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0641\u0631\u0627\u063a\u0627\u062a \u0627\u0644\u0633\u0644\u0628\u064a\u0629\" (Negative Space) \u0641\u064a \u0645\u0628\u0627\u062f\u0626 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0648\u0627\u062c\u0647\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0641\u0631\u0627\u063a\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u0645\u0633\u062a\u063a\u0644\u0629 \u0627\u0644\u062a\u064a \u064a\u062c\u0628 \u0645\u0644\u0624\u0647\u0627."}, {"key": "B", "text": "\u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0627\u0644\u0628\u064a\u0636\u0627\u0621 \u062d\u0648\u0644 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u064a \u062a\u0633\u0627\u0639\u062f \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0632\u0647\u0627 \u0648\u062a\u0631\u062a\u064a\u0628\u0647\u0627."}, {"key": "C", "text": "\u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062f\u0627\u0643\u0646\u0629 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u064a\u0629."}, {"key": "D", "text": "\u0627\u0644\u0645\u0633\u0627\u062d\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u062d\u062f\u062b \u0641\u064a\u0647\u0627 \u0623\u062e\u0637\u0627\u0621."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q33", "number": 33, "text": "\u0623\u064a \u0627\u0644\u0639\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u062a\u0635\u0641 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u062a\u0645\u0631\u0643\u0632 \u062d\u0648\u0644 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0646\u0638\u0627\u0645 \u0647\u0648 \u0645\u062d\u0648\u0631 \u0627\u0644\u0639\u0645\u0644\u064a\u0629."}, {"key": "B", "text": "\u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0647\u064a \u0627\u0644\u062a\u064a \u062a\u062d\u062f\u062f \u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "C", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0647\u0648 \u0645\u062d\u0648\u0631 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0648\u064a\u062c\u0628 \u0641\u0647\u0645 \u0633\u064a\u0627\u0642 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647."}, {"key": "D", "text": "\u064a\u062a\u0645 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0642\u062f\u0631\u0627\u062a \u0627\u0644\u0645\u0628\u0631\u0645\u062c."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q34", "number": 34, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \"\u0627\u0644\u0643\u0644\u0645\u0627\u062a\" (Words) \u0648\"\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a\" \u0643\u0623\u0628\u0639\u0627\u062f \u0644\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0644\u0644\u0623\u0648\u0627\u0645\u0631\u060c \u0648\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a \u0644\u0644\u0635\u0648\u0631 \u0641\u0642\u0637."}, {"key": "B", "text": "\u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0644\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0646\u0635\u064a\u060c \u0648\u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a \u0644\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0631\u0633\u0648\u0645\u064a\u0629 \u0648\u0627\u0644\u0623\u064a\u0642\u0648\u0646\u0627\u062a."}, {"key": "C", "text": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u0631\u0642."}, {"key": "D", "text": "\u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u062e\u0628\u0631\u0627\u0621 \u0641\u0642\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q35", "number": 35, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u0644\u0627 \u064a\u0639\u062a\u0628\u0631 \u0645\u0646 \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u062e\u0645\u0633\u0629 \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0627\u062a\u0633\u0627\u0642."}, {"key": "B", "text": "\u0627\u0644\u0623\u0645\u0627\u0646\u0629 (Honesty)."}, {"key": "C", "text": "\u0627\u0644\u0625\u062f\u0631\u0627\u0643."}, {"key": "D", "text": "\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q36", "number": 36, "text": "\u0645\u0627 \u0627\u0644\u0647\u062f\u0641 \u0645\u0646 \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629\" (Prototyping)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0628\u064a\u0639 \u0627\u0644\u0645\u0646\u062a\u062c \u0627\u0644\u0646\u0647\u0627\u0626\u064a."}, {"key": "B", "text": "\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u0627\u062a \u0648\u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0645\u0644\u0627\u062d\u0638\u0627\u062a \u0645\u0628\u0643\u0631\u0629."}, {"key": "C", "text": "\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f \u0627\u0644\u0646\u0647\u0627\u0626\u064a."}, {"key": "D", "text": "\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q37", "number": 37, "text": "\u0625\u0630\u0627 \u0643\u0646\u062a \u062a\u0635\u0645\u0645 \u0646\u0638\u0627\u0645\u0627\u064b \u0644\u0631\u0648\u0627\u062f \u0627\u0644\u0641\u0636\u0627\u0621 \u064a\u062a\u0637\u0644\u0628 \u0627\u062a\u0628\u0627\u0639 \u062e\u0637\u0648\u0627\u062a \u062f\u0642\u064a\u0642\u0629 \u0648\u0635\u0627\u0631\u0645\u0629\u060c \u0623\u064a \u062a\u0631\u062a\u064a\u0628 \u0644\u0644\u062a\u062d\u0643\u0645 \u062a\u062e\u062a\u0627\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0631\u062a\u064a\u0628 \u0645\u062a\u0643\u0631\u0631 (Frequency)."}, {"key": "B", "text": "\u062a\u0631\u062a\u064a\u0628 \u0648\u0638\u064a\u0641\u064a (Functional)."}, {"key": "C", "text": "\u062a\u0631\u062a\u064a\u0628 \u062a\u0633\u0644\u0633\u0644\u064a (Sequential)."}, {"key": "D", "text": "\u062a\u0631\u062a\u064a\u0628 \u0639\u0634\u0648\u0627\u0626\u064a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q38", "number": 38, "text": "\u0643\u064a\u0641 \u064a\u0633\u0627\u0647\u0645 \"\u0627\u0644\u0648\u0642\u062a\" \u0643\u0628\u0639\u062f \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0628\u0642\u064a\u0627\u0633 \u0633\u0631\u0639\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062c."}, {"key": "B", "text": "\u0628\u0642\u064a\u0627\u0633 \u0645\u062f\u0629 \u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u062a\u0642\u062f\u0645\u0647 \u0641\u064a \u0627\u0644\u0645\u0647\u0645\u0629."}, {"key": "C", "text": "\u0628\u062a\u062d\u062f\u064a\u062f \u0645\u0648\u0639\u062f \u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0633\u0627\u0647\u0645 \u0628\u0623\u064a \u0634\u064a\u0621."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q39", "number": 39, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 \u0623\u0646 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \"\u0628\u062f\u064a\u0647\u064a\u0627\u064b\" (Learnability)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0646 \u064a\u0643\u0648\u0646 \u0645\u062c\u0647\u0648\u0644 \u0627\u0644\u0645\u0635\u062f\u0631."}, {"key": "B", "text": "\u0623\u0646 \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062e\u0628\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0644\u0627 \u064a\u062d\u062a\u0627\u062c \u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0643\u062b\u064a\u0631\u0629."}, {"key": "C", "text": "\u0623\u0646 \u064a\u0643\u0648\u0646 \u0635\u0639\u0628\u0627\u064b \u0644\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u062a\u062d\u062f\u064a."}, {"key": "D", "text": "\u0623\u0646 \u064a\u0638\u0647\u0631 \u0631\u0633\u0627\u0626\u0644 \u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0641\u064a \u0643\u0644 \u062b\u0627\u0646\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q40", "number": 40, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062f \u0645\u0646 \u0639\u0646\u0627\u0635\u0631 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u0645\u062a\u062d\u0631\u0643\u0629 (Animation)."}, {"key": "B", "text": "\u0627\u0644\u0637\u0628\u0627\u0639\u0629 (Typography)."}, {"key": "C", "text": "\u0627\u0644\u0648\u0642\u062a."}, {"key": "D", "text": "\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q41", "number": 41, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629\" \u0641\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u062c\u0647\u0632\u0629 (\u0647\u0648\u0627\u062a\u0641\u060c \u0644\u0627\u0628\u062a\u0648\u0628) \u0627\u0644\u062a\u064a \u064a\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "B", "text": "\u0627\u0644\u0623\u062b\u0627\u062b \u0641\u064a \u0627\u0644\u063a\u0631\u0641\u0629."}, {"key": "C", "text": "\u0627\u0644\u0623\u0642\u0631\u0627\u0635 \u0627\u0644\u0635\u0644\u0628\u0629."}, {"key": "D", "text": "\u0627\u0644\u0643\u0648\u062f \u0627\u0644\u0628\u0631\u0645\u062c\u064a."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-1-q42", "number": 42, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\" \u0645\u0647\u0645\u0627\u064b \u0644\u0644\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629 (Branding)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0623\u0646\u0647 \u064a\u062d\u062f\u062f \u0633\u0639\u0631 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u0644\u0623\u0646\u0647 \u064a\u0646\u0642\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u0647\u0648\u064a\u0629 \u0627\u0644\u0634\u0631\u0643\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0648\u0627\u0644\u0634\u0639\u0627\u0631."}, {"key": "C", "text": "\u0644\u0623\u0646\u0647 \u064a\u062c\u0639\u0644 \u0627\u0644\u0645\u0648\u0642\u0639 \u0628\u0637\u064a\u0626\u0627\u064b."}, {"key": "D", "text": "\u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647 \u0628\u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q43", "number": 43, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064a \"\u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629."}, {"key": "B", "text": "\u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a (Requirements)."}, {"key": "C", "text": "\u0627\u0644\u062a\u062d\u0644\u064a\u0644."}, {"key": "D", "text": "\u0627\u0644\u062a\u0646\u0641\u064a\u0630."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q44", "number": 44, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \"\u062a\u0648\u0642\u0639 \u0627\u0644\u0623\u062e\u0637\u0627\u0621\" \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062c\u064a\u062f\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u062d\u0627\u0648\u0644\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0625\u062a\u0644\u0627\u0641 \u0627\u0644\u0646\u0638\u0627\u0645."}, {"key": "B", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0646\u0638\u0627\u0645 \u0644\u0645\u0646\u0639 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u062d\u062a\u0645\u0644\u0629 \u0623\u0648 \u0627\u0644\u062a\u062e\u0641\u064a\u0641 \u0645\u0646 \u062d\u062f\u062a\u0647\u0627 \u0642\u0628\u0644 \u0648\u0642\u0648\u0639\u0647\u0627."}, {"key": "C", "text": "\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062e\u0637\u0623 \u0627\u0644\u0645\u062e\u064a\u0641\u0629."}, {"key": "D", "text": "\u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0646\u0638\u0627\u0645 \u0639\u0646\u062f \u0623\u064a \u062e\u0637\u0623."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q45", "number": 45, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0635\u0641 \"\u0646\u0645\u0637 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629\" (Conversing)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u0643\u062a\u0628 \u0623\u0648\u0627\u0645\u0631 \u0635\u0627\u0631\u0645\u0629."}, {"key": "B", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u062c\u0631\u064a \u062d\u0648\u0627\u0631\u0627\u064b \u0645\u0639 \u0627\u0644\u0646\u0638\u0627\u0645 (\u0635\u0648\u062a\u064a/\u0646\u0635\u064a) \u0648\u0643\u0623\u0646\u0647 \u0634\u062e\u0635 \u0622\u062e\u0631."}, {"key": "C", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u0645\u0644\u0623 \u0641\u0631\u0627\u063a\u0627\u062a."}, {"key": "D", "text": "\u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u064a\u062e\u062a\u0627\u0631 \u0645\u0646 \u0642\u0627\u0626\u0645\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q46", "number": 46, "text": "\u0645\u0627 \u0647\u064a \u0645\u0634\u0643\u0644\u0629 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u063a\u064a\u0631 \u0627\u0644\u0645\u062a\u0633\u0642\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0633\u0647\u0644 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062a\u0646\u0628\u0624."}, {"key": "B", "text": "\u064a\u0631\u0628\u0643 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u064a\u0632\u064a\u062f \u0645\u0646 \u0627\u062d\u062a\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062e\u0637\u0623."}, {"key": "C", "text": "\u064a\u062c\u0639\u0644 \u0627\u0644\u0645\u0646\u062a\u062c \u062c\u0630\u0627\u0628\u0627\u064b."}, {"key": "D", "text": "\u064a\u0642\u0644\u0644 \u0648\u0642\u062a \u0627\u0644\u062a\u0646\u0641\u064a\u0630."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q47", "number": 47, "text": "\u0641\u064a \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a\"\u060c \u0623\u064a \u062a\u0642\u0646\u064a\u0629 \u0644\u0627 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u062c\u0645\u0639 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0627\u062a."}, {"key": "B", "text": "\u0645\u0631\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646."}, {"key": "C", "text": "\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f."}, {"key": "D", "text": "\u0627\u0644\u0627\u0637\u0644\u0627\u0639 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q48", "number": 48, "text": "\u0645\u0627 \u0647\u0648 \u062a\u0623\u062b\u064a\u0631 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\" \u0627\u0644\u0633\u064a\u0621 \u0639\u0644\u0649 \u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0627 \u064a\u0624\u062b\u0631."}, {"key": "B", "text": "\u064a\u0632\u064a\u062f \u0645\u0646 \u0633\u0631\u0639\u0629 \u0627\u0644\u0645\u0648\u0642\u0639."}, {"key": "C", "text": "\u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0633\u0648\u0621 \u0627\u0644\u0641\u0647\u0645 \u0648\u0639\u062f\u0645 \u0627\u0644\u062b\u0642\u0629."}, {"key": "D", "text": "\u064a\u062d\u0633\u0646 \u0645\u0646 \u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u0646\u0638\u0627\u0645."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-1-q49", "number": 49, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0645\u062b\u0644 \"\u0627\u0644\u062a\u0643\u0631\u0627\u0631\" \u0641\u064a \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0643\u0631\u0627\u0631 \u0646\u0641\u0633 \u0627\u0644\u0623\u062e\u0637\u0627\u0621."}, {"key": "B", "text": "\u062a\u0643\u0631\u0627\u0631 \u062f\u0648\u0631\u0629 (\u062a\u0635\u0645\u064a\u0645 -> \u0627\u062e\u062a\u0628\u0627\u0631 -> \u062a\u0639\u062f\u064a\u0644) \u0644\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0646\u062a\u064a\u062c\u0629."}, {"key": "C", "text": "\u062a\u0643\u0631\u0627\u0631 \u0646\u0641\u0633 \u0627\u0644\u0623\u0644\u0648\u0627\u0646."}, {"key": "D", "text": "\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0628\u064a\u0639."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q50", "number": 50, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0645\u0646 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0625\u0646\u0634\u0627\u0621 \u0645\u0646\u062a\u062c\u0627\u062a \u0645\u0639\u0642\u062f\u0629."}, {"key": "B", "text": "\u062a\u0633\u0647\u064a\u0644 \u062d\u064a\u0627\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u062c\u0639\u0644 \u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0623\u0642\u0644 \u0625\u062d\u0628\u0627\u0637\u0627\u064b."}, {"key": "C", "text": "\u0632\u064a\u0627\u062f\u0629 \u0639\u062f\u062f \u0627\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "D", "text": "\u062a\u0642\u0644\u064a\u0644 \u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u0646\u0638\u0627\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-1-q51", "number": 51, "text": "\u0639\u0631\u0641 \u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0628\u064a\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u0627\u0633\u0648\u0628 (HCI).", "questionType": "text", "answerText": "\u0647\u0648 \u0645\u062c\u0627\u0644 \u0645\u062a\u0639\u062f\u062f \u0627\u0644\u062a\u062e\u0635\u0635\u0627\u062a \u064a\u0647\u062a\u0645 \u0628\u062f\u0631\u0627\u0633\u0629 \u0648\u062a\u0635\u0645\u064a\u0645 \u0648\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u0631\u0643\u0632\u0629 \u062d\u0648\u0644 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u060c \u0628\u0647\u062f\u0641 \u062c\u0639\u0644 \u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0633\u0647\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u060c \u0645\u0641\u064a\u062f\u0629\u060c \u0648\u0645\u0645\u062a\u0639\u0629."}, {"id": "hci-lecture-1-q52", "number": 52, "text": "\u0623\u0630\u0643\u0631 \u062b\u0644\u0627\u062b\u0629 \u0645\u0646 \u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629\u060c \u0648\u0627\u0634\u0631\u062d \u0648\u0627\u062d\u062f\u0627\u064b \u0645\u0646\u0647\u0627.", "questionType": "text", "answerText": "1. \u0627\u0644\u0627\u062a\u0633\u0627\u0642. 2. \u0627\u0644\u0642\u0627\u0628\u0644\u064a\u0629 \u0644\u0644\u062a\u0646\u0628\u0624. 3. \u0627\u0644\u0625\u062f\u0631\u0627\u0643 (\u0623\u0648 \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629\u060c \u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645)."}, {"id": "hci-lecture-1-q53", "number": 53, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 \u0646\u0645\u0637 \"\u0633\u0637\u0631 \u0627\u0644\u0623\u0648\u0627\u0645\u0631\" \u0648 \"\u0627\u0644\u0642\u0648\u0627\u0626\u0645\" \u0645\u0646 \u062d\u064a\u062b \u0633\u0647\u0648\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0648\u0627\u0644\u0642\u0648\u0629.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-1-q54", "number": 54, "text": "\u0645\u0627 \u0647\u064a \u0623\u0628\u0639\u0627\u062f \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u062e\u0645\u0633\u0629\u061f", "questionType": "text", "answerText": "1. \u0627\u0644\u0643\u0644\u0645\u0627\u062a (Words). 2. \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a (Visual Presentation). 3. \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u0627\u062f\u064a\u0629 (Physical Objects). 4. \u0627\u0644\u0648\u0642\u062a (Time). 5. \u0627\u0644\u0633\u0644\u0648\u0643 (Behavior)."}, {"id": "hci-lecture-1-q55", "number": 55, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0648\u0638\u064a\u0641\u064a\" \u0648 \"\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062a\u0633\u0644\u0633\u0644\u064a\" \u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u062d\u0643\u0645.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-1-q56", "number": 56, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u064a\" (Iterative Design)\u061f \u0648\u0644\u0645\u0627\u0630\u0627 \u0647\u0648 \u0636\u0631\u0648\u0631\u064a\u061f", "questionType": "text", "answerText": "\u0647\u0648 \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u062a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062a\u0643\u0631\u0627\u0631 \u062f\u0648\u0631\u0627\u062a \u0645\u0646 (\u062a\u0635\u0645\u064a\u0645 -> \u0646\u0645\u0648\u0630\u062c -> \u0627\u062e\u062a\u0628\u0627\u0631 -> \u062a\u0639\u062f\u064a\u0644)."}, {"id": "hci-lecture-1-q57", "number": 57, "text": "\u0648\u0636\u062d \u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0628\u064a\u0646 \"\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\" \u0648 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a\". \u0623\u064a\u0647\u0645\u0627 \u064a\u0633\u0628\u0642 \u0627\u0644\u0622\u062e\u0631\u061f", "questionType": "text", "answerText": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 (ID) \u064a\u0633\u0628\u0642 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0631\u0626\u064a (VD)."}, {"id": "hci-lecture-1-q58", "number": 58, "text": "\u0645\u0627 \u0647\u064a \u062e\u0637\u0648\u0627\u062a \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628\u061f", "questionType": "text", "answerText": "1. \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a (Requirements). 2. \u0627\u0644\u062a\u062d\u0644\u064a\u0644 (Analysis). 3. \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629 (Iteration & Prototyping). 4. \u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0648\u0627\u0644\u0646\u0634\u0631 (Implementation & Deployment)."}, {"id": "hci-lecture-1-q59", "number": 59, "text": "\u0627\u0634\u0631\u062d \u0645\u0628\u062f\u0623 \"\u0627\u0644\u0625\u062f\u0631\u0627\u0643\" (Perceivability) \u0645\u0639 \u0645\u062b\u0627\u0644.", "questionType": "text", "answerText": "\u064a\u0639\u0646\u064a \u0623\u0646 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u0627\u062a \u0648\u0627\u0644\u0648\u0638\u0627\u0626\u0641 \u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0648\u0627\u0636\u062d\u0629 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062f\u0648\u0646 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0644\u062a\u062c\u0631\u0628\u0629."}, {"id": "hci-lecture-1-q60", "number": 60, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0646\u0645\u0637 \"\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a\" \u0648 \"\u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629\" \u0641\u064a \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-3-q1", "number": 1, "text": "\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI) \u062a\u0631\u0643\u0632 \u0641\u0642\u0637 \u0639\u0644\u0649 \u0627\u0644\u0634\u0643\u0644 \u0627\u0644\u062c\u0645\u0627\u0644\u064a \u0648\u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647\u0627 \u0628\u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u0623\u0632\u0631\u0627\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q2", "number": 2, "text": "\"\u0627\u0644\u062d\u0627\u0648\u064a\u0627\u062a\" (Containers) \u0641\u064a \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0641\u064a \u0623\u0642\u0633\u0627\u0645 \u0630\u0627\u062a \u0645\u0639\u0646\u0649.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q3", "number": 3, "text": "\u0645\u0628\u062f\u0623 \"\u0627\u0644\u0623\u0644\u0641\u0629\" (Familiarity) \u064a\u0639\u0646\u064a \u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0627\u062a \u062c\u062f\u064a\u062f\u0629 \u0648\u0645\u0628\u062a\u0643\u0631\u0629 \u062a\u0645\u0627\u0645\u0627\u064b \u0644\u062a\u062c\u0646\u0628 \u0627\u0644\u0645\u0644\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q4", "number": 4, "text": "\"\u062a\u062d\u0643\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\" (User Control) \u064a\u0639\u0646\u064a \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u062d\u0631\u064a\u0629 \u0627\u0631\u062a\u0643\u0627\u0628 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0645\u0639 \u062a\u0648\u0641\u064a\u0631 \u0648\u0633\u064a\u0644\u0629 \u0644\u0644\u062a\u0631\u0627\u062c\u0639 (Undo).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q5", "number": 5, "text": "\u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0647\u0631\u0645\u064a \u0627\u0644\u0628\u0635\u0631\u064a (Hierarchy) \u064a\u0639\u062a\u0645\u062f \u0641\u0642\u0637 \u0639\u0644\u0649 \u062d\u062c\u0645 \u0627\u0644\u062e\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q6", "number": 6, "text": "\"\u0627\u0644\u0645\u0631\u0648\u0646\u0629\" (Flexibility) \u0641\u064a \u062a\u0635\u0645\u064a\u0645 UI \u062a\u0639\u0646\u064a \u0642\u062f\u0631\u0629 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0639\u0644\u0649 \u062e\u062f\u0645\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u0645\u0628\u062a\u062f\u0626\u064a\u0646 \u0648\u0627\u0644\u062e\u0628\u0631\u0627\u0621 \u0645\u0639\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q7", "number": 7, "text": "\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UX) \u062a\u0642\u062a\u0635\u0631 \u0639\u0644\u0649 \u0634\u0639\u0648\u0631 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062d\u0638\u0629 \u0634\u0631\u0627\u0621 \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q8", "number": 8, "text": "\u0645\u0631\u062d\u0644\u0629 \"\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c\" (Product Definition) \u062a\u0623\u062a\u064a \u0628\u0639\u062f \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645\".", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q9", "number": 9, "text": "\"\u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\" (Information Architecture) \u062a\u0647\u062a\u0645 \u0628\u0643\u064a\u0641\u064a\u0629 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0648\u0647\u064a\u0643\u0644 \u0627\u0644\u0645\u0646\u062a\u062c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q10", "number": 10, "text": "\u0645\u0635\u0645\u0645 UI \u064a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0645\u0647\u0627\u0631\u0627\u062a \u0641\u064a \"\u0623\u0628\u062d\u0627\u062b \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\" \u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0635\u0645\u0645 UX.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q11", "number": 11, "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0628 (RWD) \u064a\u0639\u0646\u064a \u0625\u0646\u0634\u0627\u0621 \u0645\u0648\u0642\u0639\u064a\u0646 \u0645\u0646\u0641\u0635\u0644\u064a\u0646 \u0644\u0644\u0645\u0648\u0628\u0627\u064a\u0644 \u0648\u0627\u0644\u0643\u0645\u0628\u064a\u0648\u062a\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q12", "number": 12, "text": "\u0625\u0637\u0627\u0631 \u0627\u0644\u0639\u0645\u0644 Bootstrap \u064a\u0648\u0641\u0631 \u0648\u0642\u062a\u0627\u064b \u0648\u062c\u0647\u062f\u0627\u064b \u0644\u0644\u0645\u0637\u0648\u0631\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q13", "number": 13, "text": "\u0646\u0638\u0627\u0645 \u0627\u0644\u0634\u0628\u0643\u0629 \u0641\u064a Bootstrap \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u0649 \u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u0635\u0641\u062d\u0629 \u0625\u0644\u0649 10 \u0623\u0639\u0645\u062f\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q14", "number": 14, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `col-lg` \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0623\u0642\u0644 \u0645\u0646 576 \u0628\u0643\u0633\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q15", "number": 15, "text": "\u064a\u0645\u0643\u0646 \u062f\u0645\u062c \u0643\u0644\u0627\u0633\u0627\u062a Bootstrap (\u0645\u062b\u0644 `col-md` \u0648 `col-sm`) \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0639\u0646\u0635\u0631 \u0644\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0627\u0644\u0634\u0643\u0644 \u0639\u0644\u0649 \u0623\u062c\u0647\u0632\u0629 \u0645\u062e\u062a\u0644\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q16", "number": 16, "text": "\"\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644\" (Accessibility) \u062a\u0639\u0646\u064a \u0633\u0647\u0648\u0644\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0635\u0641\u062d\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q17", "number": 17, "text": "\"\u0627\u0644\u0648\u0636\u0648\u062d\" (Clarity) \u064a\u0639\u0646\u064a \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0641\u062c\u0648\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0628\u064a\u0646 \u0645\u0627 \u064a\u0639\u0631\u0641\u0647 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0648\u0645\u0627 \u064a\u062d\u062a\u0627\u062c \u0644\u0645\u0639\u0631\u0641\u062a\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q18", "number": 18, "text": "\u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\" \u0641\u064a UX \u0644\u0627 \u062a\u062a\u0637\u0644\u0628 \u0648\u062c\u0648\u062f \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q19", "number": 19, "text": "\"\u0627\u0644\u0641\u0631\u0627\u063a \u0627\u0644\u0633\u0644\u0628\u064a\" (Negative Space) \u064a\u0634\u062a\u062a \u0627\u0646\u062a\u0628\u0627\u0647 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q20", "number": 20, "text": "\u0645\u0635\u0645\u0645 UI \u064a\u062d\u062a\u0627\u062c \u0644\u0645\u0639\u0631\u0641\u0629 HTML/CSS \u0644\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629 \u0627\u0644\u0633\u0631\u064a\u0639\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q21", "number": 21, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0639\u0646\u0635\u0631 \u0627\u0644\u0630\u064a \u064a\u064f\u0635\u0646\u0641 \u0636\u0645\u0646 \"\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0625\u062f\u062e\u0627\u0644\" (Input Controls)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0642\u062f\u0645 (Progress Bar)."}, {"key": "B", "text": "\u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 (Dropdown List)."}, {"key": "C", "text": "\u0623\u064a\u0642\u0648\u0646\u0629 \u0627\u0644\u062a\u0646\u0628\u064a\u0647."}, {"key": "D", "text": "\u0627\u0644\u062d\u0627\u0648\u064a\u0629 (Container)."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q22", "number": 22, "text": "\u0641\u064a \u0633\u064a\u0627\u0642 UI\u060c \u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \"\u0645\u0628\u062f\u0623 \u0627\u0644\u0623\u0644\u0641\u0629\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0646 \u064a\u0639\u0631\u0641 \u0627\u0644\u0645\u0635\u0645\u0639 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0634\u062e\u0635\u064a\u0627\u064b."}, {"key": "B", "text": "\u0623\u0646 \u062a\u0639\u0645\u0644 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0628\u0646\u0641\u0633 \u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u062a\u064a \u064a\u062a\u0648\u0642\u0639\u0647\u0627 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0645\u0646 \u062a\u062c\u0627\u0631\u0628\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0635\u0648\u0631 \u0639\u0627\u0626\u0644\u064a\u0629."}, {"key": "D", "text": "\u062a\u0643\u0631\u0627\u0631 \u0646\u0641\u0633 \u0627\u0644\u0639\u0646\u0627\u0635\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q23", "number": 23, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u064a \u064a\u062a\u0645 \u0641\u064a\u0647\u0627 \u0625\u0646\u0634\u0627\u0621 \"\u0627\u0644\u0634\u062e\u0635\u064a\u0627\u062a\" (Personas) \u0641\u064a \u0639\u0645\u0644\u064a\u0629 UX\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "C", "text": "\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "D", "text": "\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q24", "number": 24, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `col-sm-4` \u0648 `col-md-4` \u0641\u064a Bootstrap\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "B", "text": "`col-sm-4` \u064a\u0638\u0647\u0631 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629\u060c \u0648 `col-md-4` \u0639\u0644\u0649 \u0627\u0644\u0635\u063a\u064a\u0631\u0629."}, {"key": "C", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u064a\u0639\u0637\u064a \u0639\u0631\u0636\u0627\u064b \u064a\u0633\u0627\u0648\u064a \u062b\u0644\u062b \u0627\u0644\u0635\u0641\u062d\u0629 (4 \u0645\u0646 12)\u060c \u0644\u0643\u0646 `col-sm` \u064a\u0646\u0637\u0628\u0642 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629 \u0648\u0645\u0627\u0641\u0648\u0642\u0647\u0627\u060c \u0648 `col-md` \u0639\u0644\u0649 \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629 \u0648\u0645\u0627 \u0641\u0648\u0642\u0647\u0627."}, {"key": "D", "text": "`col-md-4` \u064a\u062c\u0639\u0644 \u0627\u0644\u0639\u0646\u0635\u0631 \u0645\u062e\u0641\u064a\u0627\u064b."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q25", "number": 25, "text": "\u0623\u064a \u0645\u0645\u0627 \u064a\u0644\u064a \u064a\u0639\u062f \u0645\u0646 \u0645\u0647\u0627\u0631\u0627\u062a \"\u0645\u0635\u0645\u0645 UX\" \u0648\u0644\u064a\u0633 UI\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0623\u0644\u0648\u0627\u0646."}, {"key": "B", "text": "\u0623\u0628\u062d\u0627\u062b \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (User Research)."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Adobe XD."}, {"key": "D", "text": "\u0627\u0644\u0637\u0628\u0627\u0639\u0629 (Typography)."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q26", "number": 26, "text": "\u0645\u0627 \u0647\u064a \u0641\u0627\u0626\u062f\u0629 \"\u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0627\u0644\u0623\u0648\u0644\u064a\u0629\" (Wireframes)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0644\u0648\u064a\u0646 \u0627\u0644\u0648\u0627\u062c\u0647\u0629."}, {"key": "B", "text": "\u062a\u0648\u0636\u064a\u062d \u0647\u064a\u0643\u0644 \u0627\u0644\u0635\u0641\u062d\u0629 \u0648\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u062f\u0648\u0646 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u062c\u0645\u0627\u0644\u064a\u0629."}, {"key": "C", "text": "\u0643\u062a\u0627\u0628\u0629 \u0643\u0648\u062f \u0627\u0644\u062e\u0627\u062f\u0645."}, {"key": "D", "text": "\u0628\u064a\u0639 \u0627\u0644\u0645\u0646\u062a\u062c."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q27", "number": 27, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0645\u062e\u0631\u062c \u0627\u0644\u0637\u0648\u0627\u0631\u0626\" \u0641\u064a \u0645\u0628\u062f\u0623 \u062a\u062d\u0643\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u0631 \u0644\u0627\u0633\u062a\u062f\u0639\u0627\u0621 \u0627\u0644\u0634\u0631\u0637\u0629."}, {"key": "B", "text": "\u062e\u064a\u0627\u0631 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 (Undo) \u0623\u0648 \u0627\u0644\u0625\u0644\u063a\u0627\u0621 \u0644\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u062d\u0627\u0644\u0629 \u063a\u064a\u0631 \u0645\u0631\u063a\u0648\u0628 \u0641\u064a\u0647\u0627."}, {"key": "C", "text": "\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u062c\u0647\u0627\u0632."}, {"key": "D", "text": "\u062d\u0630\u0641 \u0627\u0644\u062d\u0633\u0627\u0628."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q28", "number": 28, "text": "\u0645\u0627 \u0647\u064a \u0623\u0643\u0628\u0631 \u0634\u0627\u0634\u0629 \u064a\u062f\u0639\u0645\u0647\u0627 \u0643\u0644\u0627\u0633 `col-lg`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "768px."}, {"key": "B", "text": "992px."}, {"key": "C", "text": "1200px \u0641\u0623\u0643\u062b\u0631."}, {"key": "D", "text": "576px."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q29", "number": 29, "text": "\u0643\u064a\u0641 \u064a\u0645\u0643\u0646 \u062a\u062d\u0642\u064a\u0642 \"\u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0647\u0631\u0645\u064a\" \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0644\u0648\u0646\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0627\u0644\u062f\u0627\u0643\u0646\u0629 \u0644\u0643\u0644 \u0634\u064a\u0621."}, {"key": "B", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u0644\u0648\u0627\u0646 \u0632\u0627\u0647\u064a\u0629 \u0644\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0642\u0644 \u0623\u0647\u0645\u064a\u0629."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0623\u0644\u0648\u0627\u0646 \u0645\u062a\u0628\u0627\u064a\u0646\u0629 \u0648\u062c\u0630\u0627\u0628\u0629 \u0644\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0643\u062b\u0631 \u0623\u0647\u0645\u064a\u0629."}, {"key": "D", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u0648\u0646 \u0648\u0627\u062d\u062f \u0641\u0642\u0637."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q30", "number": 30, "text": "\u0645\u0627 \u0647\u0648 \"\u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c\" (Product Definition)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0631\u062d\u0644\u0629 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062f."}, {"key": "B", "text": "\u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u062a\u062d\u062f\u064a\u062f \u0645\u0627 \u0647\u0648 \u0645\u0637\u0644\u0648\u0628 \u0648\u0641\u0647\u0645 \u0633\u064a\u0627\u0642 \u0627\u0644\u0645\u0634\u0631\u0648\u0639."}, {"key": "C", "text": "\u0645\u0631\u062d\u0644\u0629 \u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u0645\u0648\u0642\u0639."}, {"key": "D", "text": "\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0633\u0648\u064a\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q31", "number": 31, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u0644\u064a\u0633 \u0645\u0646 \u0645\u0632\u0627\u064a\u0627 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0628 (RWD)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u062d\u0633\u064a\u0646 \u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "B", "text": "\u062a\u062d\u0633\u064a\u0646 \u062a\u0631\u062a\u064a\u0628 \u0645\u062d\u0631\u0643\u0627\u062a \u0627\u0644\u0628\u062d\u062b (SEO)."}, {"key": "C", "text": "\u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0635\u064a\u0627\u0646\u0629 \u0645\u0648\u0642\u0639\u064a\u0646 \u0645\u0646\u0641\u0635\u0644\u064a\u0646."}, {"key": "D", "text": "\u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0648\u0642\u062a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q32", "number": 32, "text": "\u0645\u0627 \u0647\u0648 \u062f\u0648\u0631 \"\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u0646\u0642\u0644\" (Navigational Elements)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a."}, {"key": "B", "text": "\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u0646\u0642\u0644 \u0641\u064a \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0648\u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u0647\u0627\u0645."}, {"key": "C", "text": "\u0639\u0631\u0636 \u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062e\u0637\u0623."}, {"key": "D", "text": "\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0635\u0648\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q33", "number": 33, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \u0627\u0644\u0643\u0644\u0627\u0633 `col-12` \u0641\u064a Bootstrap\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0639\u0646\u0635\u0631 \u0645\u062e\u0641\u064a."}, {"key": "B", "text": "\u0639\u0646\u0635\u0631 \u064a\u0623\u062e\u0630 \u0643\u0627\u0645\u0644 \u0639\u0631\u0636 \u0627\u0644\u0635\u0641 (100%)."}, {"key": "C", "text": "\u0639\u0646\u0635\u0631 \u064a\u0623\u062e\u0630 \u0646\u0635\u0641 \u0627\u0644\u0635\u0641."}, {"key": "D", "text": "\u0639\u0646\u0635\u0631 \u064a\u0623\u062e\u0630 12 \u0639\u0645\u0648\u062f\u0627\u064b \u0645\u062a\u062c\u0627\u0648\u0632\u0627\u064b \u0627\u0644\u062d\u062f."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q34", "number": 34, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 UI \u0648 UX \u0645\u0646 \u062d\u064a\u062b \"\u0627\u0644\u0646\u0637\u0627\u0642\" (Scope)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "UI \u0623\u0648\u0633\u0639 \u0646\u0637\u0627\u0642\u0627\u064b."}, {"key": "B", "text": "UX \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0634\u0643\u0644 \u0641\u0642\u0637."}, {"key": "C", "text": "UI \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0648\u0627\u0644\u0623\u0632\u0631\u0627\u0631\u060c \u0628\u064a\u0646\u0645\u0627 UX \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0631\u062d\u0644\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q35", "number": 35, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0645\u0631\u0648\u0646\u0629\" \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0644\u0644\u0645\u0628\u0631\u0645\u062c\u064a\u0646 \u0641\u0642\u0637."}, {"key": "B", "text": "\u0642\u062f\u0631\u0629 \u0627\u0644\u0648\u0627\u062c\u0647\u0629 \u0639\u0644\u0649 \u062e\u062f\u0645\u0629 \u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0628\u0645\u0647\u0627\u0631\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629 (\u0645\u0628\u062a\u062f\u0626/\u062e\u0628\u064a\u0631) \u0648\u0623\u062c\u0647\u0632\u0629 \u0645\u062e\u062a\u0644\u0641\u0629."}, {"key": "C", "text": "\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0628\u0627\u0633\u062a\u0645\u0631\u0627\u0631."}, {"key": "D", "text": "\u0625\u0636\u0627\u0641\u0629 \u0645\u0645\u064a\u0632\u0627\u062a \u0645\u0639\u0642\u062f\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q36", "number": 36, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u064a\u0629\" (Informational Components)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0632\u0631\u0627\u0631 \u0627\u0644\u0625\u0631\u0633\u0627\u0644."}, {"key": "B", "text": "\u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u064a \u062a\u0648\u0635\u0644 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (\u0645\u062b\u0644 \u0623\u0634\u0631\u0637\u0629 \u0627\u0644\u062a\u0642\u062f\u0645)."}, {"key": "C", "text": "\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u062a\u0646\u0642\u0644."}, {"key": "D", "text": "\u062d\u0642\u0648\u0644 \u0627\u0644\u0646\u0635."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q37", "number": 37, "text": "\u0643\u064a\u0641 \u064a\u0633\u0627\u0647\u0645 Bootstrap \u0641\u064a \"\u0627\u0644\u0627\u062a\u0633\u0627\u0642\" (Consistency)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0641\u0631\u0636 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u0648\u0646 \u0648\u0627\u062d\u062f."}, {"key": "B", "text": "\u064a\u0648\u0641\u0631 \u0645\u0643\u062a\u0628\u0629 \u0645\u0648\u062d\u062f\u0629 \u0645\u0646 \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0630\u0627\u062a \u0627\u0644\u0634\u0643\u0644 \u0627\u0644\u0645\u0648\u062d\u062f."}, {"key": "C", "text": "\u064a\u0645\u0646\u0639 \u0627\u0644\u062a\u0639\u062f\u064a\u0644 \u0639\u0644\u0649 \u0627\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0633\u0627\u0647\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q38", "number": 38, "text": "\u0645\u0627 \u0647\u064a \u0645\u0631\u062d\u0644\u0629 \"\u0627\u0644\u0628\u062d\u062b\" (Product Research)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0642\u0648\u0627\u0644\u0628 \u062c\u0627\u0647\u0632\u0629."}, {"key": "B", "text": "\u0625\u062c\u0631\u0627\u0621 \u0623\u0628\u062d\u0627\u062b \u0627\u0644\u0633\u0648\u0642 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0633\u064a\u0646 \u0644\u0641\u0647\u0645 \u0627\u0644\u0641\u0631\u0635."}, {"key": "C", "text": "\u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0645\u0633\u062a\u062b\u0645\u0631\u064a\u0646."}, {"key": "D", "text": "\u0627\u0644\u0628\u062d\u062b \u0641\u064a \u0645\u062d\u0631\u0643\u0627\u062a \u0627\u0644\u0628\u062d\u062b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q39", "number": 39, "text": "\u0645\u0627\u0630\u0627 \u064a\u062d\u062f\u062b \u0625\u0630\u0627 \u062a\u062c\u0627\u0648\u0632 \u0645\u062c\u0645\u0648\u0639 \u0627\u0644\u0623\u0639\u0645\u062f\u0629 \u0641\u064a \u0627\u0644\u0635\u0641 \u0627\u0644\u0648\u0627\u062d\u062f 12\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0627 \u064a\u062d\u062f\u062b \u0634\u064a\u0621."}, {"key": "B", "text": "\u064a\u062a\u0645 \u0642\u0637\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0632\u0627\u0626\u062f."}, {"key": "C", "text": "\u064a\u062a\u0645 \u062f\u0641\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0632\u0627\u0626\u062f\u0629 \u0644\u0633\u0637\u0631 \u062c\u062f\u064a\u062f \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b."}, {"key": "D", "text": "\u064a\u0639\u0637\u064a \u0627\u0644\u0646\u0638\u0627\u0645 \u062e\u0637\u0623."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q40", "number": 40, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u062e\u062a\u0628\u0627\u0631 \u0642\u0627\u0628\u0644\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645\" (Usability Testing) \u0645\u0647\u0645\u0627\u064b\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0646\u062a\u062c \u0645\u0639 \u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u062d\u0642\u064a\u0642\u064a\u064a\u0646 \u0648\u0627\u0643\u062a\u0634\u0627\u0641 \u0627\u0644\u0623\u062e\u0637\u0627\u0621."}, {"key": "B", "text": "\u0644\u0632\u064a\u0627\u062f\u0629 \u0645\u0628\u064a\u0639\u0627\u062a \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "C", "text": "\u0644\u062a\u062d\u0633\u064a\u0646 \u0634\u0643\u0644 \u0627\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "D", "text": "\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u0648\u062b\u064a\u0642."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q41", "number": 41, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0647\u062f\u0641 \u0645\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \"\u0627\u0644\u062a\u0628\u0627\u064a\u0646\" \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0625\u0631\u0628\u0627\u0643 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645."}, {"key": "B", "text": "\u0644\u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0645\u0647\u0645\u0629 \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0639\u064a\u0646."}, {"key": "C", "text": "\u0644\u062a\u062c\u0645\u064a\u0644 \u0627\u0644\u0635\u0641\u062d\u0629 \u0641\u0642\u0637."}, {"key": "D", "text": "\u0644\u062a\u0642\u0644\u064a\u0644 \u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062a\u062d\u0645\u064a\u0644."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q42", "number": 42, "text": "\u0645\u0627 \u0647\u064a \"\u0646\u0642\u0637\u0629 \u0627\u0644\u0627\u0646\u0643\u0633\u0627\u0631\" (Breakpoint) \u0644\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629 (md)\u061f", "questionType": "choice", "options": [{"key": "A", "text": ">= 576px."}, {"key": "B", "text": ">= 768px."}, {"key": "C", "text": ">= 992px."}, {"key": "D", "text": ">= 1200px."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-3-q43", "number": 43, "text": "\u0645\u0627 \u0627\u0644\u0630\u064a \u064a\u0645\u064a\u0632 \u0645\u0635\u0645\u0645 UI \u0639\u0646 \u0645\u0635\u0645\u0645 \u0627\u0644\u062c\u0631\u0627\u0641\u064a\u0643 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0635\u0645\u0645 UI \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0648\u0633\u0644\u0648\u0643 \u0627\u0644\u0639\u0646\u0627\u0635\u0631\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u062c\u0631\u0627\u0641\u064a\u0643 \u064a\u0631\u0643\u0632 \u0639\u0644\u0649 \u0627\u0644\u0637\u0628\u0627\u0639\u0629 \u0648\u0627\u0644\u0635\u0648\u0631\u0629 \u0627\u0644\u062b\u0627\u0628\u062a\u0629."}, {"key": "B", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "C", "text": "\u0645\u0635\u0645\u0645 \u0627\u0644\u062c\u0631\u0627\u0641\u064a\u0643 \u064a\u0628\u0631\u0645\u062c."}, {"key": "D", "text": "\u0645\u0635\u0645\u0645 UI \u0644\u0627 \u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0623\u0644\u0648\u0627\u0646."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-3-q44", "number": 44, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0645\u0647\u0627\u0645\" (Tasks) \u0641\u064a \u0633\u064a\u0627\u0642 UX\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0648\u0627\u062c\u0628\u0627\u062a \u0627\u0644\u0645\u0628\u0631\u0645\u062c\u064a\u0646."}, {"key": "B", "text": "\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u064a \u064a\u0633\u0639\u0649 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u062d\u0642\u064a\u0642\u0647\u0627 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "C", "text": "\u0623\u0648\u0627\u0645\u0631 \u0646\u0638\u0627\u0645 \u0627\u0644\u062a\u0634\u063a\u064a\u0644."}, {"key": "D", "text": "\u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q45", "number": 45, "text": "\u0643\u064a\u0641 \u064a\u0648\u0641\u0631 Bootstrap \"\u0648\u0642\u062a \u0627\u0644\u0645\u0637\u0648\u0631\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0643\u062a\u0628 \u0627\u0644\u0643\u0648\u062f \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u062f\u0648\u0646 \u062a\u062f\u062e\u0644."}, {"key": "B", "text": "\u064a\u0648\u0641\u0631 \u0643\u0648\u062f CSS \u0648 HTML \u062c\u0627\u0647\u0632\u0627\u064b \u0644\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0634\u0627\u0626\u0639\u0629."}, {"key": "C", "text": "\u064a\u0645\u0646\u0639 \u0627\u0644\u062d\u0627\u062c\u0629 \u0644\u0644\u062a\u0635\u0645\u064a\u0645."}, {"key": "D", "text": "\u064a\u062c\u0639\u0644 \u0627\u0644\u0645\u0648\u0642\u0639 \u0623\u0633\u0631\u0639 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q46", "number": 46, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"Viewport\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0646\u0633\u0628\u0629 \u0627\u0644\u062a\u0643\u0628\u064a\u0631."}, {"key": "B", "text": "\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0645\u0631\u0626\u064a\u0629 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632."}, {"key": "C", "text": "\u062d\u062c\u0645 \u0627\u0644\u0645\u0644\u0641."}, {"key": "D", "text": "\u062f\u0642\u0629 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q47", "number": 47, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062a\u0628\u0631 \u0645\u064a\u0632\u0629 \"\u062a\u0646\u0627\u0641\u0633\u064a\u0629\" \u0644\u062a\u0635\u0645\u064a\u0645 UI \u0627\u0644\u062c\u064a\u062f\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u064a\u0627\u062f\u0629 \u062a\u0643\u0644\u0641\u0629 \u0627\u0644\u0645\u0646\u062a\u062c."}, {"key": "B", "text": "\u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0645\u0646\u062a\u062c \u0648\u062a\u0648\u0641\u064a\u0631 \u062a\u062c\u0631\u0628\u0629 \u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u0627\u0626\u0642\u0629."}, {"key": "C", "text": "\u062a\u0639\u0642\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645."}, {"key": "D", "text": "\u062a\u0642\u0644\u064a\u062f \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u064a\u0646."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q48", "number": 48, "text": "\u0645\u0627 \u0647\u064a \"\u0627\u0644\u0642\u0627\u0628\u0644\u064a\u0629 \u0644\u0644\u062a\u0639\u0644\u0645\" (Learnability) \u0641\u064a \u0645\u0628\u0627\u062f\u0626 UI\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u0630\u0643\u064a\u0627\u064b."}, {"key": "B", "text": "\u0645\u062f\u0649 \u0633\u0647\u0648\u0644\u0629 \u062a\u0639\u0644\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u0646\u0638\u0627\u0645 \u0645\u0646 \u0623\u0648\u0644 \u0645\u0631\u0629."}, {"key": "C", "text": "\u0648\u062c\u0648\u062f \u062f\u0648\u0631\u0627\u062a \u062a\u062f\u0631\u064a\u0628\u064a\u0629 \u0645\u0643\u062b\u0641\u0629."}, {"key": "D", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q49", "number": 49, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0644\u062c\u0639\u0644 \u0639\u0646\u0635\u0631 \u064a\u0639\u0631\u0636 \u0643\u0639\u0645\u0648\u062f \u0648\u0627\u062d\u062f (Full Width) \u0639\u0644\u0649 \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644\u060c \u0648\u0639\u0645\u0648\u062f\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062a\u0627\u0628\u0644\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`col-6 col-sm-12`."}, {"key": "B", "text": "`col-12 col-sm-6`."}, {"key": "C", "text": "`col-xs-1 col-sm-2`."}, {"key": "D", "text": "`col-12 col-lg-6`."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q50", "number": 50, "text": "\u0645\u0627 \u0647\u064a \u062e\u0637\u0648\u0631\u0629 \u062a\u062c\u0627\u0647\u0644 \"\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644\" (Accessibility)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062e\u0633\u0627\u0631\u0629 \u0645\u0627\u0644\u064a\u0629 \u0641\u0642\u0637."}, {"key": "B", "text": "\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0634\u0631\u064a\u062d\u0629 \u0643\u0628\u064a\u0631\u0629 \u0645\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0645\u0634\u0627\u0643\u0644 \u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0645\u062d\u062a\u0645\u0644\u0629."}, {"key": "C", "text": "\u0644\u0627 \u062e\u0637\u0648\u0631\u0629."}, {"key": "D", "text": "\u0628\u0637\u0621 \u0627\u0644\u0645\u0648\u0642\u0639."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-3-q51", "number": 51, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI) \u0648\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UX) \u0645\u0646 \u062d\u064a\u062b \u0627\u0644\u062a\u0639\u0631\u064a\u0641 \u0648\u0627\u0644\u0647\u062f\u0641.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-3-q52", "number": 52, "text": "\u0623\u0630\u0643\u0631 \u0645\u0628\u0627\u062f\u0626 \u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI) \u0627\u0644\u0633\u062a\u0629.", "questionType": "text", "answerText": "1. \u0627\u0644\u0648\u0636\u0648\u062d. 2. \u0627\u0644\u0623\u0644\u0641\u0629. 3. \u062a\u062d\u0643\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645. 4. \u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0647\u0631\u0645\u064a. 5. \u0627\u0644\u0645\u0631\u0648\u0646\u0629. 6. \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644."}, {"id": "hci-lecture-3-q53", "number": 53, "text": "\u0627\u0634\u0631\u062d \u0645\u0631\u0627\u062d\u0644 \u0639\u0645\u0644\u064a\u0629 \u062a\u0635\u0645\u064a\u0645 \u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UX) \u0628\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0628\u0627\u062e\u062a\u0635\u0627\u0631.", "questionType": "text", "answerText": "1. \u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0645\u0646\u062a\u062c (\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a). 2. \u0628\u062d\u062b \u0627\u0644\u0645\u0646\u062a\u062c (\u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u0633\u0648\u0642). 3. \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (\u0634\u062e\u0635\u064a\u0627\u062a \u0648\u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a). 4. \u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a (\u0627\u0644\u0647\u064a\u0643\u0644 \u0648\u0627\u0644\u062a\u0646\u0642\u0644). 5. \u0627\u0644\u062a\u0635\u0645\u064a\u0645 (\u0627\u0644\u0631\u0633\u0648\u0645\u0627\u062a \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062c). 6. \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0648\u0627\u0644\u062a\u062d\u0642\u0642."}, {"id": "hci-lecture-3-q54", "number": 54, "text": "\u0645\u0627 \u0647\u0648 \"\u0646\u0638\u0627\u0645 \u0627\u0644\u0634\u0628\u0643\u0629\" (Grid System) \u0641\u064a Bootstrap\u061f \u0648\u0643\u064a\u0641 \u064a\u0639\u0645\u0644\u061f", "questionType": "text", "answerText": "\u0647\u0648 \u0646\u0638\u0627\u0645 \u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0635\u0641\u062d\u0629 \u064a\u0642\u0633\u0645\u0647\u0627 \u0625\u0644\u0649 12 \u0639\u0645\u0648\u062f\u0627\u064b \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0627\u064b. \u064a\u0633\u0645\u062d \u0644\u0644\u0645\u0637\u0648\u0631 \u0628\u062a\u062d\u062f\u064a\u062f \u0639\u0631\u0636 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a (\u0645\u062b\u0644 `col-md-6`) \u0644\u0644\u062a\u062d\u0643\u0645 \u0641\u064a \u0643\u064a\u0641\u064a\u0629 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0623\u0641\u0642\u064a\u0627\u064b."}, {"id": "hci-lecture-3-q55", "number": 55, "text": "\u0645\u0627 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0640 \"\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644\" (Accessibility)\u061f \u0648\u0643\u064a\u0641 \u064a\u0645\u0643\u0646 \u062a\u0637\u0628\u064a\u0642\u0647\u0627\u061f", "questionType": "text", "answerText": "\u062a\u0639\u0646\u064a \u062a\u0635\u0645\u064a\u0645 \u0645\u0646\u062a\u062c\u0627\u062a \u064a\u0645\u0643\u0646 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0645\u060c \u0628\u0645\u0627 \u0641\u064a\u0647\u0645 \u0630\u0648\u0648 \u0627\u0644\u0625\u0639\u0627\u0642\u0629."}, {"id": "hci-lecture-3-q56", "number": 56, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `col-sm` \u0648 `col-lg`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-3-q57", "number": 57, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u0643\u0648\u0646 \u0645\u0646\u0647\u0627 \u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (UI Elements)\u061f", "questionType": "text", "answerText": "1. \u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0625\u062f\u062e\u0627\u0644 (Input Controls). 2. \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u0646\u0642\u0644 (Navigational Components). 3. \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u064a\u0629 (Informational Components). 4. \u0627\u0644\u062d\u0627\u0648\u064a\u0627\u062a (Containers)."}, {"id": "hci-lecture-3-q58", "number": 58, "text": "\u0644\u0645\u0627\u0630\u0627 \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u0641\u0631\u0627\u063a \u0627\u0644\u0633\u0644\u0628\u064a\" (Negative Space) \u0645\u0647\u0645\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u061f", "questionType": "text", "answerText": "\u0644\u0627 \u064a\u0639\u062a\u0628\u0631 \u0645\u0633\u0627\u062d\u0629 \u0645\u0647\u062f\u0631\u0629\u060c \u0628\u0644 \u0639\u0646\u0635\u0631 \u062a\u0635\u0645\u064a\u0645\u064a \u064a\u0633\u0627\u0639\u062f \u0639\u0644\u0649 \u0641\u0635\u0644 \u0627\u0644\u0639\u0646\u0627\u0635\u0631\u060c \u0625\u0631\u0627\u062d\u0629 \u0627\u0644\u0639\u064a\u0646\u060c \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0644\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0647\u0645."}, {"id": "hci-lecture-3-q59", "number": 59, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0645\u0647\u0627\u0645 \u0645\u0635\u0645\u0645 UI \u0648\u0645\u0635\u0645\u0645 UX\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-3-q60", "number": 60, "text": "\u0643\u064a\u0641 \u064a\u062f\u0639\u0645 Bootstrap \u0645\u0641\u0647\u0648\u0645 \"\u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0633\u0631\u064a\u0639 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629\" (Responsive Design)\u061f", "questionType": "text", "answerText": "\u0645\u0646 \u062e\u0644\u0627\u0644 \u0646\u0638\u0627\u0645 \u0627\u0644\u0634\u0628\u0643\u0629 \u0627\u0644\u0645\u062a\u063a\u064a\u0631\u060c \u062d\u064a\u062b \u064a\u0645\u0643\u0646 \u0644\u0644\u0645\u0637\u0648\u0631 \u062a\u062d\u062f\u064a\u062f \u0643\u0644\u0627\u0633\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629 \u0644\u0646\u0641\u0633 \u0627\u0644\u0639\u0646\u0635\u0631 \u0644\u064a\u062a\u0635\u0631\u0641 \u0628\u0634\u0643\u0644 \u0645\u062e\u062a\u0644\u0641 \u0639\u0644\u0649 \u0623\u062d\u062c\u0627\u0645 \u0634\u0627\u0634\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629 (\u0645\u062b\u0644\u0627\u064b: \u0639\u0645\u0648\u062f \u0643\u0627\u0645\u0644 \u0641\u064a \u0627\u0644\u0645\u0648\u0628\u0627\u064a\u0644\u060c \u0648\u0646\u0635\u0641 \u0639\u0645\u0648\u062f \u0641\u064a \u0627\u0644\u0643\u0645\u0628\u064a\u0648\u062a\u0631)."}, {"id": "hci-lecture-4-q1", "number": 1, "text": "\u064a\u0645\u0643\u0646 \u062a\u0637\u0628\u064a\u0642 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0623\u0632\u0631\u0627\u0631 (`.btn`) \u0639\u0644\u0649 \u0639\u0646\u0627\u0635\u0631 `<a>` \u0648 `<input>` \u0648\u0644\u064a\u0633 \u0641\u0642\u0637 `<button>`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q2", "number": 2, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.btn-outline-*` \u064a\u0639\u0637\u064a \u0627\u0644\u0632\u0631 \u062e\u0644\u0641\u064a\u0629 \u0645\u0644\u0648\u0646\u0629 \u0645\u0639 \u062d\u062f\u0648\u062f \u0634\u0641\u0627\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q3", "number": 3, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.btn-sm` \u064a\u062c\u0639\u0644 \u0627\u0644\u0632\u0631 \u0643\u0628\u064a\u0631\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q4", "number": 4, "text": "`.nav-tabs` \u0648 `.nav-pills` \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0645\u0627 \u0645\u0639\u0627\u064b \u0644\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u0642\u0627\u0626\u0645\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q5", "number": 5, "text": "\u0627\u0644\u062a\u0628\u0648\u064a\u0628\u0627\u062a \u0627\u0644\u062f\u064a\u0646\u0627\u0645\u064a\u0643\u064a\u0629 (Dynamic Tabs) \u062a\u062a\u0637\u0644\u0628 \u0648\u062c\u0648\u062f `.tab-content` \u0648 `.tab-pane`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q6", "number": 6, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.navbar-expand-lg` \u064a\u062c\u0639\u0644 \u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0646\u0642\u0644 \u0645\u0637\u0648\u064a\u0627\u064b (Collapsed) \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0643\u0628\u064a\u0631\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q7", "number": 7, "text": "`.table-striped` \u064a\u0636\u064a\u0641 \u0644\u0648\u0646\u0627\u064b \u0645\u062e\u062a\u0644\u0641\u0627\u064b \u0644\u0644\u0635\u0641\u0648\u0641 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 (Zebra Striping).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q8", "number": 8, "text": "`.table-hover` \u064a\u063a\u064a\u0631 \u0644\u0648\u0646 \u0627\u0644\u0635\u0641 \u0639\u0646\u062f \u0627\u0644\u0646\u0642\u0631 \u0639\u0644\u064a\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q9", "number": 9, "text": "`.table-dark` \u064a\u062d\u0648\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u062f\u0627\u0643\u0646 (\u062e\u0644\u0641\u064a\u0629 \u0633\u0648\u062f\u0627\u0621 \u0648\u0646\u0635 \u0623\u0628\u064a\u0636).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q10", "number": 10, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.table-responsive` \u064a\u062c\u0639\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u064a\u062a\u063a\u064a\u0631 \u0634\u0643\u0644\u0647 \u0644\u064a\u062a\u0646\u0627\u0633\u0628 \u0645\u0639 \u0627\u0644\u0634\u0627\u0634\u0629 \u0627\u0644\u0635\u063a\u064a\u0631\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0623\u0639\u0645\u062f\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q11", "number": 11, "text": "\"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0639\u0645\u0648\u062f\u064a\" (Vertical Form) \u0647\u0648 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0641\u064a Bootstrap.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q12", "number": 12, "text": "\"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0623\u0641\u0642\u064a\" (Horizontal Form) \u064a\u062a\u0637\u0644\u0628 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0634\u0628\u0643\u0629 (Grid classes) \u0645\u062b\u0644 `.row` \u0648 `.col`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q13", "number": 13, "text": "\"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u0636\u0645\u0646\" (Inline Form) \u064a\u0639\u0631\u0636 \u062c\u0645\u064a\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0641\u064a \u0633\u0637\u0631 \u0648\u0627\u062d\u062f \u0645\u062a\u0635\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q14", "number": 14, "text": "`.card-group` \u064a\u0639\u0631\u0636 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a \u0628\u0641\u0648\u0627\u0635\u0644 \u0648\u0645\u0633\u0627\u0641\u0627\u062a \u0628\u064a\u0646\u0647\u0627.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q15", "number": 15, "text": "`.card-img-top` \u064a\u0636\u0639 \u0627\u0644\u0635\u0648\u0631\u0629 \u0641\u064a \u0623\u0639\u0644\u0649 \u0627\u0644\u0628\u0637\u0627\u0642\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q16", "number": 16, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.stretched-link` \u064a\u062c\u0639\u0644 \u0643\u0627\u0645\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0646\u0642\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q17", "number": 17, "text": "\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 `.table-danger` \u0644\u062a\u0644\u0648\u064a\u0646 \u0635\u0641 \u0641\u064a \u0627\u0644\u062c\u062f\u0648\u0644 \u0628\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0623\u062d\u0645\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q18", "number": 18, "text": "\u0627\u0644\u0643\u0644\u0627\u0633 `.active` \u0641\u064a \u0627\u0644\u062a\u0646\u0642\u0644 \u064a\u062c\u0639\u0644 \u0627\u0644\u0639\u0646\u0635\u0631 \u064a\u0628\u062f\u0648 \u0645\u0641\u0639\u0644\u0627\u064b (\u0645\u0638\u0644\u0644\u0627\u064b).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q19", "number": 19, "text": "Spinner \u0647\u0648 \u0645\u0643\u0648\u0646 \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0639\u0631\u0636 \u0642\u0627\u0626\u0645\u0629 \u0645\u0646\u0633\u062f\u0644\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q20", "number": 20, "text": "`.container-fluid` \u064a\u0639\u0637\u064a \u062d\u0627\u0648\u064a\u0629 \u0628\u0639\u0631\u0636 \u0643\u0627\u0645\u0644 \u0627\u0644\u0634\u0627\u0634\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q21", "number": 21, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u0625\u0646\u0634\u0627\u0621 \u0632\u0631 \u0623\u062d\u0645\u0631 \u064a indicate \u062e\u0637\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.btn-danger`"}, {"key": "B", "text": "`.btn-warning`"}, {"key": "C", "text": "`.btn-red`"}, {"key": "D", "text": "`.btn-error`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q22", "number": 22, "text": "\u0643\u064a\u0641 \u062a\u0635\u0646\u0639 \u0632\u0631\u0627\u064b \u0634\u0641\u0627\u0641\u0627\u064b \u0630\u0627 \u062d\u062f\u0648\u062f \u0632\u0631\u0642\u0627\u0621\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.btn-primary`"}, {"key": "B", "text": "`.btn-outline-primary`"}, {"key": "C", "text": "`.btn-transparent`"}, {"key": "D", "text": "`.btn-border`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q23", "number": 23, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.nav-tabs` \u0648 `.nav-pills`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Tabs \u0623\u0641\u0642\u064a\u0629\u060c Pills \u0639\u0645\u0648\u062f\u064a\u0629."}, {"key": "B", "text": "Tabs \u062a\u0628\u062f\u0648 \u0643\u0645\u0644\u0641\u0627\u062a\u060c Pills \u062a\u0628\u062f\u0648 \u0643\u0623\u0632\u0631\u0627\u0631 \u0645\u0633\u062a\u062f\u064a\u0631\u0629."}, {"key": "C", "text": "Tabs \u0644\u0644\u062a\u0646\u0642\u0644\u060c Pills \u0644\u0644\u0625\u062f\u062e\u0627\u0644."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q24", "number": 24, "text": "\u0644\u062c\u0639\u0644 \u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0646\u0642\u0644 (Navbar) \u064a\u062e\u062a\u0641\u064a \u0648\u064a\u0638\u0647\u0631 \u0643\u0642\u0627\u0626\u0645\u0629 (Toggle) \u0639\u0644\u0649 \u0634\u0627\u0634\u0627\u062a \u0627\u0644\u062a\u0627\u0628\u0644\u062a\u060c \u0646\u0633\u062a\u062e\u062f\u0645:", "questionType": "choice", "options": [{"key": "A", "text": "`.navbar-expand-sm`"}, {"key": "B", "text": "`.navbar-expand-lg`"}, {"key": "C", "text": "`.navbar-hide`"}, {"key": "D", "text": "`.navbar-toggle`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q25", "number": 25, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0630\u064a \u064a\u0636\u064a\u0641 \u062d\u062f\u0648\u062f\u0627\u064b \u0644\u062c\u0645\u064a\u0639 \u062e\u0644\u0627\u064a\u0627 \u0627\u0644\u062c\u062f\u0648\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.table-striped`"}, {"key": "B", "text": "`.table-bordered`"}, {"key": "C", "text": "`.table-hover`"}, {"key": "D", "text": "`.table-borderless`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q26", "number": 26, "text": "\u0623\u064a \u0646\u0645\u0648\u0630\u062c (Form) \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0648\u0636\u0639 \u0627\u0644\u062a\u0633\u0645\u064a\u0629 (Label) \u0648\u0627\u0644\u062d\u0642\u0644 (Input) \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0633\u0637\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Vertical Form."}, {"key": "B", "text": "Horizontal Form."}, {"key": "C", "text": "Inline Form."}, {"key": "D", "text": "Grid Form."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q27", "number": 27, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.card-group` \u0648 `.card-deck`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Group \u064a\u0644\u0635\u0642 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a\u060c Deck \u064a\u062a\u0631\u0643 \u0641\u0631\u0627\u063a\u0627\u062a \u0628\u064a\u0646\u0647\u0627."}, {"key": "B", "text": "Deck \u064a\u0644\u0635\u0642 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a\u060c Group \u064a\u062a\u0631\u0643 \u0641\u0631\u0627\u063a\u0627\u062a."}, {"key": "C", "text": "Group \u0639\u0645\u0648\u062f\u064a\u060c Deck \u0623\u0641\u0642\u064a."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q28", "number": 28, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u0639\u0631\u0636 \u0646\u0635 \u0641\u0648\u0642 \u0635\u0648\u0631\u0629 \u062e\u0644\u0641\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.card-img-top`"}, {"key": "B", "text": "`.card-img-overlay`"}, {"key": "C", "text": "`.card-text-overlay`"}, {"key": "D", "text": "`.img-text`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q29", "number": 29, "text": "\u0645\u0627 \u0647\u0648 \u062f\u0648\u0631 `.spinner-border`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0625\u0636\u0627\u0641\u0629 \u062d\u062f\u0648\u062f \u0644\u0644\u062c\u062f\u0648\u0644."}, {"key": "B", "text": "\u0639\u0631\u0636 \u062f\u0627\u0626\u0631\u0629 \u062a\u062d\u0645\u064a\u0644 (Loading) \u062a\u062f\u0648\u0631."}, {"key": "C", "text": "\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062d\u062f\u0648\u062f."}, {"key": "D", "text": "\u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u0639\u0646\u0635\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q30", "number": 30, "text": "\u0643\u064a\u0641 \u062a\u062c\u0639\u0644 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u064a\u0639\u0631\u0636 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0641\u064a \u0635\u0641 \u0648\u0627\u062d\u062f \u0645\u0636\u063a\u0648\u0637\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.form-horizontal`"}, {"key": "B", "text": "`.form-inline`"}, {"key": "C", "text": "`.form-row`"}, {"key": "D", "text": "`.inline-form`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q31", "number": 31, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0633\u064a\u0627\u0642\u064a \u0644\u0644\u062f\u0644\u0627\u0644\u0629 \u0639\u0644\u0649 \"\u0646\u062c\u0627\u062d\" \u0641\u064a \u0627\u0644\u062c\u062f\u0648\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.table-primary`"}, {"key": "B", "text": "`.table-warning`"}, {"key": "C", "text": "`.table-success`"}, {"key": "D", "text": "`.table-info`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-4-q32", "number": 32, "text": "\u0645\u0627 \u0641\u0627\u0626\u062f\u0629 `.stretched-link`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u064a\u0627\u062f\u0629 \u0637\u0648\u0644 \u0627\u0644\u0631\u0627\u0628\u0637."}, {"key": "B", "text": "\u062c\u0639\u0644 \u0643\u0627\u0645\u0644 \u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062d\u0627\u0648\u064a\u0629 (Card) \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0646\u0642\u0631 \u0643\u0631\u0627\u0628\u0637."}, {"key": "C", "text": "\u0641\u062a\u062d \u0627\u0644\u0631\u0627\u0628\u0637 \u0641\u064a \u0635\u0641\u062d\u0629 \u062c\u062f\u064a\u062f\u0629."}, {"key": "D", "text": "\u062a\u063a\u064a\u064a\u0631 \u0644\u0648\u0646 \u0627\u0644\u0631\u0627\u0628\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q33", "number": 33, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u062c\u0639\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0645\u0631\u064a\u0631 \u0627\u0644\u0623\u0641\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.table-scroll`"}, {"key": "B", "text": "`.table-responsive`"}, {"key": "C", "text": "`.responsive-table`"}, {"key": "D", "text": "`.table-fluid`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q34", "number": 34, "text": "\u0641\u064a \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0623\u0641\u0642\u064a\u060c \u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u0636\u0628\u0637 \u0645\u062d\u0627\u0630\u0627\u0629 \u0627\u0644\u062a\u0633\u0645\u064a\u0627\u062a (Labels) \u0639\u0645\u0648\u062f\u064a\u0627\u064b\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.col-form-label`"}, {"key": "B", "text": "`.form-label`"}, {"key": "C", "text": "`.label-vertical`"}, {"key": "D", "text": "`.align-label`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q35", "number": 35, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 \u0627\u0644\u0643\u0644\u0627\u0633 `.disabled` \u0639\u0644\u0649 \u0627\u0644\u0632\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u062c\u0639\u0644\u0647 \u064a\u0644\u0645\u0639."}, {"key": "B", "text": "\u064a\u062c\u0639\u0644\u0647 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644 \u0644\u0644\u0646\u0642\u0631 \u0648\u0634\u0643\u0644\u0647 \u0628\u0627\u0647\u062a."}, {"key": "C", "text": "\u064a\u062c\u0639\u0644\u0647 \u0623\u0635\u063a\u0631."}, {"key": "D", "text": "\u064a\u062d\u0630\u0641\u0647."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q36", "number": 36, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u0644\u064a\u0633 \u0645\u0646 \u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0628\u0637\u0627\u0642\u0629 (Card)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.card-body`"}, {"key": "B", "text": "`.card-footer`"}, {"key": "C", "text": "`.card-input`"}, {"key": "D", "text": "`.card-title`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-4-q37", "number": 37, "text": "\u0643\u064a\u0641 \u062a\u0636\u064a\u0641 \"\u062a\u0623\u062e\u064a\u0631\u0627\u064b\" (Fade) \u0639\u0646\u062f \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0628\u064a\u0646 \u0627\u0644\u062a\u0628\u0648\u064a\u0628\u0627\u062a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0643\u0644\u0627\u0633 `.fade`"}, {"key": "B", "text": "\u0643\u0644\u0627\u0633 `.slow`"}, {"key": "C", "text": "\u062e\u0627\u0635\u064a\u0629 `delay`"}, {"key": "D", "text": "\u0644\u0627 \u064a\u0645\u0643\u0646 \u0630\u0644\u0643"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q38", "number": 38, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u062a\u0646\u0642\u0644 \u0627\u0644\u062f\u0627\u0643\u0646 (Dark Navbar)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.bg-black`"}, {"key": "B", "text": "`.navbar-dark`"}, {"key": "C", "text": "`.bg-dark`"}, {"key": "D", "text": "`.dark-navbar`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-4-q39", "number": 39, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.table-borderless` \u0648 `.table` \u0627\u0644\u0639\u0627\u062f\u064a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Borderless \u064a\u0636\u064a\u0641 \u062d\u062f\u0648\u062f\u0627\u064b."}, {"key": "B", "text": "Borderless \u064a\u0632\u064a\u0644 \u062c\u0645\u064a\u0639 \u0627\u0644\u062d\u062f\u0648\u062f."}, {"key": "C", "text": "Borderless \u064a\u062c\u0639\u0644 \u0627\u0644\u062c\u062f\u0648\u0644 \u0635\u063a\u064a\u0631\u0627\u064b."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q40", "number": 40, "text": "\u0645\u0627 \u0647\u0648 `.card-subtitle`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0639\u0646\u0648\u0627\u0646 \u0631\u0626\u064a\u0633\u064a."}, {"key": "B", "text": "\u0639\u0646\u0648\u0627\u0646 \u0641\u0631\u0639\u064a \u064a\u0638\u0647\u0631 \u062a\u062d\u062a \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0631\u0626\u064a\u0633\u064a \u0628\u0644\u0648\u0646 \u0623\u0641\u062a\u062d."}, {"key": "C", "text": "\u062a\u0630\u064a\u064a\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629."}, {"key": "D", "text": "\u0631\u0627\u0628\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q41", "number": 41, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u062c\u0645\u064a\u0639 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0646\u0645\u0648\u0630\u062c (Label + Input) \u0648\u0625\u0636\u0627\u0641\u0629 \u0647\u0627\u0645\u0634 \u0633\u0641\u0644\u064a\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.form-group`"}, {"key": "B", "text": "`.group-form`"}, {"key": "C", "text": "`.input-group`"}, {"key": "D", "text": "`.form-row`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q42", "number": 42, "text": "\u0623\u064a \u0643\u0644\u0627\u0633 \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u062c\u0639\u0644 \u0627\u0644\u0635\u0648\u0631\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u062a\u0623\u062e\u0630 \u0643\u0627\u0645\u0644 \u0639\u0631\u0636 \u0627\u0644\u0628\u0637\u0627\u0642\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.img-fluid`"}, {"key": "B", "text": "`.card-img-top` (\u0623\u0648 `.card-img`)"}, {"key": "C", "text": "`.img-full`"}, {"key": "D", "text": "`.w-100`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q43", "number": 43, "text": "\u0645\u0627 \u0647\u064a \u0648\u0638\u064a\u0641\u0629 `.navbar-toggler`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0632\u0631 \u0644\u0641\u062a\u062d \u0648\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0635\u063a\u064a\u0631\u0629."}, {"key": "B", "text": "\u062a\u063a\u064a\u064a\u0631 \u0644\u0648\u0646 \u0627\u0644\u0634\u0631\u064a\u0637."}, {"key": "C", "text": "\u0625\u0636\u0627\u0641\u0629 \u0634\u0639\u0627\u0631."}, {"key": "D", "text": "\u0631\u0628\u0637 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0627\u0639\u062f\u0629 \u0628\u064a\u0627\u0646\u0627\u062a."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q44", "number": 44, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0644\u0644\u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \"\u062a\u062d\u0630\u064a\u0631\" (Warning) \u0641\u064a \u0627\u0644\u062c\u062f\u0627\u0648\u0644 \u0648\u0627\u0644\u0623\u0632\u0631\u0627\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.danger`"}, {"key": "B", "text": "`.warning`"}, {"key": "C", "text": "`.alert`"}, {"key": "D", "text": "`.info`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q45", "number": 45, "text": "\u0643\u064a\u0641 \u064a\u0645\u0643\u0646\u0643 \u062c\u0639\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a \u0645\u062a\u0633\u0627\u0648\u064a\u0629 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u0641\u064a `.card-deck`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u062c\u0628 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u064a\u062f\u0648\u064a\u0627\u064b."}, {"key": "B", "text": "\u064a\u062d\u062f\u062b \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Flexbox."}, {"key": "C", "text": "\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633 `.h-equal`."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0645\u0643\u0646 \u0630\u0644\u0643."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q46", "number": 46, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `form-control` \u0648 `btn`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`form-control` \u0644\u0644\u062d\u0642\u0648\u0644\u060c `btn` \u0644\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "B", "text": "`form-control` \u0644\u0644\u0623\u0632\u0631\u0627\u0631\u060c `btn` \u0644\u0644\u062d\u0642\u0648\u0644."}, {"key": "C", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u0644\u0644\u0623\u0632\u0631\u0627\u0631."}, {"key": "D", "text": "\u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0647\u0645\u0627."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q47", "number": 47, "text": "\u0645\u0627 \u0627\u0644\u0643\u0644\u0627\u0633 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0644\u062c\u0639\u0644 `.nav` \u062a\u0645\u062a\u062f \u0628\u0639\u0631\u0636 \u0643\u0627\u0645\u0644 \u0648\u062a\u0648\u0632\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.nav-fill`"}, {"key": "B", "text": "`.nav-full`"}, {"key": "C", "text": "`.nav-wide`"}, {"key": "D", "text": "`.nav-stretch`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-4-q48", "number": 48, "text": "\u0645\u0627 \u0627\u0644\u0641\u0627\u0626\u062f\u0629 \u0645\u0646 `.form-control-lg`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0635\u063a\u064a\u0631\u0627\u064b."}, {"key": "B", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0643\u0628\u064a\u0631\u0627\u064b."}, {"key": "C", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637."}, {"key": "D", "text": "\u062c\u0639\u0644 \u0627\u0644\u062d\u0642\u0644 \u0625\u0644\u0632\u0627\u0645\u064a\u0627\u064b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q49", "number": 49, "text": "\u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0625\u0636\u0627\u0641\u0629 \u0631\u0627\u0628\u0637 \u062f\u0627\u062e\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629\u060c \u0623\u064a \u0643\u0644\u0627\u0633 \u062a\u0636\u064a\u0641 \u0644\u0647\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.card-url`"}, {"key": "B", "text": "`.card-link`"}, {"key": "C", "text": "`.card-a`"}, {"key": "D", "text": "`.link-card`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q50", "number": 50, "text": "\u0623\u064a\u0646 \u0646\u0636\u0639 \u0627\u0644\u0643\u0644\u0627\u0633 `.table-responsive`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062f\u0627\u062e\u0644 `<table>`."}, {"key": "B", "text": "\u062f\u0627\u062e\u0644 `<div>` \u064a\u062d\u064a\u0637 \u0628\u0640 `<table>`."}, {"key": "C", "text": "\u062f\u0627\u062e\u0644 `<tr>`."}, {"key": "D", "text": "\u062f\u0627\u062e\u0644 `<td>`."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-4-q51", "number": 51, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 `.btn-primary` \u0648 `.btn-outline-primary`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q52", "number": 52, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062e\u0637\u0648\u0627\u062a \u0644\u0625\u0646\u0634\u0627\u0621 \"\u062a\u0628\u0648\u064a\u0628\u0627\u062a \u062f\u064a\u0646\u0627\u0645\u064a\u0643\u064a\u0629\" (Dynamic Tabs) \u0641\u064a Bootstrap\u061f", "questionType": "text", "answerText": "1. \u0625\u0646\u0634\u0627\u0621 \u0642\u0627\u0626\u0645\u0629 \u062a\u0646\u0642\u0644 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `.nav-tabs` \u0648\u0625\u0636\u0627\u0641\u0629 `data-toggle=\"tab\"`. 2. \u0625\u0646\u0634\u0627\u0621 \u062d\u0627\u0648\u064a\u0629 \u0645\u062d\u062a\u0648\u0649 `.tab-content`. 3. \u0625\u0636\u0627\u0641\u0629 `.tab-pane` \u0644\u0643\u0644 \u0645\u062d\u062a\u0648\u0649 \u0645\u0639 `id` \u0641\u0631\u064a\u062f. 4. \u0631\u0628\u0637 \u0627\u0644\u0631\u0648\u0627\u0628\u0637 \u0628\u0627\u0644\u0640 `id` \u0639\u0628\u0631 `href`."}, {"id": "hci-lecture-4-q53", "number": 53, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.table-striped` \u0648 `.table-hover`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q54", "number": 54, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.card-group` \u0648 `.card-deck`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q55", "number": 55, "text": "\u0643\u064a\u0641 \u062a\u0646\u0634\u0626 \u0646\u0645\u0648\u0630\u062c\u0627\u064b \u0623\u0641\u0642\u064a\u0627\u064b (Horizontal Form)\u061f", "questionType": "text", "answerText": "1. \u0625\u0636\u0627\u0641\u0629 \u0643\u0644\u0627\u0633 `.row` \u0644\u0644\u0645\u062c\u0645\u0648\u0639\u0629 (`.form-group`). 2. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0634\u0628\u0643\u0629 (\u0645\u062b\u0644 `.col-sm-2`) \u0644\u0644\u062a\u0633\u0645\u064a\u0627\u062a. 3. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0627\u0633\u0627\u062a \u0627\u0644\u0634\u0628\u0643\u0629 (\u0645\u062b\u0644 `.col-sm-10`) \u0644\u0644\u062d\u0642\u0648\u0644. 4. \u0627\u0633\u062a\u062e\u062f\u0627\u0645 `.col-form-label` \u0644\u0644\u062a\u0633\u0645\u064a\u0627\u062a \u0644\u0645\u062d\u0627\u0630\u0627\u062a\u0647\u0627 \u0639\u0645\u0648\u062f\u064a\u0627\u064b."}, {"id": "hci-lecture-4-q56", "number": 56, "text": "\u0645\u0627 \u0647\u064a \u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0628\u0637\u0627\u0642\u0629 (Card) \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q57", "number": 57, "text": "\u0645\u0627 \u0641\u0627\u0626\u062f\u0629 `.stretched-link`\u061f", "questionType": "text", "answerText": "\u064a\u062c\u0639\u0644 \u0643\u0627\u0645\u0644 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0646\u0642\u0631 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0631\u0627\u0628\u0637 `::after` \u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u062d\u0627\u0648\u064a\u0629 \u0627\u0644\u0623\u0628 (\u0645\u0641\u064a\u062f \u0644\u0644\u0633\u064a\u0648 \u0648\u062a\u062c\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645)."}, {"id": "hci-lecture-4-q58", "number": 58, "text": "\u0627\u0634\u0631\u062d \u0645\u0641\u0647\u0648\u0645 \"\u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0645\u0636\u0645\u0646\" (Inline Form).", "questionType": "text", "answerText": "\u0647\u0648 \u0646\u0645\u0648\u0630\u062c \u064a\u062a\u0645 \u0641\u064a\u0647 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 (\u0627\u0644\u062a\u0633\u0645\u064a\u0627\u062a \u0648\u0627\u0644\u062d\u0642\u0648\u0644 \u0648\u0627\u0644\u0623\u0632\u0631\u0627\u0631) \u0641\u064a \u0635\u0641 \u0623\u0641\u0642\u064a \u0648\u0627\u062d\u062f\u060c \u0648\u064a\u0633\u062a\u062e\u062f\u0645 \u0639\u0627\u062f\u0629\u064b \u0644\u062d\u0642\u0648\u0644 \u0627\u0644\u0628\u062d\u062b \u0623\u0648 \u0646\u0645\u0627\u0630\u062c \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0627\u0644\u0628\u0633\u064a\u0637\u0629. \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0643\u0644\u0627\u0633 `.form-inline`."}, {"id": "hci-lecture-4-q59", "number": 59, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.navbar-light` \u0648 `.navbar-dark`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-4-q60", "number": 60, "text": "\u0643\u064a\u0641 \u062a\u0636\u064a\u0641 \u0623\u064a\u0642\u0648\u0646\u0629 \u062a\u062d\u0645\u064a\u0644 (Spinner) \u062f\u0627\u062e\u0644 \u0632\u0631\u061f", "questionType": "text", "answerText": "\u0628\u0648\u0636\u0639 \u0639\u0646\u0635\u0631 `<span>` \u062f\u0627\u062e\u0644 \u0627\u0644\u0632\u0631 \u0648\u0625\u0639\u0637\u0627\u0626\u0647 \u0643\u0644\u0627\u0633 `.spinner-border` \u0623\u0648 `.spinner-grow`\u060c \u0645\u0639 \u0625\u062e\u0641\u0627\u0621 \u0646\u0635 \u0627\u0644\u0632\u0631 \u0623\u0648 \u062a\u063a\u064a\u064a\u0631\u0647 \u0644\u064a\u0643\u0648\u0646 \"\u062c\u0627\u0631\u064a \u0627\u0644\u062a\u062d\u0645\u064a\u0644\"."}, {"id": "hci-lecture-5-q1", "number": 1, "text": "Regex \u0641\u064a PHP \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q2", "number": 2, "text": "\u0627\u0644\u062f\u0627\u0644\u0629 `preg_match()` \u062a\u062a\u0648\u0642\u0641 \u0639\u0646\u062f \u0623\u0648\u0644 \u062a\u0637\u0627\u0628\u0642 \u062a\u062c\u062f\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q3", "number": 3, "text": "\u0627\u0644\u0646\u0645\u0637 `[1-100]` \u064a\u0639\u0646\u064a \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 1 \u0625\u0644\u0649 100.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q4", "number": 4, "text": "\u0627\u0644\u0631\u0645\u0632 `^` \u062e\u0627\u0631\u062c \u0627\u0644\u0623\u0642\u0648\u0627\u0633 `[]` \u064a\u0639\u0646\u064a \"\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631\".", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q5", "number": 5, "text": "`\\d` \u064a\u0637\u0627\u0628\u0642 \u0623\u064a \u062d\u0631\u0641 \u0644\u064a\u0633 \u0631\u0642\u0645\u0627\u064b.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q6", "number": 6, "text": "`+` \u062a\u0639\u0646\u064a \u0635\u0641\u0631 \u0623\u0648 \u0623\u0643\u062b\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q7", "number": 7, "text": "`\\s` \u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u0627\u0644\u0628\u064a\u0636\u0627\u0621 (Space, Tab, Newline).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q8", "number": 8, "text": "\u0627\u0644\u0645\u0639\u062f\u0644 `i` \u064a\u062c\u0639\u0644 \u0627\u0644\u0628\u062d\u062b \u062d\u0633\u0627\u0633\u0627\u064b \u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0623\u062d\u0631\u0641.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q9", "number": 9, "text": "`preg_replace` \u062a\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u0628\u062d\u062b \u0648\u0627\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q10", "number": 10, "text": "`?` \u062a\u0639\u0646\u064a \u0623\u0646 \u0627\u0644\u0639\u0646\u0635\u0631 \u0627\u0644\u0633\u0627\u0628\u0642 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0638\u0647\u0631 \u0645\u0631\u062a\u064a\u0646.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q11", "number": 11, "text": "`[A-Z]` \u064a\u0637\u0627\u0628\u0642 \u0623\u064a \u062d\u0631\u0641 \u0643\u0628\u064a\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q12", "number": 12, "text": "`{2,4}` \u064a\u0639\u0646\u064a \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0645\u0631\u062a\u064a\u0646 \u0623\u0648 4 \u0645\u0631\u0627\u062a \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q13", "number": 13, "text": "`|` \u062a\u0639\u0646\u064a \"\u0623\u0648\" (OR).", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q14", "number": 14, "text": "\u0627\u0644\u0646\u0645\u0637 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0628\u064a\u0646 \u0634\u0631\u0637\u062a\u064a\u0646 `/pattern/` \u0641\u064a PHP.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q15", "number": 15, "text": "`$` \u062a\u0639\u0646\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0646\u0635.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q16", "number": 16, "text": "`[abc]` \u062a\u0637\u0627\u0628\u0642 \u0627\u0644\u0643\u0644\u0645\u0629 \"abc\" \u0628\u0627\u0644\u0643\u0627\u0645\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q17", "number": 17, "text": "`[^abc]` \u062a\u0637\u0627\u0628\u0642 \u0623\u064a \u062d\u0631\u0641 \u0639\u062f\u0627 a, b, c.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q18", "number": 18, "text": "`preg_match_all` \u062a\u0639\u064a\u062f \u0645\u0635\u0641\u0648\u0641\u0629 \u0628\u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0637\u0627\u0628\u0642\u0627\u062a.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q19", "number": 19, "text": "`\\w` \u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u062d\u0631\u0648\u0641 \u0648\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0648\u0627\u0644\u0634\u0631\u0637\u0629 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q20", "number": 20, "text": "\u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 Regex \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u064a\u063a\u0629 \u0627\u0644\u0625\u064a\u0645\u064a\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q21", "number": 21, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062f\u0627\u0644\u0629 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0646\u0645\u0637 \u0645\u0639\u064a\u0646 \u0641\u0642\u0637 (\u0646\u0639\u0645/\u0644\u0627)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`preg_replace`"}, {"key": "B", "text": "`preg_match_all`"}, {"key": "C", "text": "`preg_match`"}, {"key": "D", "text": "`preg_split`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-5-q22", "number": 22, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \u0627\u0644\u0646\u0645\u0637 `[0-9]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 0 \u0625\u0644\u0649 9."}, {"key": "B", "text": "\u0627\u0644\u0646\u0635 \"0-9\"."}, {"key": "C", "text": "\u0623\u064a \u0631\u0642\u0645 \u0639\u062f\u0627 0 \u0648 9."}, {"key": "D", "text": "\u0627\u0644\u0633\u0627\u0644\u0628 \u0648\u0627\u0644\u0635\u0641\u0631."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q23", "number": 23, "text": "\u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0639\u0646 \u0631\u0642\u0645 \u0647\u0627\u062a\u0641 \u0645\u0643\u0648\u0646 \u0645\u0646 10 \u0623\u0631\u0642\u0627\u0645 \u0628\u0627\u0644\u0636\u0628\u0637:", "questionType": "choice", "options": [{"key": "A", "text": "`\\d{10}`"}, {"key": "B", "text": "`\\d*`"}, {"key": "C", "text": "`\\d+`"}, {"key": "D", "text": "`\\d{1,10}`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q24", "number": 24, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `+` \u0648 `*`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`+` \u0635\u0641\u0631 \u0623\u0648 \u0623\u0643\u062b\u0631\u060c `*` \u0648\u0627\u062d\u062f \u0623\u0648 \u0623\u0643\u062b\u0631."}, {"key": "B", "text": "`+` \u0648\u0627\u062d\u062f \u0623\u0648 \u0623\u0643\u062b\u0631\u060c `*` \u0635\u0641\u0631 \u0623\u0648 \u0623\u0643\u062b\u0631."}, {"key": "C", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u0645\u062a\u0633\u0627\u0648\u064a."}, {"key": "D", "text": "`+` \u0644\u0644\u062c\u0645\u0639."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q25", "number": 25, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `^` \u062f\u0627\u062e\u0644 `[]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631."}, {"key": "B", "text": "\u0627\u0644\u0646\u0641\u064a (Not)."}, {"key": "C", "text": "\u0627\u0644\u0642\u0648\u0629."}, {"key": "D", "text": "\u0627\u0644\u062a\u0643\u0631\u0627\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q26", "number": 26, "text": "\u0643\u064a\u0641 \u062a\u0643\u062a\u0628 \u0646\u0645\u0637\u0627\u064b \u064a\u0642\u0628\u0644 \"color\" \u0623\u0648 \"colour\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`colou?r`"}, {"key": "B", "text": "`color|colour`"}, {"key": "C", "text": "`col(o|ou)r`"}, {"key": "D", "text": "\u062c\u0645\u064a\u0639 \u0645\u0627 \u0633\u0628\u0642 \u0635\u062d\u064a\u062d."}], "answerIndex": 3, "answerText": "D"}, {"id": "hci-lecture-5-q27", "number": 27, "text": "\u0645\u0627 \u0647\u0648 \u0646\u0627\u062a\u062c `preg_match(\"/a/\", \"A\")` \u0628\u062f\u0648\u0646 \u0645\u0639\u062f\u0644 `i`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "1"}, {"key": "B", "text": "0"}, {"key": "C", "text": "Error"}, {"key": "D", "text": "True"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q28", "number": 28, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `\\S`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0633\u0627\u0641\u0629."}, {"key": "B", "text": "\u062d\u0631\u0641 \u063a\u064a\u0631 \u0645\u0633\u0627\u0641\u0629."}, {"key": "C", "text": "\u062d\u0631\u0641 \u062e\u0627\u0635."}, {"key": "D", "text": "\u0643\u0644\u0645\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q29", "number": 29, "text": "\u0623\u064a \u0646\u0645\u0637 \u064a\u0637\u0627\u0628\u0642 \u0643\u0644\u0645\u0629 \u062a\u0628\u062f\u0623 \u0628\u062d\u0631\u0641 \u0643\u0628\u064a\u0631 \u0648\u062a\u0644\u064a\u0647\u0627 \u0623\u062d\u0631\u0641 \u0635\u063a\u064a\u0631\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`^[a-z]`"}, {"key": "B", "text": "`^[A-Z][a-z]+$`"}, {"key": "C", "text": "`[A-Z].*`"}, {"key": "D", "text": "`^[A-Z]+$`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q30", "number": 30, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `\\d` \u0648 `\\D`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\\d` \u0644\u0644\u0623\u0631\u0642\u0627\u0645\u060c `\\D` \u0644\u063a\u064a\u0631 \u0627\u0644\u0623\u0631\u0642\u0627\u0645."}, {"key": "B", "text": "\u0627\u0644\u0639\u0643\u0633."}, {"key": "C", "text": "`\\d` \u0644\u0644\u062a\u0627\u0631\u064a\u062e."}, {"key": "D", "text": "\u0644\u0627 \u0641\u0631\u0642."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q31", "number": 31, "text": "\u0645\u0627 \u0647\u064a \u0641\u0627\u0626\u062f\u0629 `{n,m}`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0645\u0646 n \u0625\u0644\u0649 m \u0645\u0631\u0627\u062a."}, {"key": "B", "text": "\u0627\u0644\u062c\u0645\u0639 \u0628\u064a\u0646 n \u0648 m."}, {"key": "C", "text": "\u0627\u062e\u062a\u064a\u0627\u0631 n \u0623\u0648 m."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0648\u062c\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q32", "number": 32, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a `$`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062f\u0648\u0644\u0627\u0631."}, {"key": "B", "text": "\u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0646\u0635."}, {"key": "C", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0646\u0635."}, {"key": "D", "text": "\u0645\u062a\u063a\u064a\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q33", "number": 33, "text": "\u0643\u064a\u0641 \u062a\u0645\u0646\u0639 \u062a\u0637\u0627\u0628\u0642 \u0646\u0635 \u064a\u0648\u062c\u062f \u0641\u064a \u0648\u0633\u0637 \u062c\u0645\u0644\u0629\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `^` \u0648 `$`."}, {"key": "B", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `*`."}, {"key": "C", "text": "\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `+`."}, {"key": "D", "text": "\u0644\u0627 \u064a\u0645\u0643\u0646."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q34", "number": 34, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0646\u0645\u0637 \u0627\u0644\u0635\u062d\u064a\u062d \u0644\u0645\u0637\u0627\u0628\u0642\u0629 \u0631\u0642\u0645 \u0645\u0646 1 \u0625\u0644\u0649 9\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`[1-9]`"}, {"key": "B", "text": "`[0-9]`"}, {"key": "C", "text": "`\\d`"}, {"key": "D", "text": "`[1-9]+`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q35", "number": 35, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `\\` \u0642\u0628\u0644 \u062d\u0631\u0641 \u062e\u0627\u0635 \u0645\u062b\u0644 `.`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0644\u063a\u0649 \u0627\u0644\u062e\u0627\u0635\u064a\u0629 \u0648\u064a\u062c\u0639\u0644\u0647 \u0646\u0642\u0637\u0629 \u0639\u0627\u062f\u064a\u0629."}, {"key": "B", "text": "\u064a\u0632\u064a\u062f \u0645\u0646 \u0642\u0648\u062a\u0647."}, {"key": "C", "text": "\u064a\u062c\u0639\u0644\u0647 \u064a\u0639\u0645\u0644 \u0643\u0640 `*`."}, {"key": "D", "text": "\u064a\u0633\u0628\u0628 \u062e\u0637\u0623."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q36", "number": 36, "text": "\u0645\u0627 \u0647\u064a \u0646\u062a\u064a\u062c\u0629 `preg_match(\"/a*b/\", \"b\")`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "0 (\u0644\u0627 \u064a\u0648\u062c\u062f \u062a\u0637\u0627\u0628\u0642)."}, {"key": "B", "text": "1 (\u062a\u0637\u0627\u0628\u0642 \u0645\u0648\u062c\u0648\u062f)."}, {"key": "C", "text": "\u062e\u0637\u0623."}, {"key": "D", "text": "`ab`."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q37", "number": 37, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `(a|b)`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0631\u0641 a \u062b\u0645 b."}, {"key": "B", "text": "\u062d\u0631\u0641 a \u0623\u0648 \u062d\u0631\u0641 b."}, {"key": "C", "text": "\u062d\u0631\u0641 ab."}, {"key": "D", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q38", "number": 38, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0637\u0627\u0628\u0642 \"carries\" \u0648 \"car\" \u0648 \"carry\"\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`car(r|ri|ries)?`"}, {"key": "B", "text": "`car*`"}, {"key": "C", "text": "`car+`"}, {"key": "D", "text": "`car?`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q39", "number": 39, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0645\u0639\u062f\u0644 \u0627\u0644\u0630\u064a \u064a\u0633\u0645\u062d \u0628\u0627\u0644\u0628\u062d\u062b \u0641\u064a \u0633\u0637\u0648\u0631 \u0645\u062a\u0639\u062f\u062f\u0629 (Multiline)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`i`"}, {"key": "B", "text": "`m`"}, {"key": "C", "text": "`u`"}, {"key": "D", "text": "`s`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q40", "number": 40, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `{5}`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0645\u0646 1 \u0625\u0644\u0649 5."}, {"key": "B", "text": "\u0628\u0627\u0644\u0636\u0628\u0637 5 \u0645\u0631\u0627\u062a."}, {"key": "C", "text": "\u0623\u0643\u062b\u0631 \u0645\u0646 5."}, {"key": "D", "text": "\u0623\u0642\u0644 \u0645\u0646 5."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q41", "number": 41, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `.` \u0648 `\\.`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`.` \u0623\u064a \u062d\u0631\u0641\u060c `\\.` \u0646\u0642\u0637\u0629 \u062d\u0642\u064a\u0642\u064a\u0629."}, {"key": "B", "text": "`\\.` \u0623\u064a \u062d\u0631\u0641\u060c `.` \u0646\u0642\u0637\u0629."}, {"key": "C", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "D", "text": "\u0643\u0644\u0627\u0647\u0645\u0627 \u0646\u0642\u0637\u0629."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q42", "number": 42, "text": "\u0643\u064a\u0641 \u062a\u0637\u0627\u0628\u0642 \u0646\u0635 \u064a\u0628\u062f\u0648 \u0643\u062a\u0627\u0631\u064a\u062e (YYYY-MM-DD)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\\d\\d-\\d\\d-\\d\\d\\d\\d`"}, {"key": "B", "text": "`\\d{4}-\\d{2}-\\d{2}`"}, {"key": "C", "text": "`[0-9]-[0-9]-[0-9]`"}, {"key": "D", "text": "`Date`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q43", "number": 43, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u064a\u062f `preg_match` \u0639\u0646\u062f \u0627\u0644\u0641\u0634\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`null`"}, {"key": "B", "text": "`false` \u0623\u0648 `0`."}, {"key": "C", "text": "`-1`"}, {"key": "D", "text": "\u0646\u0635 \u0641\u0627\u0631\u063a."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q44", "number": 44, "text": "\u0645\u0627 \u0647\u064a \u0648\u0638\u064a\u0641\u0629 `preg_split`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062f\u0645\u062c \u0627\u0644\u0646\u0635\u0648\u0635."}, {"key": "B", "text": "\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0645\u0635\u0641\u0648\u0641\u0629 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0646\u0645\u0637."}, {"key": "C", "text": "\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0646\u0635."}, {"key": "D", "text": "\u0627\u0644\u0628\u062d\u062b."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q45", "number": 45, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `[a-zA-Z]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0631\u0648\u0641 \u0635\u063a\u064a\u0631\u0629 \u0641\u0642\u0637."}, {"key": "B", "text": "\u062d\u0631\u0648\u0641 \u0643\u0628\u064a\u0631\u0629 \u0641\u0642\u0637."}, {"key": "C", "text": "\u0623\u064a \u062d\u0631\u0641 \u0625\u0646\u062c\u0644\u064a\u0632\u064a \u0643\u0628\u064a\u0631 \u0623\u0648 \u0635\u063a\u064a\u0631."}, {"key": "D", "text": "\u0623\u0631\u0642\u0627\u0645."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-5-q46", "number": 46, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0640 Delimiter \u0627\u0644\u0642\u064a\u0627\u0633\u064a \u0641\u064a PHP Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`#`"}, {"key": "B", "text": "`~`"}, {"key": "C", "text": "`/`"}, {"key": "D", "text": "\u062c\u0645\u064a\u0639 \u0645\u0627 \u0633\u0628\u0642 \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u060c \u0644\u0643\u0646 `/` \u0647\u0648 \u0627\u0644\u0623\u0634\u0647\u0631."}], "answerIndex": 3, "answerText": "D"}, {"id": "hci-lecture-5-q47", "number": 47, "text": "\u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0646\u0645\u0637 `^a$`\u060c \u0645\u0627\u0630\u0627 \u064a\u0637\u0627\u0628\u0642\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0623\u064a \u0646\u0635 \u064a\u062d\u062a\u0648\u064a \u0639\u0644\u0649 a."}, {"key": "B", "text": "\u0627\u0644\u0646\u0635 \"a\" \u0641\u0642\u0637."}, {"key": "C", "text": "\u0646\u0635 \u064a\u0628\u062f\u0623 \u0628\u0640 a."}, {"key": "D", "text": "\u0646\u0635 \u064a\u0646\u062a\u0647\u064a \u0628\u0640 a."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q48", "number": 48, "text": "\u0645\u0627\u0630\u0627 \u062a\u0639\u0646\u064a `\\w`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Whitespace."}, {"key": "B", "text": "Word Character (\u062d\u0631\u0648\u0641\u060c \u0623\u0631\u0642\u0627\u0645\u060c _)."}, {"key": "C", "text": "Wide."}, {"key": "D", "text": "Without."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q49", "number": 49, "text": "\u0645\u0627 \u0647\u064a \u0646\u062a\u064a\u062c\u0629 `preg_match(\"/a{2,}/\", \"aaaa\")`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0637\u0627\u0628\u0642 (\u0644\u0623\u0646 a \u062a\u0643\u0631\u0631\u062a 4 \u0645\u0631\u0627\u062a \u0648\u0647\u0648 \u0623\u0643\u0628\u0631 \u0645\u0646 2)."}, {"key": "B", "text": "\u0641\u0634\u0644."}, {"key": "C", "text": "\u062e\u0637\u0623."}, {"key": "D", "text": "\u064a\u0637\u0627\u0628\u0642 \u062d\u0631\u0641\u064a\u0646 \u0641\u0642\u0637."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-5-q50", "number": 50, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 `[^\\d]`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0631\u0642\u0645."}, {"key": "B", "text": "\u0644\u064a\u0633 \u0631\u0642\u0645\u0627\u064b."}, {"key": "C", "text": "\u0646\u0642\u0637\u0629."}, {"key": "D", "text": "\u062d\u0631\u0641 d."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-5-q51", "number": 51, "text": "\u0639\u0631\u0641 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0642\u064a\u0627\u0633\u064a (Regex).", "questionType": "text", "answerText": "\u0647\u0648 \u0633\u0644\u0633\u0644\u0629 \u0645\u0646 \u0627\u0644\u0623\u062d\u0631\u0641 \u0648\u0627\u0644\u0631\u0645\u0648\u0632 \u0627\u0644\u062a\u064a \u062a\u0645\u062b\u0644 \u0646\u0645\u0637\u0627\u064b \u0644\u0644\u0628\u062d\u062b \u062f\u0627\u062e\u0644 \u0627\u0644\u0646\u0635\u0648\u0635\u060c \u062a\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u062a\u062d\u0642\u0642\u060c \u0627\u0644\u0628\u062d\u062b\u060c \u0627\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644\u060c \u0648\u0627\u0644\u062a\u0642\u0633\u064a\u0645."}, {"id": "hci-lecture-5-q52", "number": 52, "text": "\u0642\u0627\u0631\u0646 \u0628\u064a\u0646 `preg_match` \u0648 `preg_match_all`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q53", "number": 53, "text": "\u0627\u0634\u0631\u062d \u0648\u0638\u064a\u0641\u0629 \u0627\u0644\u0631\u0645\u0648\u0632 \u0627\u0644\u062a\u0627\u0644\u064a\u0629: `^`, `$`, `|`.", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q54", "number": 54, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `+` \u0648 `*` \u0648 `?`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q55", "number": 55, "text": "\u0644\u0645\u0627\u0630\u0627 \u0627\u0644\u0646\u0645\u0637 `[1-100]` \u062e\u0627\u0637\u0626 \u0644\u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 1 \u0625\u0644\u0649 100\u061f", "questionType": "text", "answerText": "\u0644\u0623\u0646 Regex \u064a\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 \u0627\u0644\u0623\u062d\u0631\u0641 \u0648\u0644\u064a\u0633 \u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629. `[1-100]` \u062a\u0639\u0646\u064a \u062d\u0631\u0641\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 {1, 0}\u060c \u0644\u0623\u0646 \u0627\u0644\u0646\u0637\u0627\u0642 `1-1` \u063a\u064a\u0631 \u0645\u0646\u0637\u0642\u064a \u0648\u0627\u0644\u0640 `00` \u0645\u062c\u0631\u062f \u062a\u0643\u0631\u0627\u0631. \u0627\u0644\u062d\u0644 \u0627\u0644\u0635\u062d\u064a\u062d \u0647\u0648 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0646\u0637\u0642 \u0627\u0644\u0628\u0631\u0645\u062c\u0629: `^([1-9]|[1-9][0-9]|100)$`."}, {"id": "hci-lecture-5-q56", "number": 56, "text": "\u0627\u0643\u062a\u0628 \u0646\u0645\u0637\u0627\u064b \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062a\u062a\u0643\u0648\u0646 \u0645\u0646 6 \u0623\u062d\u0631\u0641 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644.", "questionType": "text", "answerText": "`^.{6,}$`."}, {"id": "hci-lecture-5-q57", "number": 57, "text": "\u0645\u0627 \u0647\u064a \u0648\u0638\u064a\u0641\u0629 `\\s` \u0648 `\\S`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q58", "number": 58, "text": "\u0643\u064a\u0641 \u062a\u0633\u062a\u062e\u062f\u0645 `preg_replace` \u0644\u062d\u0630\u0641 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 \u0646\u0635\u061f", "questionType": "text", "answerText": "\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0646\u0645\u0637 \u0627\u0644\u0628\u062d\u062b `\\d` \u0648\u0627\u0633\u062a\u0628\u062f\u0627\u0644\u0647 \u0628\u0646\u0635 \u0641\u0627\u0631\u063a `\"\"`."}, {"id": "hci-lecture-5-q59", "number": 59, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `[abc]` \u0648 `(abc)`\u061f", "questionType": "text", "answerText": ""}, {"id": "hci-lecture-5-q60", "number": 60, "text": "\u0627\u0634\u0631\u062d \u0627\u0644\u0645\u0639\u062f\u0644 `i` \u0645\u0639 \u0645\u062b\u0627\u0644.", "questionType": "text", "answerText": "\u064a\u062c\u0639\u0644 \u0627\u0644\u0628\u062d\u062b \u063a\u064a\u0631 \u062d\u0633\u0627\u0633 \u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0623\u062d\u0631\u0641."}, {"id": "hci-lecture-6-q1", "number": 1, "text": "`filter_var` \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647\u0627 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0625\u064a\u0645\u064a\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q2", "number": 2, "text": "`FILTER_SANITIZE_EMAIL` \u062a\u062d\u0630\u0641 \u062d\u0631\u0641 `@` \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u064a\u0644.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q3", "number": 3, "text": "\u0627\u0644\u062a\u062d\u0642\u0642 (Validation) \u064a\u063a\u064a\u0631 \u0627\u0644\u0646\u0635\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u062a\u0639\u0642\u064a\u0645 (Sanitization) \u064a\u0631\u0641\u0636\u0647 \u0623\u0648 \u064a\u0642\u0628\u0644\u0647.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q4", "number": 4, "text": "`FILTER_VALIDATE_URL` \u062a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0631\u0627\u0628\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q5", "number": 5, "text": "`FILTER_FLAG_QUERY_REQUIRED` \u062a\u0634\u062a\u0631\u0637 \u0648\u062c\u0648\u062f `?` \u0641\u064a \u0627\u0644\u0631\u0627\u0628\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q6", "number": 6, "text": "\u0641\u064a C#\u060c `Regex.IsMatch` \u062a\u0639\u064a\u062f \u0645\u0635\u0641\u0648\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q7", "number": 7, "text": "`Regex.Replace` \u0641\u064a C# \u062a\u0633\u062a\u062e\u062f\u0645 \u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0646\u0645\u0637 \u0628\u0646\u0635 \u0622\u062e\u0631.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q8", "number": 8, "text": "`\\d` \u0641\u064a C# \u062a\u0639\u0646\u064a \u0634\u064a\u0626\u0627\u064b \u0645\u062e\u062a\u0644\u0641\u0627\u064b \u0639\u0646 `\\d` \u0641\u064a PHP.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q9", "number": 9, "text": "`FILTER_SANITIZE_URL` \u062a\u0633\u0645\u062d \u0628\u0648\u062c\u0648\u062f \u0627\u0644\u0631\u0645\u0648\u0632 `$` \u0648 `_` \u0641\u064a \u0627\u0644\u0631\u0627\u0628\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q10", "number": 10, "text": "`Regex.Split` \u062a\u0642\u0633\u0645 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0645\u0635\u0641\u0648\u0641\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q11", "number": 11, "text": "`FILTER_VALIDATE_IP` \u062a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0639\u0646\u0648\u0627\u0646 IP.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q12", "number": 12, "text": "\u0644\u0627 \u064a\u0645\u0643\u0646 \u062f\u0645\u062c \u0639\u062f\u0629 Flags \u0641\u064a `filter_var`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q13", "number": 13, "text": "`FILTER_SANITIZE_STRING` \u062a\u0632\u064a\u0644 \u0627\u0644\u062a\u0627\u062c\u0627\u062a (Tags) \u0645\u0646 \u0627\u0644\u0646\u0635.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q14", "number": 14, "text": "\u0627\u0644\u0646\u0645\u0637 `\\d{2}` \u064a\u0637\u0627\u0628\u0642 \u0631\u0642\u0645\u064a\u0646 \u0628\u0627\u0644\u0636\u0628\u0637 \u0641\u064a C#.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q15", "number": 15, "text": "`filter_var` \u062a\u0639\u0648\u062f \u0628\u0640 `false` \u0639\u0646\u062f \u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q16", "number": 16, "text": "`Regex.Match` \u062a\u0639\u064a\u062f \u0623\u0648\u0644 \u062a\u0637\u0627\u0628\u0642 \u0641\u0642\u0637.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q17", "number": 17, "text": "\u0627\u0644\u062a\u0639\u0642\u064a\u0645 (Sanitization) \u0644\u0627 \u064a\u062d\u0645\u064a \u0645\u0646 SQL Injection \u0628\u062d\u062f \u0630\u0627\u062a\u0647\u060c \u0628\u0644 \u0647\u0648 \u062e\u0637\u0648\u0629 \u0645\u0633\u0627\u0639\u062f\u0629.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q18", "number": 18, "text": "\u0627\u0644\u0646\u0645\u0637 `\\.(jpg|png)` \u0641\u064a C# \u064a\u0637\u0627\u0628\u0642 \u0627\u0645\u062a\u062f\u0627\u062f jpg \u0623\u0648 png.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q19", "number": 19, "text": "`FILTER_FLAG_HOST_REQUIRED` \u062a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u0636\u064a\u0641.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q20", "number": 20, "text": "\u0644\u0627 \u062d\u0627\u062c\u0629 \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 `@` \u0642\u0628\u0644 \u0627\u0644\u0646\u0635 \u0641\u064a C# Regex \u0644\u0643\u0646\u0647\u0627 \u062a\u0641\u0636\u0644 \u0644\u062a\u062c\u0646\u0628 \u0645\u0634\u0627\u0643\u0644 `\\`.", "questionType": "choice", "options": [{"key": "A", "text": "\u0635\u062d"}, {"key": "B", "text": "\u062e\u0637\u0623"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q21", "number": 21, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0641\u0644\u062a\u0631 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0644\u062a\u0646\u0638\u064a\u0641 \u0627\u0644\u0625\u064a\u0645\u064a\u0644\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_VALIDATE_EMAIL`"}, {"key": "B", "text": "`FILTER_SANITIZE_EMAIL`"}, {"key": "C", "text": "`FILTER_CLEAN_EMAIL`"}, {"key": "D", "text": "`FILTER_EMAIL`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q22", "number": 22, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062f\u0627\u0644\u0629 \u0641\u064a C# \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0646\u0645\u0637 (Boolean)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`Regex.Match`"}, {"key": "B", "text": "`Regex.Matches`"}, {"key": "C", "text": "`Regex.IsMatch`"}, {"key": "D", "text": "`Regex.Check`"}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-6-q23", "number": 23, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `FILTER_VALIDATE_EMAIL` \u0645\u0639 \u0627\u0644\u0625\u064a\u0645\u064a\u0644 \u0627\u0644\u062e\u0627\u0637\u0626\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0635\u0644\u062d\u0647."}, {"key": "B", "text": "\u064a\u0639\u064a\u062f `false`."}, {"key": "C", "text": "\u064a\u062d\u0630\u0641\u0647."}, {"key": "D", "text": "\u064a\u0631\u0645\u064a \u0627\u0633\u062a\u062b\u0646\u0627\u0621."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q24", "number": 24, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 `\\d{2,4}` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0631\u0642\u0645\u064a\u0646."}, {"key": "B", "text": "4 \u0623\u0631\u0642\u0627\u0645."}, {"key": "C", "text": "\u0645\u0646 2 \u0625\u0644\u0649 4 \u0623\u0631\u0642\u0627\u0645."}, {"key": "D", "text": "\u0631\u0642\u0645\u064a\u0646 \u0645\u0641\u0635\u0648\u0644\u064a\u0646 \u0628\u0641\u0627\u0635\u0644\u0629."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-6-q25", "number": 25, "text": "\u0643\u064a\u0641 \u062a\u062c\u0628\u0631 \u0627\u0644\u0631\u0627\u0628\u0637 \u0639\u0644\u0649 \u0627\u062d\u062a\u0648\u0627\u0621 Query String\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_FLAG_QUERY_REQUIRED`"}, {"key": "B", "text": "`FILTER_FLAG_PATH_REQUIRED`"}, {"key": "C", "text": "`FILTER_FLAG_URL_REQUIRED`"}, {"key": "D", "text": "`FILTER_FLAG_STRING_REQUIRED`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q26", "number": 26, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0623\u062d\u0631\u0641 \u0627\u0644\u062a\u064a \u062a\u062d\u0630\u0641\u0647\u0627 `FILTER_SANITIZE_URL`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u0631\u0642\u0627\u0645."}, {"key": "B", "text": "\u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629."}, {"key": "C", "text": "\u0627\u0644\u0623\u062d\u0631\u0641 \u063a\u064a\u0631 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 (\u0645\u062b\u0644 \u0627\u0644\u0623\u0642\u0648\u0627\u0633 \u063a\u064a\u0631 \u0627\u0644\u0645\u0633\u0645\u0648\u062d\u0629)."}, {"key": "D", "text": "\u0627\u0644\u0646\u0642\u0627\u0637 \u0648\u0627\u0644\u0634\u0631\u0637\u0627\u062a."}], "answerIndex": 2, "answerText": "C"}, {"id": "hci-lecture-6-q27", "number": 27, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `Regex.Match` \u0648 `Regex.Matches` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u0639\u064a\u062f \u0643\u0644 \u0627\u0644\u062a\u0637\u0627\u0628\u0642\u0627\u062a\u060c \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u062a\u0637\u0627\u0628\u0642 \u0648\u0627\u062d\u062f."}, {"key": "B", "text": "\u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u0639\u064a\u062f \u0623\u0648\u0644 \u062a\u0637\u0627\u0628\u0642\u060c \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0643\u0644 \u0627\u0644\u062a\u0637\u0627\u0628\u0642\u0627\u062a."}, {"key": "C", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "D", "text": "\u0627\u0644\u0623\u0648\u0644\u0649 \u0644\u0644\u062a\u062d\u0642\u0642\u060c \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0644\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q28", "number": 28, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `Validation` \u0648 `Sanitization`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Validation \u062a\u0646\u0638\u0641\u060c Sanitization \u062a\u062a\u062d\u0642\u0642."}, {"key": "B", "text": "Validation \u062a\u062a\u062d\u0642\u0642 (\u062a\u0642\u0628\u0644/\u062a\u0631\u0641\u0636)\u060c Sanitization \u062a\u0646\u0638\u0641 (\u062a\u0632\u064a\u0644/\u062a\u0639\u062f\u0644)."}, {"key": "C", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "D", "text": "Validation \u0644\u0644\u0623\u0631\u0642\u0627\u0645 \u0641\u0642\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q29", "number": 29, "text": "\u0623\u064a \u0641\u0644\u062a\u0631 \u064a\u062a\u062d\u0642\u0642 \u0645\u0646 \u0648\u062c\u0648\u062f \u0639\u0646\u0648\u0627\u0646 IP\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_VALIDATE_IP`"}, {"key": "B", "text": "`FILTER_VALIDATE_URL`"}, {"key": "C", "text": "`FILTER_VALIDATE_EMAIL`"}, {"key": "D", "text": "`FILTER_VALIDATE_INT`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q30", "number": 30, "text": "\u0645\u0627 \u0647\u0648 \u062f\u0648\u0631 \u0627\u0644\u0631\u0645\u0632 `@` \u0642\u0628\u0644 \u0627\u0644\u0646\u0635 \u0641\u064a C# Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0644\u0644\u0625\u0634\u0627\u0631\u0629 \u0644\u0644\u062e\u0637\u0623."}, {"key": "B", "text": "\u0644\u062c\u0639\u0644 \u0627\u0644\u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u0646\u0635\u064a\u0629 (String) \u062a\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 `\\` \u0643\u062d\u0631\u0641 \u0639\u0627\u062f\u064a (Verbatim)."}, {"key": "C", "text": "\u0644\u062a\u0639\u0644\u064a\u0642 \u0627\u0644\u0643\u0648\u062f."}, {"key": "D", "text": "\u0644\u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0646\u0645\u0637."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q31", "number": 31, "text": "\u0625\u0630\u0627 \u0623\u0631\u062f\u062a \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0643\u0644 \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u0641\u064a \u0646\u0635 \u0628\u0646\u062c\u0645\u0629 \u0641\u064a C#\u060c \u0645\u0627\u0630\u0627 \u062a\u0633\u062a\u062e\u062f\u0645\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`Regex.IsMatch`"}, {"key": "B", "text": "`Regex.Replace`"}, {"key": "C", "text": "`Regex.Split`"}, {"key": "D", "text": "`Regex.Space`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q32", "number": 32, "text": "\u0645\u0627 \u0646\u0627\u062a\u062c `filter_var(\"user@example.com\", FILTER_VALIDATE_EMAIL)`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\"user@example.com\"`"}, {"key": "B", "text": "`true`"}, {"key": "C", "text": "`false`"}, {"key": "D", "text": "`null`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q33", "number": 33, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `\\s` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0648\u0642\u0641 \u0627\u0644\u0628\u062d\u062b."}, {"key": "B", "text": "\u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0627\u0644\u0628\u064a\u0636\u0627\u0621."}, {"key": "C", "text": "\u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u062d\u0631\u0641 s."}, {"key": "D", "text": "\u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0635\u063a\u064a\u0631\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q34", "number": 34, "text": "\u0645\u0627 \u0647\u0648 \u0627\u0644\u0646\u0645\u0637 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0635\u0648\u0631\u0629 \u0628\u0627\u0645\u062a\u062f\u0627\u062f `jpg` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`*.jpg`"}, {"key": "B", "text": "`\\.jpg$`"}, {"key": "C", "text": "`jpg`"}, {"key": "D", "text": "`.jpg`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q35", "number": 35, "text": "\u0643\u064a\u0641 \u062a\u0646\u0634\u0626 Regex \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`new Regex()`"}, {"key": "B", "text": "`Regex.Create()`"}, {"key": "C", "text": "`Regex.Init()`"}, {"key": "D", "text": "`new Reg()`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q36", "number": 36, "text": "\u0645\u0627 \u0627\u0644\u0641\u0627\u0626\u062f\u0629 \u0645\u0646 `Regex.Split`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0642\u0637\u0639 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0646\u0635\u0641\u064a\u0646."}, {"key": "B", "text": "\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u0646\u0635 \u0625\u0644\u0649 \u0645\u0635\u0641\u0648\u0641\u0629 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0646\u0645\u0637 \u0641\u0627\u0635\u0644."}, {"key": "C", "text": "\u062f\u0645\u062c \u0627\u0644\u0646\u0635\u0648\u0635."}, {"key": "D", "text": "\u062d\u0630\u0641 \u0623\u062c\u0632\u0627\u0621 \u0645\u0646 \u0627\u0644\u0646\u0635."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q37", "number": 37, "text": "\u0645\u0627\u0630\u0627 \u064a\u062d\u062f\u062b \u0644\u0648 \u0643\u0627\u0646 \u0627\u0644\u0646\u0635 `http://example` \u0645\u0639 `FILTER_FLAG_PATH_REQUIRED`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u0642\u0628\u0644\u0647."}, {"key": "B", "text": "\u064a\u0631\u0641\u0636\u0647 (false) \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0633\u0627\u0631 `/path`."}, {"key": "C", "text": "\u064a\u0636\u064a\u0641 `/` \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b."}, {"key": "D", "text": "\u064a\u062d\u0630\u0641 \u0627\u0644\u062f\u0648\u0645\u064a\u0646."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q38", "number": 38, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u0639\u0627\u062f\u0629 \u0645\u0646 `filter_var` \u0639\u0646\u062f \u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`0`"}, {"key": "B", "text": "`false`"}, {"key": "C", "text": "`null`"}, {"key": "D", "text": "`-1`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q39", "number": 39, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0645\u0643\u062a\u0628\u0629 \u0627\u0644\u062a\u064a \u064a\u062c\u0628 \u0627\u0633\u062a\u064a\u0631\u0627\u062f\u0647\u0627 \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 Regex \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`System.IO`"}, {"key": "B", "text": "`System.Text.RegularExpressions`"}, {"key": "C", "text": "`System.Net`"}, {"key": "D", "text": "`System.Web`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q40", "number": 40, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062a\u0628\u0631 \"\u0627\u0644\u062a\u062d\u0642\u0642\" (Validation)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0630\u0641 \u0627\u0644\u0645\u0633\u0627\u0641\u0627\u062a \u0627\u0644\u0632\u0627\u0626\u062f\u0629."}, {"key": "B", "text": "\u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0623\u0646 \u0627\u0644\u0639\u0645\u0631 \u0623\u0643\u0628\u0631 \u0645\u0646 18."}, {"key": "C", "text": "\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0646\u0635 \u0644\u0623\u062d\u0631\u0641 \u0635\u063a\u064a\u0631\u0629."}, {"key": "D", "text": "\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0640 HTML Tags."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q41", "number": 41, "text": "\u0623\u064a \u0645\u0646 \u0627\u0644\u062a\u0627\u0644\u064a \u064a\u0639\u062a\u0628\u0631 \"\u062a\u0639\u0642\u064a\u0645\" (Sanitization)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0625\u064a\u0645\u064a\u0644."}, {"key": "B", "text": "\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0634\u0631\u0637\u0627\u062a \u0627\u0644\u0645\u0627\u0626\u0644\u0629 `/` \u0645\u0646 \u0646\u0635."}, {"key": "C", "text": "\u0645\u0642\u0627\u0631\u0646\u0629 \u0643\u0644\u0645\u062a\u064a\u0646."}, {"key": "D", "text": "\u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0637\u0648\u0644 \u0627\u0644\u0646\u0635."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q42", "number": 42, "text": "\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a `\\w` \u0641\u064a C# Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "Whitespace."}, {"key": "B", "text": "Word character."}, {"key": "C", "text": "Wildcard."}, {"key": "D", "text": "Web."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q43", "number": 43, "text": "\u0643\u064a\u0641 \u062a\u0633\u062a\u062e\u062f\u0645 Regex \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u0646\u0633\u064a\u0642 \u062a\u0627\u0631\u064a\u062e (Day-Month-Year)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`\\d-\\d-\\d`"}, {"key": "B", "text": "`\\d{2}-\\d{2}-\\d{4}`"}, {"key": "C", "text": "`Date`"}, {"key": "D", "text": "`[0-9]-[0-9]-[0-9]`"}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q44", "number": 44, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u0641\u0627\u0626\u062f\u0629 \u0627\u0644\u0623\u0645\u0646\u064a\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0644\u0644\u062a\u0639\u0642\u064a\u0645 (Sanitization)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062a\u0633\u0631\u064a\u0639 \u0627\u0644\u0645\u0648\u0642\u0639."}, {"key": "B", "text": "\u0645\u0646\u0639 \u062d\u0642\u0646 \u0627\u0644\u0623\u0643\u0648\u0627\u062f (Injection Attacks)."}, {"key": "C", "text": "\u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u0634\u0643\u0644."}, {"key": "D", "text": "\u062a\u0642\u0644\u064a\u0644 \u062d\u062c\u0645 \u0627\u0644\u0645\u0644\u0641."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q45", "number": 45, "text": "\u0627\u0644\u0631\u0645\u0632 `|` \u0641\u064a C# Regex \u064a\u0639\u0646\u064a:", "questionType": "choice", "options": [{"key": "A", "text": "AND."}, {"key": "B", "text": "OR."}, {"key": "C", "text": "NOT."}, {"key": "D", "text": "Concatenation."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q46", "number": 46, "text": "\u0645\u0627\u0630\u0627 \u064a\u0641\u0639\u0644 `FILTER_SANITIZE_STRING`\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u064a\u062d\u0648\u0644 \u0627\u0644\u0646\u0635 \u0644\u0623\u0631\u0642\u0627\u0645."}, {"key": "B", "text": "\u064a\u0632\u064a\u0644 \u0627\u0644\u062a\u0627\u062c\u0627\u062a (Tags) \u0648\u062a\u0631\u0645\u0632 \u0627\u0644\u0623\u062d\u0631\u0641 \u0627\u0644\u062e\u0627\u0635\u0629."}, {"key": "C", "text": "\u064a\u0636\u064a\u0641 \u0646\u0635\u0627\u064b."}, {"key": "D", "text": "\u064a\u062d\u0630\u0641 \u0627\u0644\u0623\u0631\u0642\u0627\u0645."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q47", "number": 47, "text": "\u0645\u0627 \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 `Match` \u0648 `MatchCollection` \u0641\u064a C#\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`Match` \u0646\u062a\u064a\u062c\u0629 \u0648\u0627\u062d\u062f\u0629\u060c `MatchCollection` \u0645\u062c\u0645\u0648\u0639\u0629 \u0646\u062a\u0627\u0626\u062c."}, {"key": "B", "text": "\u0644\u0627 \u0641\u0631\u0642."}, {"key": "C", "text": "`Match` \u0644\u0644\u0628\u062d\u062b\u060c `MatchCollection` \u0644\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644."}, {"key": "D", "text": "`Match` \u0623\u0633\u0631\u0639."}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q48", "number": 48, "text": "\u0623\u064a \u0641\u0644\u062a\u0631 \u064a\u0633\u062a\u062e\u062f\u0645 \u0644\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0623\u0646 \u0627\u0644\u0642\u064a\u0645\u0629 \u0639\u062f\u062f \u0635\u062d\u064a\u062d (Integer)\u061f", "questionType": "choice", "options": [{"key": "A", "text": "`FILTER_VALIDATE_INT`"}, {"key": "B", "text": "`FILTER_VALIDATE_NUMBER`"}, {"key": "C", "text": "`FILTER_SANITIZE_INT`"}, {"key": "D", "text": "`FILTER_CHECK_INT`"}], "answerIndex": 0, "answerText": "A"}, {"id": "hci-lecture-6-q49", "number": 49, "text": "\u0645\u0627 \u0645\u0639\u0646\u0649 \u0627\u0644\u0646\u0645\u0637 `\\b` \u0641\u064a Regex\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u062d\u0631\u0641 b."}, {"key": "B", "text": "\u062d\u062f\u0648\u062f \u0627\u0644\u0643\u0644\u0645\u0629 (Word Boundary)."}, {"key": "C", "text": "\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0637\u0631."}, {"key": "D", "text": "\u0645\u0633\u0627\u0641\u0629 \u062e\u0644\u0641\u064a\u0629."}], "answerIndex": 1, "answerText": "B"}, {"id": "hci-lecture-6-q50", "number": 50, "text": "\u0645\u0627 \u0647\u064a \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0645\u062f\u062e\u0644\u0627\u062a \u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u064a PHP\u061f", "questionType": "choice", "options": [{"key": "A", "text": "\u0627\u0644\u062a\u062d\u0642\u0642 \u062b\u0645 \u0627\u0644\u062a\u0639\u0642\u064a\u0645."}, {"key": "B", "text": "\u0627\u0644\u062a\u0639\u0642\u064a\u0645 \u062b\u0645 \u0627\u0644\u062a\u062d\u0642\u0642."}, {"key": "C", "text": "\u0627\u0644\u062d\u0641\u0638 \u0645\u0628\u0627\u0634\u0631\u0629."}, {"key": "D", "text": "\u0627\u0644\u0637\u0628\u0627\u0639\u0629."}], "answerIndex": 1, "answerText": "B"}]}]};
